// Ściąga CLF-C02: usługi i pojęcia z kursu (nazwa, opis PL, opis EN). Strona: materialy/sciaga.html
window.CLF_SCIAGA = [
{"name": "AWS Shared Responsibility Model / Model współdzielonej odpowiedzialności", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 1, "pl": "Podział obowiązków bezpieczeństwa między AWS a klienta. AWS odpowiada za bezpieczeństwo CHMURY (security OF the cloud): sprzęt, oprogramowanie infrastruktury, sieć i obiekty fizyczne. Klient odpowiada za bezpieczeństwo W CHMURZE (security IN the cloud): swoje dane, dostęp do nich i konfigurację usług. Granica przesuwa się zależnie od usługi – im bardziej zarządzana usługa, tym mniej obowiązków klienta.", "en": "A model that divides security duties between AWS and the customer. AWS is responsible for security OF the cloud (hardware, software, networking and facilities that run AWS services). The customer is responsible for security IN the cloud (their data, who can access it and how services are configured). The split shifts depending on the service used."},
{"name": "Benefit from massive economies of scale / Korzyści skali", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 1, "pl": "Jedna z sześciu zalet chmury AWS. Dzięki ogromnej globalnej infrastrukturze AWS (setki tysięcy klientów) koszt jednostkowy jest niższy – jak przy zakupach hurtowych. Małe firmy mają dostęp do technologii, które wcześniej były dostępne tylko dla dużych korporacji.", "en": "One of the six benefits of the AWS Cloud. Like buying in bulk lowers the unit price, the vast global infrastructure of AWS results in lower costs for customers. Businesses big and small can access advanced technologies previously available only to large enterprises."},
{"name": "Client/server model / Model klient–serwer", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 2, "pl": "Podstawowy model działania aplikacji: klient (np. przeglądarka) wysyła żądanie do serwera, serwer wykonuje pracę i odsyła odpowiedź. W kursie zilustrowany kawiarnią – klient zamawia, barista realizuje zamówienie. W AWS rolę serwera pełni np. instancja Amazon EC2.", "en": "The basic model of how applications work: a client (such as a web browser) sends a request to a server, the server does some work and sends back a response. The course illustrates it with a coffee shop. In AWS, the server can be an Amazon EC2 instance."},
{"name": "Cloud computing / Przetwarzanie w chmurze", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 1, "pl": "Dostarczanie zasobów IT na żądanie przez internet z płatnością za faktyczne użycie (pay-as-you-go). Zasoby – serwery, pamięć masowa, bazy danych, sieci, narzędzia AI/ML – są dostępne w kilka sekund i można je zwiększać lub zmniejszać według potrzeb. Nie kupujesz ani nie utrzymujesz własnego sprzętu.", "en": "The on-demand delivery of IT resources over the internet with pay-as-you-go pricing. Resources such as servers, storage, databases, networking and AI/ML tools are available within seconds and can be scaled up or down as needed. You don't buy or maintain local hardware."},
{"name": "Cloud-based deployment / Wdrożenie w chmurze", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 1, "pl": "Model wdrożenia, w którym cała aplikacja działa w chmurze. Możesz przenieść do chmury istniejące zasoby, budować w niej nowe aplikacje albo łączyć oba podejścia. Przykład: firma migruje dane do chmury i buduje aplikację z serwerów wirtualnych, baz danych i komponentów sieciowych hostowanych w całości w AWS.", "en": "A deployment model in which the application runs entirely in the cloud. You can migrate existing resources, design and build new applications in the cloud, or combine both. For example, a company migrates its data and builds an application made of virtual servers, databases and networking components hosted entirely in AWS."},
{"name": "Elasticity / Elastyczność", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 2, "pl": "Zdolność do automatycznego zwiększania i zmniejszania zasobów w odpowiedzi na bieżące zapotrzebowanie. Skalowalność to potencjał wzrostu w czasie, a elastyczność to dynamiczne dostosowywanie „tu i teraz” – skalowanie wszerz w szczycie i zwijanie, gdy ruch spada. Zapewnia optymalne koszty.", "en": "The ability to automatically scale resources up or down in response to real-time demand: scaling out during peaks and scaling in when demand decreases. Scalability is about potential growth over time, whereas elasticity is dynamic, on-demand adjustment. It provides cost efficiency."},
{"name": "Fault tolerance / Odporność na awarie", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 1, "pl": "Zdolność systemu do dalszego działania mimo awarii pojedynczego komponentu. Strefy dostępności AWS są od siebie odizolowane i mają niezależne zasilanie, sieć i łączność, więc redundancja między AZ zapewnia odporność na awarie. Ściśle powiązana z wysoką dostępnością.", "en": "The ability of a system to keep working even when a component fails. AWS Availability Zones are isolated, each with independent power, networking and connectivity, so redundancy across AZs provides fault tolerance. It is closely related to high availability."},
{"name": "Fully managed services / Usługi w pełni zarządzane", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 3, "pl": "Usługi, w których nie zarządzasz żadnymi serwerami – AWS obsługuje infrastrukturę, skalowanie, dostępność i poprawki. Ty odpowiadasz głównie za swój kod lub dane oraz za kontrolę dostępu. Przykłady: AWS Lambda, AWS Fargate, Amazon DynamoDB.", "en": "Services where you don't provision or manage any servers; AWS handles the infrastructure, scaling, availability and patching. You remain responsible mainly for your code or data and access controls. Examples: AWS Lambda, AWS Fargate, Amazon DynamoDB."},
{"name": "Go global in minutes / Globalny zasięg w kilka minut", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 1, "pl": "Jedna z sześciu zalet chmury AWS. Aby działać w innych krajach, nie budujesz własnej infrastruktury – wdrażasz aplikacje w wielu Regionach AWS w kilka minut. Użytkownicy na całym świecie dostają niższe opóźnienia przy minimalnym koszcie.", "en": "One of the six benefits of the AWS Cloud. You don't need to set up your own infrastructure to expand internationally; you can deploy applications and services across multiple AWS Regions in minutes, giving global users lower latency."},
{"name": "High availability / Wysoka dostępność", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 1, "pl": "Zdolność systemu do nieprzerwanego działania z minimalnymi przestojami. W AWS osiąga się ją, rozkładając zasoby na wiele Stref dostępności (AZ), a dla jeszcze większej odporności – na wiele Regionów. Gdy jedna AZ ma awarię, aplikacja działa dalej w pozostałych.", "en": "The ability of a system to keep operating with minimal downtime. In AWS you achieve it by distributing resources across multiple Availability Zones and, for even more resilience, multiple Regions. If one AZ has an outage, the application continues to run in the others."},
{"name": "Horizontal scaling (scale out) / Skalowanie poziome", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 2, "pl": "Dodawanie kolejnych maszyn do puli, aby więcej pracy wykonywać równolegle (scale out), i usuwanie ich, gdy obciążenie spada (scale in). Tak działa Amazon EC2 Auto Scaling. Zwiększa też dostępność, bo awaria jednej instancji nie zatrzymuje systemu.", "en": "Adding more resources to the pool so more work can be done in parallel (scale out), and removing them when demand drops (scale in). This is how Amazon EC2 Auto Scaling works. It also improves availability because one failed instance doesn't stop the system."},
{"name": "Hybrid deployment / Wdrożenie hybrydowe", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 1, "pl": "Zasoby w chmurze i infrastruktura on-premises działają razem. Dobre rozwiązanie, gdy starsze aplikacje muszą zostać lokalnie ze względu na utrzymanie lub regulacje, a np. analityka działa już w chmurze. Wdrożenia multi-cloud (u kilku dostawców) też można uznać za hybrydowe.", "en": "Cloud-based resources and on-premises infrastructure work together. It is ideal when legacy applications must remain on premises for maintenance or regulatory reasons, while cloud services handle, for example, data processing and analytics. Multi-cloud deployments can also be considered hybrid."},
{"name": "Hypervisor", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 2, "pl": "Oprogramowanie działające na fizycznym hoście, które tworzy maszyny wirtualne, dzieli między nie zasoby i izoluje je od siebie. Za warstwę hypervisora w AWS odpowiada AWS (część „bezpieczeństwa chmury”). Maszyny wirtualne z hypervisorem uruchamiają pełne, osobne systemy operacyjne, dlatego są cięższe od kontenerów.", "en": "Software running on the physical host machine that creates virtual machines, shares resources between them and isolates them from each other. AWS is responsible for the hypervisor layer (security of the cloud). VMs run full, separate operating systems, so they are heavier than containers."},
{"name": "Increase speed and agility / Większa szybkość i zwinność", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 1, "pl": "Jedna z sześciu zalet chmury AWS. Nowe zasoby i aplikacje wdrażasz w minuty zamiast tygodni. Skraca to czas wejścia na rynek (time to market) i pozwala szybciej reagować na zmiany potrzeb biznesowych i sytuacji rynkowej.", "en": "One of the six benefits of the AWS Cloud. You can rapidly deploy applications and services, accelerating time to market and responding more quickly to changing business needs and market conditions."},
{"name": "Managed services / Usługi zarządzane", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 3, "pl": "Usługi, w których AWS przejmuje większość pracy operacyjnej (np. sprzęt, poprawki, kopie zapasowe), ale Ty nadal konfigurujesz część ustawień – opcje wdrożenia, skalowanie, środowisko lub parametry bazy. Przykłady: AWS Elastic Beanstalk, Amazon RDS.", "en": "Services where AWS handles much of the operational overhead (such as hardware, patching and backups), but you still configure some settings such as deployment options, scaling and environment or database configuration. Examples: AWS Elastic Beanstalk, Amazon RDS."},
{"name": "Multi-tenancy / Wielodostępność", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 2, "pl": "Sytuacja, w której wiele maszyn wirtualnych (często różnych klientów) współdzieli ten sam fizyczny serwer-host. Każda VM jest odizolowana od pozostałych, mimo że korzysta z zasobów tego samego hosta. W EC2 izolacją zarządza AWS (przez hypervisor), więc klient nie musi się tym zajmować.", "en": "When multiple virtual machines, often from different customers, share the same underlying physical host. Each VM is isolated from the others while still sharing the host's resources. For EC2, AWS manages the host, the hypervisor and the isolation between instances."},
{"name": "On-premises deployment / Wdrożenie on-premises (lokalne)", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 1, "pl": "Zasoby wdrożone we własnym centrum danych z użyciem wirtualizacji i narzędzi do zarządzania zasobami. Nie daje większości zalet chmury, ale bywa wybierane ze względu na dedykowane zasoby i niskie opóźnienia. Często nazywane też prywatną chmurą (private cloud) – w praktyce to klasyczna infrastruktura IT.", "en": "Resources deployed in your own data center by using virtualization and resource management tools. It doesn't provide many of the benefits of cloud computing, but is sometimes chosen for dedicated resources and low latency. In most cases it is the same as legacy IT infrastructure (sometimes called a private cloud)."},
{"name": "Scalability / Skalowalność", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 2, "pl": "Zdolność systemu do obsługi rosnącego obciążenia przez dodawanie zasobów. Dotyczy długoterminowego planowania pojemności, tak aby system mógł rosnąć razem z liczbą użytkowników. Można skalować w górę (mocniejsze maszyny) albo wszerz (więcej maszyn).", "en": "The ability of a system to handle an increased load by adding resources. It focuses on long-term capacity planning so the system can grow to accommodate more users or workloads. You can scale up (more power) or scale out (more machines)."},
{"name": "Security IN the cloud (customer responsibility) / Bezpieczeństwo w chmurze – po stronie klienta", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 1, "pl": "Część modelu współdzielonej odpowiedzialności należąca do klienta. Klient zarządza swoimi danymi (co przechowuje w AWS), tym, kto ma do nich dostęp i jak dostęp jest przyznawany oraz odbierany, a także szyfrowaniem po stronie klienta. Przy EC2 dochodzi m.in. system operacyjny gościa, poprawki, aplikacje i grupy zabezpieczeń.", "en": "The customer part of the shared responsibility model. Customers manage the security of their data (what they store in AWS), who has access to it and how access is granted, managed and revoked, plus client-side encryption. For EC2 this also includes the guest OS, patching, applications and security groups."},
{"name": "Security OF the cloud (AWS responsibility) / Bezpieczeństwo chmury – po stronie AWS", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 1, "pl": "Część modelu współdzielonej odpowiedzialności należąca do AWS. Obejmuje ochronę infrastruktury, na której działają wszystkie usługi: centra danych i obiekty fizyczne, sprzęt, sieć globalną oraz warstwę wirtualizacji (hypervisor). Klient nie może i nie musi np. zabezpieczać fizycznego centrum danych.", "en": "The AWS part of the shared responsibility model. AWS protects the infrastructure that runs all AWS Cloud services: hardware, software, networking and facilities, including the physical, network and hypervisor layers. Customers don't need to secure the physical data centers."},
{"name": "Software as a service (SaaS) / Oprogramowanie jako usługa", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 13, "pl": "Model, w którym aplikacje są hostowane w chmurze i dostępne przez internet, bez lokalnej instalacji i utrzymania po stronie klienta. Przejście z tradycyjnej licencji na SaaS to strategia migracji Repurchase, a oferty SaaS można też kupować w AWS Marketplace.", "en": "A model in which applications are hosted in the cloud and accessed over the internet, with no local installation or maintenance by the customer. Moving from a traditional license to SaaS is the Repurchase migration strategy, and SaaS offerings can also be bought in AWS Marketplace."},
{"name": "Stop guessing capacity / Koniec ze zgadywaniem pojemności", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 1, "pl": "Jedna z sześciu zalet chmury AWS. Zasoby skalujesz dynamicznie w górę i w dół zależnie od bieżącego zapotrzebowania. Nie kupujesz za dużo infrastruktury „na zapas” ani nie ryzykujesz, że zabraknie jej w szczycie.", "en": "One of the six benefits of the AWS Cloud. You can dynamically scale resources up or down based on real-time demand, so you achieve optimal performance without provisioning more or less infrastructure than you need."},
{"name": "Stop spending money running and maintaining data centers / Koniec z utrzymywaniem centrów danych", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 1, "pl": "Jedna z sześciu zalet chmury AWS. Nie musisz inwestować w fizyczne centra danych, media ani ich bieżące utrzymanie – tym zajmuje się AWS. Zespół i budżet możesz przeznaczyć na inicjatywy strategiczne, które wyróżniają Twoją firmę, zamiast na „dźwiganie sprzętu”.", "en": "One of the six benefits of the AWS Cloud. You don't need to invest in physical data centers, utilities and ongoing maintenance because AWS takes care of the physical infrastructure. Your resources can be reallocated to more strategic initiatives."},
{"name": "Trade fixed expense for variable expense / Koszty zmienne zamiast stałych", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 1, "pl": "Pierwsza z sześciu zalet chmury AWS. Zamiast inwestować z góry w centra danych i serwery (koszty stałe, CapEx), płacisz tylko za to, czego używasz (koszty zmienne, OpEx). Wydatki są lepiej dopasowane do faktycznego użycia, co daje większą elastyczność finansową.", "en": "One of the six benefits of the AWS Cloud. Instead of investing upfront in data centers and servers (fixed expense), you pay only for what you use (variable expense). Expenses are better aligned with actual usage, creating more financial flexibility."},
{"name": "Unmanaged services / Usługi niezarządzane", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 3, "pl": "Usługi, w których AWS dba tylko o fizyczną infrastrukturę, a Ty konfigurujesz, zabezpieczasz i utrzymujesz system operacyjny, sieć i aplikacje. Przykład: Amazon EC2 albo baza MySQL zainstalowana samodzielnie na instancji EC2. Najwięcej kontroli i najwięcej obowiązków.", "en": "Services where AWS takes care of the physical infrastructure, while you set up, secure and maintain the operating system, network configuration and applications. Example: Amazon EC2, or MySQL installed directly on an EC2 instance. Most control and most responsibility."},
{"name": "Vertical scaling (scale up) / Skalowanie pionowe", "category": "Koncepcje chmury", "kind": "pojęcie", "module": 2, "pl": "Zwiększanie mocy istniejącej maszyny, np. zmiana instancji EC2 na większy typ z większą liczbą CPU i pamięci. Proste, ale ograniczone maksymalnym rozmiarem maszyny i zwykle wymaga ponownego uruchomienia.", "en": "Adding more power to existing machines, for example resizing an EC2 instance to a larger instance type with more CPU and memory. Simple, but limited by the maximum machine size."},
{"name": "Availability Zone (AZ) / Strefa dostępności", "category": "Infrastruktura globalna", "kind": "pojęcie", "module": 4, "pl": "Strefa dostępności to odrębna lokalizacja w Regionie, złożona z jednego lub kilku centrów danych z niezależnym zasilaniem, siecią i łącznością, umieszczonych w osobnych obiektach. Strefy w Regionie są połączone łączami o niskim opóźnieniu. Uruchamianie zasobów w co najmniej dwóch AZ (multi-AZ) to podstawowa dobra praktyka wysokiej dostępności – awaria jednej strefy nie zatrzymuje aplikacji.", "en": "An Availability Zone is a distinct location within a Region made up of one or more data centers with independent power, networking and connectivity, housed in separate facilities. AZs in a Region are connected with low-latency links. Running resources in at least two AZs (multi-AZ) is the basic best practice for high availability – the failure of one AZ does not take your application down."},
{"name": "AWS Global Infrastructure / Globalna infrastruktura AWS", "category": "Infrastruktura globalna", "kind": "pojęcie", "module": 4, "pl": "Fizyczna sieć AWS na całym świecie: Regiony, strefy dostępności (AZ) i lokalizacje brzegowe (edge locations) połączone prywatną siecią AWS. Pozwala wdrażać aplikacje blisko użytkowników, osiągać wysoką dostępność i spełniać wymagania dotyczące lokalizacji danych. Hierarchia do zapamiętania: Region → co najmniej 3 AZ → co najmniej jedno centrum danych w każdej AZ; lokalizacje brzegowe działają poza Regionami.", "en": "The worldwide physical footprint of AWS: Regions, Availability Zones (AZs) and edge locations connected by the AWS global network. It lets you deploy applications close to users, achieve high availability and meet data residency requirements. Hierarchy to remember: Region → three or more AZs → one or more data centers per AZ; edge locations sit outside Regions."},
{"name": "AWS GovCloud (US)", "category": "Infrastruktura globalna", "kind": "pojęcie", "module": 4, "pl": "Odizolowane Regiony AWS w USA zaprojektowane dla amerykańskich agencji rządowych i ich wykonawców. Mają rygorystyczne fizyczne, operacyjne i kadrowe mechanizmy bezpieczeństwa, aby spełnić wymagania przepisów rządowych. Przykład na to, że dostępność funkcji i zgodność z przepisami zależą od wybranego Regionu.", "en": "Isolated AWS Regions in the US designed for US government agencies and their contractors. They have stringent physical, operational and personnel security controls to meet government regulatory requirements. An example of how feature availability and compliance depend on the Region you choose."},
{"name": "AWS Region / Region AWS", "category": "Infrastruktura globalna", "kind": "pojęcie", "module": 4, "pl": "Region to odrębny obszar geograficzny, złożony z wielu odizolowanych od siebie stref dostępności – każdy Region ma co najmniej trzy AZ. Regiony są od siebie niezależne, więc problem w jednym nie wpływa na inne, a dane nie opuszczają Regionu, dopóki sam ich nie przeniesiesz. Region wybierasz przy tworzeniu większości zasobów; wdrożenie w wielu Regionach (multi-Region) chroni przed awarią całego Regionu.", "en": "A Region is a separate geographic area made up of multiple isolated Availability Zones – each Region has three or more AZs. Regions are independent of each other, so a problem in one does not affect the others, and data stays in a Region unless you explicitly move it. You pick a Region for most resources; a multi-Region deployment protects you from the failure of an entire Region."},
{"name": "Choosing a Region / Kryteria wyboru Regionu", "category": "Infrastruktura globalna", "kind": "pojęcie", "module": 4, "pl": "Cztery główne kryteria: 1) zgodność z przepisami (compliance) – np. RODO (GDPR) albo przepisy o suwerenności danych wymagające przechowywania ich w danym kraju; 2) bliskość użytkowników – mniejsze opóźnienia (latency); 3) dostępność usług i funkcji – nie każdy Region oferuje wszystkie usługi AWS; 4) ceny – koszty działania i podatki różnią się między Regionami. Wymogi prawne są zwykle kryterium nadrzędnym.", "en": "Four key considerations: 1) compliance – e.g. GDPR or data sovereignty laws that require data to stay in a country; 2) proximity to users – lower latency; 3) feature availability – not every Region offers every AWS service; 4) pricing – operating costs and taxes differ between Regions. Compliance requirements usually come first."},
{"name": "Data residency and data sovereignty / Lokalizacja i suwerenność danych", "category": "Infrastruktura globalna", "kind": "pojęcie", "module": 4, "pl": "Wymóg, aby dane były przechowywane i przetwarzane w określonym kraju lub obszarze geograficznym, wynikający z przepisów (np. RODO) lub polityki firmy. W AWS spełniasz go, wybierając odpowiedni Region – dane nie opuszczają Regionu, dopóki sam ich nie przeniesiesz – albo rozwiązania lokalne, takie jak AWS Outposts i Amazon S3 on Outposts. Wpływa zarówno na zgodność z przepisami, jak i na koszty.", "en": "The requirement that data be stored and processed in a specific country or geographic area, driven by regulations (such as GDPR) or company policy. On AWS you meet it by choosing the right Region – data stays in a Region unless you move it – or with on-premises options such as AWS Outposts and Amazon S3 on Outposts. It affects both compliance and cost."},
{"name": "Edge location / Lokalizacja brzegowa", "category": "Infrastruktura globalna", "kind": "pojęcie", "module": 4, "pl": "Mniejsze obiekty AWS rozmieszczone poza Regionami, bliżej użytkowników, w których buforowane są (cache) obrazy, filmy i inne treści, aby trafiały do odbiorców z mniejszym opóźnieniem. Działają w nich usługi brzegowe, takie jak Amazon CloudFront (CDN), Amazon Route 53 i AWS Global Accelerator. Lokalizacji brzegowych jest znacznie więcej niż Regionów.", "en": "Smaller AWS sites located outside Regions, closer to end users, that cache images, videos and other content so it can be delivered with lower latency. They run edge services such as Amazon CloudFront (CDN), Amazon Route 53 and AWS Global Accelerator. There are many more edge locations than Regions."},
{"name": "Multi-AZ and multi-Region deployment / Wdrożenie w wielu AZ i wielu Regionach", "category": "Infrastruktura globalna", "kind": "pojęcie", "module": 4, "pl": "Multi-AZ to rozmieszczenie kopii zasobów w kilku strefach dostępności jednego Regionu – chroni przed awarią pojedynczej AZ (np. dwie podsieci w dwóch AZ za load balancerem). Multi-Region idzie dalej: aplikacja działa w kilku Regionach, więc przy awarii całego Regionu ruch można przełączyć (failover) do innego, a użytkownicy na różnych kontynentach dostają mniejsze opóźnienia. Multi-Region jest droższe i bardziej złożone, więc stosuje się je dla systemów krytycznych lub globalnych.", "en": "Multi-AZ means placing copies of resources in several Availability Zones of one Region – it protects against the failure of a single AZ (for example, two subnets in two AZs behind a load balancer). Multi-Region goes further: the application runs in several Regions, so if a whole Region is disrupted you can fail over to another, and users on different continents get lower latency. Multi-Region is more costly and complex, so it is used for critical or global systems."},
{"name": "Accelerated computing instances / Instancje z akceleracją obliczeń", "category": "Moc obliczeniowa", "kind": "pojęcie", "module": 2, "pl": "Rodzina instancji EC2 z akceleratorami sprzętowymi, np. procesorami graficznymi (GPU). Wydajnie wykonuje obliczenia zmiennoprzecinkowe, przetwarzanie grafiki i uczenie maszynowe.", "en": "An EC2 instance family that uses hardware accelerators such as graphics processing units (GPUs) to efficiently handle floating-point calculations, graphics processing and machine learning."},
{"name": "Amazon EC2 Auto Scaling", "category": "Moc obliczeniowa", "kind": "usługa", "module": 2, "pl": "Usługa automatycznie dodająca i usuwająca instancje EC2 zależnie od zapotrzebowania aplikacji, co poprawia dostępność i obniża koszty. Skalowanie dynamiczne reaguje na zmiany w czasie rzeczywistym, a predykcyjne z wyprzedzeniem planuje liczbę instancji na podstawie prognozowanego ruchu. Działa w parze z Elastic Load Balancing.", "en": "Automatically adds or removes EC2 instances based on changes in application demand, improving availability and reducing cost. Dynamic scaling responds to real-time changes, while predictive scaling schedules the right number of instances in advance based on anticipated demand. It works together with Elastic Load Balancing."},
{"name": "Amazon EC2 Capacity Reservations / Rezerwacje pojemności", "category": "Moc obliczeniowa", "kind": "pojęcie", "module": 2, "pl": "Rezerwacja mocy obliczeniowej EC2 w konkretnej Strefie dostępności dla krytycznych obciążeń, które muszą mieć zagwarantowaną pojemność. Płacisz stawkę On-Demand za zarezerwowaną pojemność niezależnie od tego, czy ją wykorzystujesz. Nie daje rabatu – daje pewność dostępności.", "en": "Reserves EC2 compute capacity in a specific Availability Zone for business-critical workloads with strict capacity requirements. Reservations are charged at the On-Demand rate whether used or not. It guarantees capacity rather than providing a discount."},
{"name": "Amazon Elastic Compute Cloud (Amazon EC2)", "category": "Moc obliczeniowa", "kind": "usługa", "module": 2, "pl": "Usługa dająca skalowalną moc obliczeniową w postaci serwerów wirtualnych (instancji) w chmurze. Instancje uruchamiasz, skalujesz i zatrzymujesz w minuty i płacisz tylko za czas działania. EC2 to usługa niezarządzana (unmanaged): AWS dba o sprzęt i hypervisor, a Ty o system operacyjny gościa, poprawki, aplikacje i grupy zabezpieczeń. Łączysz się przez SSH (Linux), RDP (Windows) lub AWS Systems Manager.", "en": "A service that provides secure, resizable compute capacity as virtual servers (instances) in the cloud. You can launch, scale and terminate instances within minutes and pay only for active usage. EC2 is an unmanaged service: AWS handles the hardware and hypervisor, while you manage the guest OS, updates, applications and security groups. You connect with SSH (Linux), RDP (Windows) or AWS Systems Manager."},
{"name": "Amazon Lightsail", "category": "Moc obliczeniowa", "kind": "usługa", "module": 3, "pl": "Uproszczona usługa chmurowa oferująca wirtualne serwery prywatne (VPS), pamięć masową, bazy danych i sieć w przewidywalnej, miesięcznej cenie. Dla małych firm, prostych stron i blogów, środowisk testowych i nauki chmury – bez złożoności pełnej konsoli AWS.", "en": "A simplified cloud service offering virtual private servers (VPSs), storage, databases and networking at a predictable monthly price. Ideal for small businesses, basic web applications, low-traffic websites, blogs, dev/test environments and learning, without the complexity of the full AWS console."},
{"name": "Amazon Machine Image (AMI)", "category": "Moc obliczeniowa", "kind": "pojęcie", "module": 2, "pl": "Gotowy obraz maszyny wirtualnej potrzebny do uruchomienia instancji EC2: system operacyjny, konfiguracja pamięci masowej, architektura, uprawnienia do uruchamiania i dodatkowe oprogramowanie. Z jednego AMI uruchomisz wiele identycznych instancji, co zapewnia powtarzalność przy skalowaniu. AMI możesz zbudować sam, użyć gotowego od AWS albo kupić w AWS Marketplace.", "en": "A pre-built virtual machine image used to launch EC2 instances. It includes the operating system, storage setup, architecture type, launch permissions and any extra software. One AMI can launch many identical instances, providing repeatability when scaling. You can build a custom AMI, use an AWS-provided AMI or buy one in AWS Marketplace."},
{"name": "Auto Scaling group (minimum / desired / maximum capacity)", "category": "Moc obliczeniowa", "kind": "pojęcie", "module": 2, "pl": "Zbiór instancji EC2 skalowany razem. Minimum – najmniejsza liczba instancji, poniżej której grupa nigdy nie zejdzie (uruchamiana od razu po utworzeniu). Desired (pożądana) – liczba, którą grupa stara się utrzymać; domyślnie równa minimum. Maximum – górny limit chroniący przed nadmiernym skalowaniem i kosztami.", "en": "A collection of EC2 instances that scale in or out together. Minimum capacity is the least number of instances, launched immediately after creation. Desired capacity is the number Auto Scaling aims to maintain and defaults to the minimum. Maximum capacity is the upper limit that prevents over-scaling and controls costs."},
{"name": "AWS Batch", "category": "Moc obliczeniowa", "kind": "usługa", "module": 3, "pl": "W pełni zarządzana usługa do uruchamiania obciążeń wsadowych (batch) w AWS. Sama planuje zadania, przydziela i skaluje zasoby obliczeniowe zależnie od ich wymagań. Do dużych, równoległych zadań: obliczeń naukowych, analizy ryzyka finansowego, transkodowania multimediów, trenowania ML i badań genomowych.", "en": "A fully managed service for running batch computing workloads on AWS. It automatically schedules, manages and scales compute resources for batch jobs based on their requirements. Good for large-scale parallel workloads such as scientific computing, financial risk analysis, media transcoding, ML training and genomics."},
{"name": "AWS Elastic Beanstalk", "category": "Moc obliczeniowa", "kind": "usługa", "module": 3, "pl": "Usługa upraszczająca wdrażanie, zarządzanie i skalowanie aplikacji webowych. Przesyłasz kod, a Elastic Beanstalk automatycznie tworzy infrastrukturę (EC2, równoważenie obciążenia, skalowanie) i monitoruje stan aplikacji. Obsługuje m.in. Java, .NET, Python, Node.js i Docker, a Ty zachowujesz pełną kontrolę nad zasobami pod spodem.", "en": "A service that streamlines deploying, managing and scaling web applications. You upload your code and Elastic Beanstalk automatically handles infrastructure provisioning, scaling, load balancing and health monitoring. It supports Java, .NET, Python, Node.js, Docker and more, while you keep full control over the underlying resources."},
{"name": "AWS Outposts", "category": "Moc obliczeniowa", "kind": "usługa", "module": 3, "pl": "W pełni zarządzane rozwiązanie chmury hybrydowej, które przenosi infrastrukturę i usługi AWS (moc obliczeniową, pamięć masową, sieć) do Twojego własnego centrum danych. Daje spójne doświadczenie on-premises i w chmurze AWS. Dla aplikacji wymagających niskich opóźnień, lokalnego przetwarzania danych oraz wymogów regulacyjnych i rezydencji danych.", "en": "A fully managed hybrid cloud solution that extends AWS infrastructure and services (compute, storage and networking) to your on-premises data centers, providing a consistent experience between on premises and the AWS Cloud. Good for low-latency applications, local data processing and data residency or regulatory requirements."},
{"name": "Compute optimized instances / Instancje zoptymalizowane pod obliczenia", "category": "Moc obliczeniowa", "kind": "pojęcie", "module": 2, "pl": "Rodzina instancji EC2 z wydajnymi procesorami do zadań intensywnych obliczeniowo: serwerów gier, obliczeń wysokiej wydajności (HPC), uczenia maszynowego i modelowania naukowego.", "en": "An EC2 instance family for compute-intensive tasks such as gaming servers, high performance computing (HPC), machine learning and scientific modeling."},
{"name": "Dedicated Hosts / Hosty dedykowane", "category": "Moc obliczeniowa", "kind": "pojęcie", "module": 2, "pl": "Cały fizyczny serwer EC2 zarezerwowany wyłącznie dla Ciebie, z pełną kontrolą nad rozmieszczeniem instancji i przydziałem zasobów. Wybierany przy rygorystycznych wymaganiach bezpieczeństwa, zgodności lub licencji powiązanych z serwerem (np. licencje per gniazdo/rdzeń). To najdroższa opcja.", "en": "An entire physical EC2 server reserved for your exclusive use, with full control over instance placement and resource allocation. Chosen for strict security, compliance or server-bound licensing requirements. It is the most expensive option."},
{"name": "Dedicated Instances / Instancje dedykowane", "category": "Moc obliczeniowa", "kind": "pojęcie", "module": 2, "pl": "Instancje działające na sprzęcie przeznaczonym tylko dla Twojego konta, odizolowane fizycznie od innych klientów AWS. Różnica względem Dedicated Hosts: nie wybierasz i nie kontrolujesz konkretnego serwera fizycznego, na którym działają.", "en": "Instances that run on hardware dedicated solely to your account, physically isolated from other AWS customers. The key difference from Dedicated Hosts is that you don't choose or control which physical server they run on."},
{"name": "Dynamic scaling vs predictive scaling / Skalowanie dynamiczne i predykcyjne", "category": "Moc obliczeniowa", "kind": "pojęcie", "module": 2, "pl": "Dwa podejścia Amazon EC2 Auto Scaling. Skalowanie dynamiczne reaguje na bieżące zmiany obciążenia (np. wzrost użycia CPU). Skalowanie predykcyjne na podstawie prognozy zapotrzebowania uruchamia instancje z wyprzedzeniem, zanim nastąpi szczyt.", "en": "The two approaches of Amazon EC2 Auto Scaling. Dynamic scaling responds in real time to fluctuations in demand. Predictive scaling preemptively schedules the right number of instances based on anticipated demand."},
{"name": "EC2 instance type / Typ instancji EC2", "category": "Moc obliczeniowa", "kind": "pojęcie", "module": 2, "pl": "Określa sprzęt instancji: liczbę procesorów, pamięć, wydajność sieci i pamięci masowej. Typy są pogrupowane w rodziny (np. ogólnego przeznaczenia, zoptymalizowane pod obliczenia, pamięć, pamięć masową, akcelerowane), a nazwa typu składa się z rodziny i rozmiaru (np. m5.large). Wybór właściwego typu wpływa na wydajność i koszt.", "en": "Determines the hardware of an instance: CPU, memory, network and storage performance. Instance types are grouped into families (general purpose, compute optimized, memory optimized, storage optimized, accelerated computing), and each name combines the family and the size (for example, m5.large)."},
{"name": "Elastic Load Balancing (ELB)", "category": "Moc obliczeniowa", "kind": "usługa", "module": 2, "pl": "Usługa automatycznie rozdzielająca przychodzący ruch aplikacji na wiele zasobów, np. instancji EC2, co poprawia wydajność i niezawodność. Load balancer jest jednym punktem wejścia dla ruchu do grupy Auto Scaling i sam skaluje się z ruchem. Oddziela (decoupling) warstwę front-end od back-end i przekierowuje ruch z niesprawnych instancji.", "en": "Automatically distributes incoming application traffic across multiple resources, such as EC2 instances, to optimize performance and reliability. The load balancer is the single point of contact for traffic to an Auto Scaling group and scales automatically with traffic. It decouples front-end and backend tiers and handles failover."},
{"name": "ELB routing methods / Metody routingu ruchu", "category": "Moc obliczeniowa", "kind": "pojęcie", "module": 2, "pl": "Sposoby rozdzielania ruchu omawiane w kursie: Round Robin (po kolei, cyklicznie na wszystkie serwery), Least Connections (do serwera z najmniejszą liczbą aktywnych połączeń), IP Hash (ten sam klient zawsze trafia na ten sam serwer na podstawie adresu IP) i Least Response Time (do serwera, który odpowiada najszybciej).", "en": "Traffic distribution methods covered in the course: Round Robin (cyclically across all servers), Least Connections (to the server with the fewest active connections), IP Hash (the client's IP address consistently routes to the same server) and Least Response Time (to the fastest-responding server)."},
{"name": "General purpose instances / Instancje ogólnego przeznaczenia", "category": "Moc obliczeniowa", "kind": "pojęcie", "module": 2, "pl": "Rodzina instancji EC2 ze zrównoważonym stosunkiem mocy obliczeniowej, pamięci i sieci. Dobre dla różnorodnych obciążeń: serwerów WWW, repozytoriów kodu i sytuacji, gdy nie wiadomo jeszcze, jakie będzie obciążenie.", "en": "An EC2 instance family with a balanced mix of compute, memory and networking resources. Ideal for diverse workloads such as web servers and code repositories, and when workload performance is uncertain."},
{"name": "Memory optimized instances / Instancje zoptymalizowane pod pamięć", "category": "Moc obliczeniowa", "kind": "pojęcie", "module": 2, "pl": "Rodzina instancji EC2 do zadań wymagających dużo pamięci RAM: przetwarzania dużych zbiorów danych w pamięci, analityki danych i baz danych. Zapewnia szybką pracę obciążeń, które trzymają dużo danych w pamięci.", "en": "An EC2 instance family for memory-intensive tasks such as processing large datasets in memory, data analytics and databases. It provides fast performance for memory-heavy workloads."},
{"name": "On-Demand Instances / Instancje na żądanie", "category": "Moc obliczeniowa", "kind": "pojęcie", "module": 2, "pl": "Opcja cenowa EC2: płacisz za faktycznie użytą moc obliczeniową, bez opłat z góry i bez długoterminowych zobowiązań. Najlepsza dla krótkich, nieregularnych lub nieprzewidywalnych obciążeń, testów i nowych aplikacji. To cena bazowa, od której liczy się rabaty innych opcji.", "en": "An EC2 pricing option where you pay only for the compute capacity you consume, with no upfront payments or long-term commitments. Best for short-term, irregular or unpredictable workloads, testing and new applications. It is the baseline price for other discounts."},
{"name": "Reserved Instances (RI) / Instancje zarezerwowane", "category": "Moc obliczeniowa", "kind": "pojęcie", "module": 2, "pl": "Opcja cenowa EC2 z rabatem do 75% względem On-Demand w zamian za zobowiązanie na 1 lub 3 lata dla określonej rodziny instancji i Regionu. Dla stabilnych, przewidywalnych obciążeń. Elastyczność RI: rabat automatycznie obejmuje inne rozmiary w tej samej rodzinie oraz wiele Stref dostępności w Regionie.", "en": "An EC2 pricing option with savings of up to 75% compared to On-Demand in exchange for a 1-year or 3-year commitment to specific instance families and Regions. Good for steady-state, predictable workloads. RI flexibility applies the discount across instance sizes in the same family and across Availability Zones in the Region."},
{"name": "Savings Plans", "category": "Moc obliczeniowa", "kind": "pojęcie", "module": 2, "pl": "Model cenowy z rabatem do 72% w zamian za zobowiązanie do stałego wydatku na moc obliczeniową (w $ na godzinę) przez 1 lub 3 lata. W odróżnieniu od RI jest elastyczny – obejmuje Amazon EC2, AWS Fargate, AWS Lambda i Amazon SageMaker AI niezależnie od typu instancji i Regionu. Płatność: całość z góry, część z góry lub bez opłaty z góry.", "en": "A pricing model with savings of up to 72% in exchange for a commitment to a consistent amount of compute usage (measured per hour) for 1 or 3 years. Unlike RIs, it applies flexibly to Amazon EC2, AWS Fargate, AWS Lambda and Amazon SageMaker AI regardless of instance type or Region. Payment options: All upfront, Partial upfront or No upfront."},
{"name": "Spot Instances / Instancje Spot", "category": "Moc obliczeniowa", "kind": "pojęcie", "module": 2, "pl": "Opcja cenowa EC2 wykorzystująca wolną moc obliczeniową AWS z rabatem do 90% względem On-Demand. AWS może przerwać instancję, gdy potrzebuje tej mocy z powrotem. Nadaje się tylko dla obciążeń elastycznych i odpornych na przerwy, np. przetwarzania wsadowego – nie dla krytycznych baz danych.", "en": "An EC2 pricing option that uses spare AWS compute capacity at up to 90% off the On-Demand price. AWS can interrupt the instance when it reclaims the capacity. Suitable only for flexible, interruption-tolerant workloads such as batch processing."},
{"name": "Storage optimized instances / Instancje zoptymalizowane pod pamięć masową", "category": "Moc obliczeniowa", "kind": "pojęcie", "module": 2, "pl": "Rodzina instancji EC2 dla obciążeń wymagających bardzo wydajnego dostępu do danych przechowywanych lokalnie: dużych baz danych, hurtowni danych i aplikacji intensywnie korzystających z operacji wejścia/wyjścia (I/O).", "en": "An EC2 instance family for workloads that require high performance for locally stored data, such as large databases, data warehousing and I/O-intensive applications."},
{"name": "Amazon Elastic Container Registry (Amazon ECR)", "category": "Kontenery i serverless", "kind": "usługa", "module": 3, "pl": "W pełni zarządzany rejestr obrazów kontenerów: przechowuje, wersjonuje i udostępnia obrazy do wdrożenia. Obsługuje obrazy zgodne ze standardem OCI (Open Container Initiative), a obrazy wysyłasz i pobierasz standardowymi narzędziami (push/pull). Integruje się z Amazon ECS, Amazon EKS i AWS Fargate.", "en": "A fully managed registry where you store, manage, version and deploy container images. It supports images that follow the Open Container Initiative (OCI) standards, and you push and pull images with standard container tooling. It integrates with Amazon ECS, Amazon EKS and AWS Fargate."},
{"name": "Amazon Elastic Container Service (Amazon ECS)", "category": "Kontenery i serverless", "kind": "usługa", "module": 3, "pl": "Skalowalna usługa orkiestracji kontenerów (np. Docker) w AWS. Kontenery możesz uruchamiać na instancjach EC2 (pełna kontrola nad infrastrukturą i sprzętem) albo na AWS Fargate (bez zarządzania serwerami). To natywne rozwiązanie AWS – gdy potrzebujesz Kubernetesa, wybierz Amazon EKS.", "en": "A scalable container orchestration service for running and managing containers, such as Docker containers, on AWS. You can run containers on EC2 instances (full control over infrastructure) or on AWS Fargate (no servers to manage). If you need Kubernetes, use Amazon EKS instead."},
{"name": "Amazon Elastic Kubernetes Service (Amazon EKS)", "category": "Kontenery i serverless", "kind": "usługa", "module": 3, "pl": "W pełni zarządzana usługa do uruchamiania Kubernetesa w AWS. Upraszcza wdrażanie, zarządzanie i skalowanie aplikacji kontenerowych na otwartoźródłowym Kubernetesie, ze wsparciem i aktualizacjami od społeczności. Działa na instancjach EC2 (pełna kontrola) lub na AWS Fargate (bez serwerów).", "en": "A fully managed service for running Kubernetes on AWS. It simplifies deploying, managing and scaling containerized applications using open-source Kubernetes, with ongoing community support and updates. It can run on EC2 instances (full control) or on AWS Fargate (serverless)."},
{"name": "AWS Fargate", "category": "Kontenery i serverless", "kind": "usługa", "module": 3, "pl": "Bezserwerowy silnik obliczeniowy dla kontenerów, działający z Amazon ECS i Amazon EKS. Nie udostępniasz ani nie zarządzasz serwerami – Fargate robi to za Ciebie, a płacisz tylko za zasoby potrzebne kontenerom. Uwaga: Fargate to platforma hostingu kontenerów, a ECS i EKS to usługi orkiestracji.", "en": "A serverless compute engine for containers that works with both Amazon ECS and Amazon EKS. You don't provision or manage servers, and you pay only for the resources required to run your containers. Fargate is a container hosting platform, whereas ECS and EKS are orchestration services."},
{"name": "AWS Lambda", "category": "Kontenery i serverless", "kind": "usługa", "module": 3, "pl": "Bezserwerowa usługa obliczeniowa, która uruchamia Twój kod (funkcję Lambda) w odpowiedzi na zdarzenia – np. przesłanie pliku do S3, wiadomość w kolejce SQS czy żądanie HTTP. AWS sam zarządza serwerami i skalowaniem. Płacisz tylko za czas wykonania kodu, liczony z dokładnością do milisekundy; cena zależy od przydzielonej pamięci. Idealna dla aplikacji sterowanych zdarzeniami.", "en": "A serverless compute service that runs your code (a Lambda function) in response to events, such as file uploads, SQS messages or HTTP requests, without provisioning or managing servers. It scales automatically. You are charged only for the compute time consumed, down to the millisecond, and the price depends on the memory allocated."},
{"name": "Container / Kontener", "category": "Kontenery i serverless", "kind": "pojęcie", "module": 3, "pl": "Standardowy pakiet zawierający kod aplikacji wraz ze wszystkimi zależnościami, dzięki czemu działa tak samo na każdym komputerze – od laptopa programisty po produkcję. Kontenery są lżejsze i szybciej startują niż maszyny wirtualne, bo współdzielą system operacyjny hosta. Ułatwiają spójne wdrożenia i przenoszenie aplikacji.", "en": "A package of your application's code and its dependencies that runs the same way on any computer, from a developer's laptop to production. Containers are lighter and start faster than virtual machines because they share the host's operating system. They make deployments consistent and portable."},
{"name": "Container orchestration / Orkiestracja kontenerów", "category": "Kontenery i serverless", "kind": "pojęcie", "module": 3, "pl": "Automatyczne wdrażanie, skalowanie, monitorowanie i zarządzanie cyklem życia wielu kontenerów na wielu hostach. Przy setkach lub tysiącach kontenerów ręczne zarządzanie przestaje być możliwe. W AWS służą do tego Amazon ECS i Amazon EKS.", "en": "Automating the deployment, scaling, monitoring and lifecycle management of many containers across multiple hosts. At the scale of hundreds or thousands of containers, manual management becomes unsustainable. In AWS, Amazon ECS and Amazon EKS provide orchestration."},
{"name": "Docker", "category": "Kontenery i serverless", "kind": "pojęcie", "module": 3, "pl": "Platforma programistyczna do budowania, testowania i wdrażania aplikacji w kontenerach. Amazon ECS uruchamia i zarządza kontenerami Docker.", "en": "A software platform for building, testing and deploying applications quickly by using containers. Amazon ECS runs and manages Docker containers."},
{"name": "Kubernetes", "category": "Kontenery i serverless", "kind": "pojęcie", "module": 3, "pl": "Otwartoźródłowa (open-source) platforma do orkiestracji kontenerów, rozwijana przez szeroką społeczność. W AWS uruchomisz ją jako usługę zarządzaną Amazon EKS.", "en": "Open-source software for orchestrating containers at scale, supported by a broad community. In AWS you run it as a managed service with Amazon EKS."},
{"name": "Serverless computing / Przetwarzanie bezserwerowe", "category": "Kontenery i serverless", "kind": "pojęcie", "module": 3, "pl": "Uruchamianie aplikacji bez udostępniania i zarządzania serwerami. AWS automatycznie obsługuje infrastrukturę, skalowanie i dostępność, a Ty płacisz tylko za faktyczne użycie. Możesz skupić się na kodzie. Przykłady: AWS Lambda, AWS Fargate, Amazon EventBridge.", "en": "Running applications without provisioning or managing the underlying servers. AWS automatically handles infrastructure, scaling and availability, and you pay only for what you use, so you can focus on your code. Examples: AWS Lambda, AWS Fargate, Amazon EventBridge."},
{"name": "Serverless web backend (API Gateway + Lambda + DynamoDB) / Backend serverless", "category": "Kontenery i serverless", "kind": "pojęcie", "module": 13, "pl": "Typowa architektura bez serwerów: Amazon API Gateway odbiera i weryfikuje żądania HTTP i wywołuje funkcję AWS Lambda, która zapisuje lub odczytuje dane w Amazon DynamoDB; AWS X-Ray śledzi żądania przez cały łańcuch, ułatwiając diagnozę. Wariant: statyczna strona w Amazon S3 z formularzem kontaktowym, w której Lambda wysyła e-mail przez Amazon SES. Nie zarządzasz żadnymi serwerami, a całość skaluje się automatycznie.", "en": "A typical serverless architecture: Amazon API Gateway receives and validates HTTP requests and invokes an AWS Lambda function, which reads or writes data in Amazon DynamoDB; AWS X-Ray traces requests through the whole chain for troubleshooting. A variant: a static website on Amazon S3 with a contact form, where Lambda sends an email through Amazon SES. You manage no servers, and everything scales automatically."},
{"name": "Amazon EventBridge", "category": "Integracja aplikacji", "kind": "usługa", "module": 2, "pl": "Bezserwerowa usługa magistrali zdarzeń do budowy aplikacji sterowanych zdarzeniami (event-driven). Kieruje zdarzenia z własnych aplikacji, usług AWS i oprogramowania firm trzecich (SaaS) do właściwych odbiorców, umożliwiając ich filtrowanie i przekształcanie. Obsługuje duże wolumeny zdarzeń, a gdy odbiorca jest niedostępny, przechowuje zdarzenie i dostarcza je później.", "en": "A serverless event bus service for building scalable, event-driven applications. It routes events from custom apps, AWS services and third-party software to other applications, and simplifies receiving, filtering, transforming and delivering events. It handles high event volumes and keeps events until an unavailable target can process them."},
{"name": "Amazon Simple Notification Service (Amazon SNS)", "category": "Integracja aplikacji", "kind": "usługa", "module": 2, "pl": "Usługa publikuj–subskrybuj (publish-subscribe). Wydawca wysyła wiadomość do tematu (SNS topic), a SNS natychmiast dostarcza ją wszystkim subskrybentom tego tematu (model push). Subskrybentami mogą być serwery WWW, adresy e-mail, funkcje AWS Lambda, kolejki SQS, SMS czy powiadomienia mobilne. Różnica względem SQS: SNS rozsyła do wielu odbiorców, SQS przechowuje wiadomości do pobrania.", "en": "A publish-subscribe service: publishers send messages to an SNS topic and SNS pushes them to all subscribers of that topic. Subscribers can include web servers, email addresses, AWS Lambda functions, SQS queues, SMS and mobile push notifications. Unlike SQS, SNS fans messages out to many subscribers instead of storing them for retrieval."},
{"name": "Amazon Simple Queue Service (Amazon SQS)", "category": "Integracja aplikacji", "kind": "usługa", "module": 2, "pl": "W pełni zarządzana usługa kolejek wiadomości do niezawodnej komunikacji między komponentami. Wysyła, przechowuje i odbiera wiadomości w dowolnej skali, nie gubiąc ich – odbiorca nie musi być dostępny w chwili wysłania. Producent wkłada wiadomość do kolejki, a konsument ją pobiera, przetwarza i usuwa (model pull). Klasyczne narzędzie do rozprzęgania (decoupling) aplikacji.", "en": "A fully managed message queuing service for reliable communication between software components. It sends, stores and receives messages at any scale without losing them, and other services don't need to be available. An application places messages in a queue, and a consumer retrieves, processes and then deletes them. A classic tool for decoupling."},
{"name": "Loosely coupled architecture (microservices) / Architektura luźno powiązana", "category": "Integracja aplikacji", "kind": "pojęcie", "module": 2, "pl": "Architektura mikrousług, w której komponenty aplikacji są luźno powiązane (decoupled). Awaria jednego komponentu nie zatrzymuje pozostałych, bo komunikują się przez kolejki, tematy lub zdarzenia (Amazon SQS, Amazon SNS, Amazon EventBridge). Zwiększa dostępność, odporność i elastyczność.", "en": "A microservices architecture in which application components are loosely coupled. If one component fails, the others continue to work because they communicate through queues, topics or events (Amazon SQS, Amazon SNS, Amazon EventBridge). It improves availability, resilience and flexibility."},
{"name": "Tightly coupled architecture (monolith) / Architektura ściśle powiązana", "category": "Integracja aplikacji", "kind": "pojęcie", "module": 2, "pl": "Tradycyjna architektura monolityczna, w której komponenty (logika bazy danych, serwery aplikacji, interfejs, logika biznesowa) są ze sobą ściśle połączone. Awaria jednego komponentu może pociągnąć za sobą kolejne i zatrzymać całą aplikację.", "en": "A traditional monolithic architecture in which components such as database logic, web application servers, user interfaces and business logic are tightly coupled. If one component fails, it can cause other components to fail and bring down the entire application."},
{"name": "AWS APIs", "category": "Zarządzanie i wdrażanie", "kind": "pojęcie", "module": 2, "pl": "Wszystkie działania w AWS – uruchomienie, zatrzymanie czy zmiana konfiguracji instancji – to wywołania interfejsów API. API udostępniają zdefiniowane metody do zarządzania zasobami. Wywołujesz je na trzy główne sposoby: przez AWS Management Console, AWS CLI lub AWS SDK (a także narzędziami infrastruktury jako kodu).", "en": "Every action in AWS, such as launching, stopping or modifying an instance, is an API request. APIs provide predefined methods to interact with and manage AWS resources. You call them through three primary methods: the AWS Management Console, the AWS CLI or the AWS SDKs."},
{"name": "AWS CloudFormation", "category": "Zarządzanie i wdrażanie", "kind": "usługa", "module": 4, "pl": "Usługa infrastruktury jako kodu: tworzysz szablon (template) w formacie JSON lub YAML opisujący wszystkie potrzebne zasoby AWS, a CloudFormation sam je tworzy i konfiguruje jako stos (stack). Ten sam szablon możesz wdrażać wielokrotnie – w innych Regionach czy na innych kontach – zawsze z identycznym wynikiem. Zastosowania: automatyzacja DevOps i potoki CI/CD oraz spójne skalowanie aplikacji na wiele Regionów.", "en": "An infrastructure as code service: you write a template in JSON or YAML that describes all the AWS resources you need, and CloudFormation provisions and configures them for you as a stack. You can deploy the same template repeatedly – in other Regions or accounts – with identical results. Use cases: DevOps automation and CI/CD pipelines, and scaling applications to multiple Regions in a consistent, repeatable way."},
{"name": "AWS Command Line Interface (AWS CLI)", "category": "Zarządzanie i wdrażanie", "kind": "usługa", "module": 2, "pl": "Narzędzie do zarządzania wieloma usługami AWS z wiersza poleceń w systemach Windows, macOS i Linux. Pozwala automatyzować zadania skryptami, np. uruchamianie instancji EC2. Dla zaawansowanych użytkowników i programistów, którzy chcą powtarzalnych, zautomatyzowanych operacji.", "en": "A tool for managing multiple AWS services from the command line on Windows, macOS and Linux. You can automate tasks through scripts, such as launching EC2 instances. Good for advanced users and developers who need automation."},
{"name": "AWS Management Console", "category": "Zarządzanie i wdrażanie", "kind": "usługa", "module": 2, "pl": "Interfejs WWW do zarządzania usługami AWS: szybki dostęp do usług, wyszukiwarka i uproszczone kreatory. Najlepszy dla osób, które wolą wizualną pracę i dopiero poznają usługi. Aplikacja mobilna Console pozwala monitorować zasoby, przeglądać alarmy i sprawdzać rozliczenia.", "en": "A web interface for managing AWS services, offering quick access to services, search and simplified workflows. Good for users who prefer a visual, easy-to-use interface. The mobile app lets you monitor resources, view alarms and check billing."},
{"name": "AWS SDKs / Zestawy SDK AWS", "category": "Zarządzanie i wdrażanie", "kind": "usługa", "module": 2, "pl": "Zestawy narzędzi programistycznych, które ułatwiają korzystanie z usług AWS bezpośrednio w kodzie aplikacji przez API dla różnych języków (m.in. C++, Java, .NET, Python, JavaScript). AWS udostępnia dokumentację i przykładowy kod. Dla programistów integrujących AWS ze swoimi aplikacjami.", "en": "Software development kits that simplify integrating AWS services into your applications by providing APIs for various programming languages, such as C++, Java and .NET. AWS offers documentation and sample code. Good for developers integrating AWS into their applications."},
{"name": "AWS Systems Manager", "category": "Zarządzanie i wdrażanie", "kind": "usługa", "module": 9, "pl": "Usługa dająca centralny widok węzłów (serwerów, instancji) we wszystkich kontach i Regionach organizacji, także w środowiskach hybrydowych i wielochmurowych. Pozwala szybko sprawdzić informacje o węzłach (np. ID, system operacyjny) i automatyzować zadania operacyjne, takie jak instalowanie poprawek bezpieczeństwa, edycje rejestru i zarządzanie użytkownikami. W kursie wspiera zasadę najmniejszych uprawnień i bezpieczną administrację.", "en": "A service that provides a centralized view of nodes (servers, instances) across your organization's accounts and Regions, including multicloud and hybrid environments. You can quickly access node information, such as ID and operating system details, and automate operational tasks such as security patching, registry edits, and user management. In the course, it supports least privilege and secure administration."},
{"name": "Infrastructure as code (IaC) / Infrastruktura jako kod", "category": "Zarządzanie i wdrażanie", "kind": "pojęcie", "module": 4, "pl": "Podejście, w którym infrastrukturę (sieci, serwery, bazy danych) opisujesz w plikach kodu, zamiast tworzyć ją ręcznie w konsoli. Dzięki temu wdrożenia są spójne i powtarzalne, a konfigurację można wersjonować i automatyzować, np. w potokach CI/CD. W AWS główną usługą IaC jest AWS CloudFormation.", "en": "An approach in which you describe infrastructure (networks, servers, databases) in code files instead of creating it manually in the console. This makes deployments consistent and repeatable, and lets you version and automate them, for example in CI/CD pipelines. The main AWS IaC service is AWS CloudFormation."},
{"name": "Amazon API Gateway", "category": "Sieci i dostarczanie treści", "kind": "usługa", "module": 5, "pl": "W pełni zarządzana usługa do tworzenia, publikowania, utrzymywania, monitorowania i zabezpieczania interfejsów API w dowolnej skali. API określa, jak różne systemy komunikują się ze sobą. API Gateway pełni rolę „drzwi wejściowych” do aplikacji – często przed funkcjami AWS Lambda lub usługami działającymi na EC2.", "en": "A fully managed service for creating, publishing, maintaining, monitoring and securing APIs at any scale. An API defines how different software systems interact and communicate with each other. API Gateway acts as the front door to applications – often in front of AWS Lambda functions or services running on EC2."},
{"name": "Amazon CloudFront", "category": "Sieci i dostarczanie treści", "kind": "usługa", "module": 5, "pl": "Usługa sieci dostarczania treści (CDN), która przechowuje kopie Twoich treści (strony, obrazy, filmy, API) w lokalizacjach brzegowych blisko użytkowników. Dzięki temu treści ładują się szybciej, z mniejszym opóźnieniem i niższym kosztem, niż gdyby każde żądanie trafiało do serwera źródłowego (origin). Zastosowania: streaming wideo, sklepy internetowe w szczycie sprzedaży, aplikacje mobilne.", "en": "A content delivery network (CDN) service that stores copies of your content (web pages, images, videos, APIs) at edge locations close to users. As a result, content loads faster, with lower latency and cost, than if every request went back to the origin server. Use cases: video streaming, ecommerce sites during peak shopping, mobile apps."},
{"name": "Amazon Route 53", "category": "Sieci i dostarczanie treści", "kind": "usługa", "module": 5, "pl": "Wysoce dostępna i skalowalna usługa DNS w chmurze, działająca na globalnie rozproszonych serwerach DNS w lokalizacjach brzegowych. Kieruje użytkowników do aplikacji działających w AWS (np. instancji EC2, load balancerów) i poza AWS. Pozwala też rejestrować nowe domeny i przenosić rekordy DNS istniejących domen, aby zarządzać wszystkimi w jednym miejscu; często współpracuje z Amazon CloudFront.", "en": "A highly available and scalable cloud DNS service running on globally dispersed DNS servers at edge locations. It routes end users to applications running in AWS (such as EC2 instances and load balancers) and outside AWS. You can also register new domain names and transfer DNS records for existing domains to manage them all in one place; it often works together with Amazon CloudFront."},
{"name": "Amazon Virtual Private Cloud (Amazon VPC)", "category": "Sieci i dostarczanie treści", "kind": "usługa", "module": 5, "pl": "Logicznie odizolowana część chmury AWS, w której uruchamiasz zasoby we własnej, zdefiniowanej przez siebie sieci wirtualnej (zakres adresów IP, podsieci, tablice routingu, bramy). VPC działa w obrębie jednego Regionu i może obejmować wiele AZ. Daje pełną kontrolę nad rozmieszczeniem zasobów, łącznością i bezpieczeństwem – ruch filtrujesz m.in. grupami zabezpieczeń i sieciowymi listami ACL.", "en": "A logically isolated section of the AWS Cloud where you launch resources in a virtual network that you define (IP address range, subnets, route tables, gateways). A VPC lives in one Region and can span multiple AZs. It gives you full control over resource placement, connectivity and security – you filter traffic with security groups and network ACLs, among others."},
{"name": "AWS Client VPN", "category": "Sieci i dostarczanie treści", "kind": "usługa", "module": 5, "pl": "W pełni zarządzana, elastyczna usługa VPN, która łączy pracowników zdalnych z zasobami AWS i sieciami on-premises z dowolnego miejsca. Skaluje się automatycznie w górę i w dół w zależności od liczby użytkowników, bez instalowania sprzętu. Używa klienta opartego na OpenVPN; typowe zastosowanie: szybkie zapewnienie dostępu zdalnego dużej liczbie pracowników, np. po przejęciu firmy.", "en": "A fully managed, elastic VPN service that connects remote workers to AWS resources and on-premises networks from anywhere. It scales up or down automatically based on the number of users, with no hardware to install. It uses an OpenVPN-based client; typical use case: quickly giving remote access to a large workforce, for example after an acquisition."},
{"name": "AWS Direct Connect", "category": "Sieci i dostarczanie treści", "kind": "usługa", "module": 5, "pl": "Dedykowane, prywatne, fizyczne łącze między Twoją siecią (centrum danych, biuro) a VPC w AWS, które omija publiczny internet. Daje stabilne, niskie opóźnienia i dużą przepustowość, a także może obniżyć koszty sieci. Zastosowania: aplikacje wrażliwe na opóźnienia, migracja dużych ilości danych, architektury hybrydowe; jako zapas (failover) używa się drugiego łącza Direct Connect lub Site-to-Site VPN, a kilka łączy można połączyć dla większej przepustowości.", "en": "A dedicated, private, physical connection between your network (data center, office) and your VPC in AWS that bypasses the public internet. It provides consistent low latency and high bandwidth and can reduce network costs. Use cases: latency-sensitive applications, large-scale data migration, hybrid architectures; for failover you use a second Direct Connect line or a Site-to-Site VPN, and multiple connections can be combined for higher aggregate bandwidth."},
{"name": "AWS Global Accelerator", "category": "Sieci i dostarczanie treści", "kind": "usługa", "module": 5, "pl": "Usługa sieciowa, która kieruje ruch użytkowników przez prywatną, globalną sieć AWS zamiast przez zatłoczony publiczny internet – jak „pas ekspresowy” dla aplikacji. Poprawia dostępność, wydajność i bezpieczeństwo dzięki inteligentnemu routingowi i szybkiemu przełączaniu (failover) przy awarii jednej z lokalizacji. W odróżnieniu od CloudFront nie buforuje treści – przyspiesza samo połączenie, np. w grach online czy aplikacjach bankowych.", "en": "A networking service that routes user traffic over the private AWS global network instead of the congested public internet – like an express lane for your application. It improves availability, performance and security with intelligent traffic routing and fast failover if one application location has a problem. Unlike CloudFront it does not cache content – it speeds up the connection itself, e.g. for online gaming or banking apps."},
{"name": "AWS PrivateLink", "category": "Sieci i dostarczanie treści", "kind": "usługa", "module": 5, "pl": "Technologia, która prywatnie łączy Twoje VPC z usługami AWS oraz z usługami w innych VPC lub u innych dostawców tak, jakby znajdowały się w Twoim VPC. Ruch nie przechodzi przez publiczny internet – nie potrzebujesz bramy internetowej, NAT, publicznych adresów IP, VPN ani Direct Connect. Sam decydujesz, które punkty końcowe (endpoints) API i usługi są osiągalne z VPC.", "en": "Technology that privately connects your VPC to AWS services and to services in other VPCs or from other providers as if they were in your own VPC. Traffic does not traverse the public internet – you don’t need an internet gateway, NAT device, public IP addresses, VPN or Direct Connect. You control which specific API endpoints and services are reachable from your VPC."},
{"name": "AWS Site-to-Site VPN", "category": "Sieci i dostarczanie treści", "kind": "usługa", "module": 5, "pl": "Tworzy bezpieczne, szyfrowane połączenie przez internet między Twoim centrum danych lub oddziałami firmy a zasobami w Amazon VPC (po stronie AWS przez wirtualną bramę prywatną). Zapewnia wysoką dostępność i prywatne sesje. Zastosowania: migracja aplikacji, bezpieczna komunikacja między odległymi lokalizacjami oraz zapasowe łącze (failover) dla AWS Direct Connect.", "en": "Creates a secure, encrypted connection over the internet between your data center or branch offices and your resources in Amazon VPC (through a virtual private gateway on the AWS side). It provides high availability and private sessions. Use cases: application migration, secure communication between remote locations, and a backup (failover) link for AWS Direct Connect."},
{"name": "AWS Transit Gateway", "category": "Sieci i dostarczanie treści", "kind": "usługa", "module": 5, "pl": "Centralny węzeł (hub), który łączy wiele VPC i sieci on-premises w jednym miejscu, zamiast tworzyć osobne połączenia między każdą parą sieci. Upraszcza zarządzanie siecią, gdy infrastruktura rośnie. Bramy tranzytowe w różnych Regionach można łączyć przez peering między Regionami, korzystając z globalnej infrastruktury AWS.", "en": "A central hub that connects many Amazon VPCs and on-premises networks in one place, instead of creating separate connections between every pair of networks. It simplifies network management as your infrastructure grows. Transit gateways in different Regions can be connected through inter-Region peering over the AWS Global Infrastructure."},
{"name": "Domain Name System (DNS)", "category": "Sieci i dostarczanie treści", "kind": "pojęcie", "module": 5, "pl": "„Książka telefoniczna internetu” – system, który tłumaczy czytelne dla ludzi nazwy domen (np. example.com) na adresy IP zrozumiałe dla komputerów. Ten proces to rozwiązywanie nazw (DNS resolution): przeglądarka pyta resolver DNS, a ten pyta serwer DNS firmy o adres IP strony. W AWS usługą DNS jest Amazon Route 53.", "en": "The phone book of the internet – a system that translates human-readable domain names (such as example.com) into machine-readable IP addresses. This process is called DNS resolution: the browser asks a DNS resolver, which asks the company’s DNS server for the website’s IP address. The AWS DNS service is Amazon Route 53."},
{"name": "Internet gateway / Brama internetowa", "category": "Sieci i dostarczanie treści", "kind": "pojęcie", "module": 5, "pl": "Komponent podłączany do VPC, który umożliwia komunikację między VPC a internetem – działa jak drzwi wejściowe do kawiarni. Bez bramy internetowej nikt z internetu nie dotrze do zasobów w VPC. Podsieć staje się publiczna, gdy jej tablica routingu kieruje ruch do bramy internetowej.", "en": "A component attached to a VPC that enables communication between the VPC and the internet – like the front door of the coffee shop. Without an internet gateway, nobody from the internet can reach resources in the VPC. A subnet becomes public when its route table sends traffic to the internet gateway."},
{"name": "NAT gateway / Brama NAT", "category": "Sieci i dostarczanie treści", "kind": "pojęcie", "module": 5, "pl": "Zarządzana usługa translacji adresów sieciowych (NAT), dzięki której instancje w podsieci prywatnej mogą łączyć się z usługami poza VPC (np. pobierać aktualizacje z internetu). Zewnętrzne usługi nie mogą jednak same nawiązać połączenia z tymi instancjami. Brama NAT umieszczana jest w podsieci publicznej.", "en": "A managed Network Address Translation (NAT) service that lets instances in a private subnet connect to services outside the VPC (for example, to download updates from the internet). External services, however, cannot initiate a connection with those instances. A NAT gateway is placed in a public subnet."},
{"name": "Network access control list (network ACL) / Sieciowa lista kontroli dostępu", "category": "Sieci i dostarczanie treści", "kind": "pojęcie", "module": 5, "pl": "Wirtualna zapora kontrolująca ruch przychodzący i wychodzący na poziomie podsieci. Jest bezstanowa (stateless) – niczego nie pamięta, sprawdza każdy pakiet w obu kierunkach, a ruch powrotny trzeba jawnie zezwolić. Obsługuje reguły zezwalające i odmawiające (allow i deny); domyślna lista ACL konta przepuszcza cały ruch, a nowa, niestandardowa lista blokuje wszystko, dopóki nie dodasz reguł.", "en": "A virtual firewall that controls inbound and outbound traffic at the subnet level. It is stateless – it remembers nothing, checks every packet in both directions, and return traffic must be explicitly allowed. It supports both allow and deny rules; the account’s default network ACL allows all traffic, while a new custom network ACL denies everything until you add rules."},
{"name": "Private subnet / Podsieć prywatna", "category": "Sieci i dostarczanie treści", "kind": "pojęcie", "module": 5, "pl": "Podsieć bez bezpośredniego dostępu z internetu – izoluje zasoby, które nie powinny być publicznie widoczne, np. bazę danych z danymi osobowymi klientów i historią zamówień. Zasoby w niej mogą komunikować się z zasobami w podsieci publicznej, a do ruchu wychodzącego do internetu mogą używać bramy NAT. Na diagramach AWS rysowana jest linią ciągłą.", "en": "A subnet without direct access from the internet – it isolates resources that should not be publicly exposed, such as a database with customers’ personal information and order history. Resources in it can communicate with resources in public subnets and can use a NAT gateway for outbound internet access. In AWS diagrams it is drawn with a solid box."},
{"name": "Public subnet / Podsieć publiczna", "category": "Sieci i dostarczanie treści", "kind": "pojęcie", "module": 5, "pl": "Podsieć z trasą do bramy internetowej (internet gateway), dzięki czemu umieszczone w niej zasoby mogą mieć bezpośredni dostęp do internetu i być osiągalne z internetu. Umieszcza się w niej zasoby, które muszą być publiczne, np. serwer WWW sklepu internetowego czy load balancer. Na diagramach AWS rysowana jest linią przerywaną.", "en": "A subnet with a route to an internet gateway, so resources inside it can have direct internet access and be reached from the internet. It holds resources that must be public, such as an online store’s web server or a load balancer. In AWS diagrams it is drawn with a dashed box."},
{"name": "Route 53 routing policies / Zasady routingu Route 53", "category": "Sieci i dostarczanie treści", "kind": "pojęcie", "module": 5, "pl": "Reguły, według których Route 53 kieruje ruch do różnych punktów końcowych. W kursie: routing oparty na opóźnieniach (latency-based – do Regionu o najmniejszym opóźnieniu), geolokalizacja (geolocation – według położenia użytkownika, np. Europa → Region europejski), geobliskość (geoproximity) i ważony (weighted round robin – podział ruchu w ustalonych proporcjach). Dzięki nim jedna domena może obsługiwać użytkowników z wielu Regionów.", "en": "Rules that determine how Route 53 routes traffic to different endpoints. Covered in the course: latency-based routing (to the Region with the lowest latency), geolocation (based on where the user is, e.g. Europe → a European Region), geoproximity, and weighted round robin (splitting traffic in set proportions). They let one domain serve users across multiple Regions."},
{"name": "Route table / Tablica routingu", "category": "Sieci i dostarczanie treści", "kind": "pojęcie", "module": 5, "pl": "Zestaw reguł (tras) określających, dokąd kierowany jest ruch sieciowy z podsieci w VPC. Np. trasa do bramy internetowej sprawia, że podsieć jest publiczna, a trasa lokalna pozwala zasobom w VPC komunikować się między sobą. Tablice routingu tworzy się i kojarzy z podsieciami podczas budowania VPC.", "en": "A set of rules (routes) that determine where network traffic from subnets in your VPC is directed. For example, a route to an internet gateway makes a subnet public, while the local route lets resources in the VPC communicate with each other. You create route tables and associate them with subnets when you build a VPC."},
{"name": "Security group / Grupa zabezpieczeń", "category": "Sieci i dostarczanie treści", "kind": "pojęcie", "module": 5, "pl": "Wirtualna zapora kontrolująca ruch przychodzący i wychodzący na poziomie zasobu, np. instancji EC2. Jest stanowa (stateful) – pamięta wcześniejsze decyzje, więc odpowiedź na dozwolone żądanie przechodzi automatycznie. Ma tylko reguły zezwalające (allow); domyślnie blokuje cały ruch przychodzący i przepuszcza cały wychodzący. Porównanie: grupa zabezpieczeń = instancja, stanowa, tylko allow; network ACL = podsieć, bezstanowa, allow i deny.", "en": "A virtual firewall that controls inbound and outbound traffic at the resource level, for example for an EC2 instance. It is stateful – it remembers previous decisions, so the response to an allowed request is automatically let through. It has allow rules only; by default it denies all inbound traffic and allows all outbound traffic. Comparison: security group = instance, stateful, allow only; network ACL = subnet, stateless, allow and deny."},
{"name": "Subnet / Podsieć", "category": "Sieci i dostarczanie treści", "kind": "pojęcie", "module": 5, "pl": "Podsieć to wydzielony zakres adresów IP w VPC, w którym grupujesz zasoby według potrzeb bezpieczeństwa lub operacyjnych. Każda podsieć znajduje się w jednej strefie dostępności, dlatego dla wysokiej dostępności tworzy się podsieci w co najmniej dwóch AZ. Podsieci mogą być publiczne lub prywatne, a ruch na ich granicy kontrolują sieciowe listy ACL.", "en": "A subnet is a range of IP addresses in your VPC used to group resources based on security or operational needs. Each subnet resides in a single Availability Zone, so for high availability you create subnets in at least two AZs. Subnets can be public or private, and traffic crossing their boundary is controlled by network ACLs."},
{"name": "Virtual private gateway / Wirtualna brama prywatna", "category": "Sieci i dostarczanie treści", "kind": "pojęcie", "module": 5, "pl": "Komponent po stronie AWS, który pozwala wpuścić do VPC chroniony (szyfrowany) ruch VPN z zaufanej sieci, np. z centrum danych on-premises lub sieci firmowej. Przepuszcza ruch tylko z zatwierdzonej sieci, więc nadaje się dla VPC z zasobami wyłącznie prywatnymi. Używana z AWS Site-to-Site VPN, a także jako punkt końcowy połączeń AWS Direct Connect.", "en": "The AWS-side component that lets protected (encrypted) VPN traffic from a trusted network, such as an on-premises data center or corporate network, enter the VPC. It allows traffic in only if it comes from an approved network, so it suits VPCs with private resources only. It is used with AWS Site-to-Site VPN and as an endpoint for AWS Direct Connect connections."},
{"name": "Virtual private network (VPN) / Wirtualna sieć prywatna", "category": "Sieci i dostarczanie treści", "kind": "pojęcie", "module": 5, "pl": "Połączenie, które tworzy bezpieczny, szyfrowany tunel przez publiczny internet i ukrywa przesyłane dane przed osobami trzecimi. W AWS dostępne jako AWS Site-to-Site VPN (sieć firmy ↔ VPC) i AWS Client VPN (pracownicy zdalni ↔ AWS). Nie myl skrótów: VPC to sieć w chmurze, virtual private gateway to brama do VPC, a VPN to szyfrowane połączenie.", "en": "A connection that creates a secure, encrypted tunnel through the public internet, hiding your traffic from others. On AWS it comes as AWS Site-to-Site VPN (company network ↔ VPC) and AWS Client VPN (remote workers ↔ AWS). Don’t confuse the acronyms: a VPC is your cloud network, a virtual private gateway is the door into the VPC, and a VPN is the encrypted connection."},
{"name": "VPC endpoint / Punkt końcowy VPC", "category": "Sieci i dostarczanie treści", "kind": "pojęcie", "module": 11, "pl": "Sposób na prywatne połączenie VPC z obsługiwanymi usługami AWS (np. Amazon S3) bez korzystania z publicznego internetu. Zwiększa bezpieczeństwo, a w kursie jest podany jako technika optymalizacji kosztów – dostęp do S3 przez punkt końcowy VPC może ograniczyć koszty transferu danych.", "en": "A way to privately connect your VPC to supported AWS services (such as Amazon S3) without using the public internet. It improves security, and in the course it is presented as a cost optimization technique – accessing Amazon S3 through a VPC endpoint can reduce data transfer costs."},
{"name": "Amazon Data Lifecycle Manager", "category": "Pamięć masowa", "kind": "usługa", "module": 6, "pl": "Usługa automatyzująca tworzenie, przechowywanie (retencję) i usuwanie migawek EBS według zdefiniowanych zasad (policies) i harmonogramów. Może wykonywać migawki poza godzinami szczytu, automatycznie usuwać stare kopie, kopiować je między Regionami i udostępniać między kontami. Zmniejsza pracę ręczną i pomaga spełnić wymagania zgodności dotyczące kopii zapasowych.", "en": "A service that automates the creation, retention and deletion of EBS snapshots based on policies and schedules you define. It can take snapshots during off-peak hours, automatically delete outdated backups, copy snapshots across Regions and share them across accounts. It reduces manual effort and helps meet backup compliance requirements."},
{"name": "Amazon EBS snapshots / Migawki EBS", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Kopie zapasowe woluminu EBS z danego momentu (point-in-time). Są przyrostowe: pierwsza migawka zawiera wszystkie dane, a kolejne tylko bloki zmienione od poprzedniej, co obniża koszty i skraca czas tworzenia. Migawki są przechowywane nadmiarowo w wielu AZ (w Amazon S3); z migawki można utworzyć nowy wolumin, także w innej AZ lub Regionie, albo udostępnić ją innemu kontu. Planowanie i usuwanie migawek to obowiązek klienta.", "en": "Point-in-time backups of an EBS volume. They are incremental: the first snapshot contains all data, and later ones store only the blocks changed since the previous snapshot, reducing cost and backup time. Snapshots are stored redundantly across multiple AZs (in Amazon S3); you can create new volumes from them, including in another AZ or Region, or share them with other accounts. Scheduling and deleting snapshots is the customer’s responsibility."},
{"name": "Amazon EBS volume types / Typy woluminów EBS", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "EBS oferuje różne typy woluminów dopasowane do wymagań wydajności (IOPS – operacje wejścia/wyjścia na sekundę) i kosztów. Woluminy SSD to m.in. General Purpose (uniwersalne) i Provisioned IOPS SSD – najwyższa wydajność dla krytycznych baz danych i aplikacji transakcyjnych; woluminy HDD są tańsze i przeznaczone do dużych, sekwencyjnych obciążeń oraz rzadko używanych danych. Typ woluminu można zmienić w locie, bez przestoju.", "en": "EBS offers several volume types matched to performance (IOPS – input/output operations per second) and cost needs. SSD volumes include General Purpose and Provisioned IOPS SSD – the highest performance for mission-critical databases and transactional apps; HDD volumes are cheaper and designed for large sequential workloads and infrequently accessed data. You can change the volume type on the fly without downtime."},
{"name": "Amazon EC2 instance store / Magazyn instancji EC2", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Tymczasowa pamięć blokowa fizycznie podłączona do serwera (hosta), na którym działa instancja EC2. Jest bardzo szybka i wliczona w cenę instancji, ale nietrwała: dane znikają po zatrzymaniu lub zakończeniu (terminate) instancji. Nadaje się tylko do danych tymczasowych – buforów, pamięci podręcznych, danych roboczych (scratch); w modelu współodpowiedzialności to rozwiązanie niezarządzane.", "en": "Temporary block storage physically attached to the host computer that runs your EC2 instance. It is very fast and included in the instance price, but non-persistent: data is lost when the instance is stopped or terminated. Use it only for temporary data – buffers, caches, scratch data; under the shared responsibility model it is an unmanaged option."},
{"name": "Amazon EFS storage classes and lifecycle / Klasy pamięci i cykl życia EFS", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "EFS oferuje klasy Standard i Standard-IA (wiele AZ, najwyższa trwałość i dostępność), tańsze One Zone i One Zone-IA (jedna AZ) oraz Archive – do 50% tańszą od IA, dla danych używanych kilka razy w roku. Zasady cyklu życia automatycznie przenoszą pliki: domyślnie do IA po 30 dniach bez dostępu i do Archive po 90 dniach. Powrót do Standard przy ponownym odczycie trzeba włączyć – domyślnie pliki zostają w IA lub Archive.", "en": "EFS offers Standard and Standard-IA classes (multi-AZ, highest durability and availability), cheaper One Zone and One Zone-IA (single AZ), and Archive – up to 50% cheaper than IA, for data accessed a few times a year. Lifecycle policies move files automatically: by default to IA after 30 days without access and to Archive after 90 days. Moving files back to Standard when accessed must be enabled – by default they stay in IA or Archive."},
{"name": "Amazon Elastic Block Store (Amazon EBS)", "category": "Pamięć masowa", "kind": "usługa", "module": 6, "pl": "Zarządzana usługa trwałej pamięci blokowej: woluminy EBS działają jak zewnętrzne dyski podłączane do instancji EC2, a dane pozostają po zatrzymaniu, a nawet zakończeniu instancji (o ile wolumin nie jest ustawiony do usunięcia razem z nią). Wolumin znajduje się w jednej AZ; można go odłączyć i podłączyć do innej instancji oraz zmieniać jego rozmiar i typ bez przestoju. Zastosowania: bazy danych, systemy plików, środowiska deweloperskie; kopie zapasowe robi się migawkami (snapshots).", "en": "A managed persistent block storage service: EBS volumes act like external hard drives attached to EC2 instances, and data remains after the instance is stopped or even terminated (unless the volume is set to be deleted with it). A volume lives in one AZ; you can detach it and attach it to another instance, and change its size and type without downtime. Use cases: databases, file systems, development environments; back it up with EBS snapshots."},
{"name": "Amazon Elastic File System (Amazon EFS)", "category": "Pamięć masowa", "kind": "usługa", "module": 6, "pl": "W pełni zarządzany, skalowalny system plików oparty na protokole NFS (dla Linuksa), z którego jednocześnie może korzystać wiele – nawet tysiące – instancji EC2 oraz serwery on-premises. Automatycznie rośnie i maleje do petabajtów w miarę dodawania i usuwania plików; płacisz tylko za użyte miejsce, a dane są replikowane w wielu AZ Regionu. Wskazówka egzaminacyjna: EBS = dysk dla instancji w jednej AZ, EFS = wspólny system plików dla wielu instancji.", "en": "A fully managed, scalable file system based on the NFS protocol (for Linux) that many – even thousands of – EC2 instances and on-premises servers can access at the same time. It automatically grows and shrinks up to petabytes as you add and remove files; you pay only for the storage used, and data is replicated across multiple AZs in a Region. Exam cue: EBS = a disk for an instance in one AZ, EFS = a shared file system for many instances."},
{"name": "Amazon FSx", "category": "Pamięć masowa", "kind": "usługa", "module": 6, "pl": "Rodzina w pełni zarządzanych, wydajnych systemów plików w chmurze opartych na popularnych technologiach: Windows File Server, Lustre, NetApp ONTAP i OpenZFS. W odróżnieniu od Amazon EFS (tylko NFS) obsługuje wiele protokołów, więc łatwo przenieść istniejące aplikacje bez zmian. AWS zajmuje się sprzętem, poprawkami i kopiami zapasowymi; płacisz za użyte miejsce.", "en": "A family of fully managed, high-performance file systems in the cloud built on popular technologies: Windows File Server, Lustre, NetApp ONTAP and OpenZFS. Unlike Amazon EFS (NFS only), it supports multiple file system protocols, so existing applications can move without changes. AWS handles hardware provisioning, patching and backups; you pay for the storage you use."},
{"name": "Amazon FSx for Lustre", "category": "Pamięć masowa", "kind": "usługa", "module": 6, "pl": "W pełni zarządzana pamięć współdzielona o skalowalności i wydajności systemu plików Lustre, zaprojektowana dla obciążeń wymagających bardzo szybkiego dostępu do danych. Zastosowania: obliczenia wysokiej wydajności (HPC), uczenie maszynowe, analityka big data, przetwarzanie mediów. Wskazówka egzaminacyjna: „HPC” lub „ML” + „system plików” = FSx for Lustre.", "en": "Fully managed shared storage with the scalability and performance of the Lustre file system, designed for workloads that need very fast data access. Use cases: high performance computing (HPC), machine learning, big data analytics, media processing. Exam cue: HPC or ML + file system = FSx for Lustre."},
{"name": "Amazon FSx for NetApp ONTAP", "category": "Pamięć masowa", "kind": "usługa", "module": 6, "pl": "W pełni zarządzana pamięć współdzielona w AWS z popularnymi funkcjami dostępu do danych i zarządzania nimi znanymi z NetApp ONTAP. Jest zgodna z obciążeniami Windows i Linux. Zastosowania: płynna migracja obciążeń korzystających z NetApp do AWS, nowoczesne aplikacje, modernizacja zarządzania danymi, ciągłość działania biznesu.", "en": "Fully managed shared storage in AWS with the popular data access and management capabilities of NetApp ONTAP. It is compatible with both Windows and Linux workloads. Use cases: seamlessly migrating NetApp-based workloads to AWS, building modern applications, modernizing data management, business continuity."},
{"name": "Amazon FSx for OpenZFS", "category": "Pamięć masowa", "kind": "usługa", "module": 6, "pl": "W pełni zarządzana współdzielona pamięć plikowa zbudowana na otwartym systemie plików OpenZFS, dostępna przez protokół NFS (v3–v4.2). Oferuje wysoką wydajność i skalowalność. Zastosowania: migracja obciążeń opartych na ZFS, analityka danych, zarządzanie treścią, szybsze środowiska deweloperskie i testowe.", "en": "Fully managed shared file storage built on the open-source OpenZFS file system and accessible over NFS (v3 to v4.2). It offers high performance and scalability. Use cases: migrating ZFS-based workloads, data analytics, content management, faster dev/test environments."},
{"name": "Amazon FSx for Windows File Server", "category": "Pamięć masowa", "kind": "usługa", "module": 6, "pl": "W pełni zarządzana pamięć współdzielona zbudowana na Windows Server, z natywną obsługą protokołu SMB i integracją z Active Directory. Zastosowania: migracja serwerów plików Windows do AWS, obciążenia hybrydowe, tańsze wdrożenia SQL Server, wirtualne pulpity i streaming. Wskazówka egzaminacyjna: „Windows” + „współdzielone pliki” = FSx for Windows File Server.", "en": "Fully managed shared storage built on Windows Server, with native SMB protocol support and Active Directory integration. Use cases: migrating Windows file servers to AWS, accelerating hybrid workloads, reducing SQL Server deployment costs, virtual desktops and streaming. Exam cue: Windows + shared files = FSx for Windows File Server."},
{"name": "Amazon S3 bucket / Bucket S3", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Kontener na obiekty w Amazon S3. Nazwa bucketa musi być globalnie unikalna w całym AWS, a sam bucket tworzy się w wybranym Regionie. Bucket to podstawowa jednostka kontroli dostępu – na jego poziomie ustawiasz wersjonowanie, logowanie, uprawnienia i blokadę dostępu publicznego (Block Public Access, domyślnie włączona).", "en": "A container for objects in Amazon S3. A bucket name must be globally unique across all of AWS, and the bucket itself is created in a Region you choose. A bucket is the basic unit of access control – at bucket level you configure versioning, logging, permissions and Block Public Access (enabled by default)."},
{"name": "Amazon S3 File Gateway", "category": "Pamięć masowa", "kind": "usługa", "module": 6, "pl": "Typ Storage Gateway, który dla lokalnych systemów wygląda jak zwykły serwer plików (NFS/SMB), a zapisywane w nim pliki automatycznie trafiają do Amazon S3 jako obiekty. Ostatnio używane dane przechowuje lokalnie w pamięci podręcznej, więc aplikacje pracują na plikach tak jak dotąd. Zastosowanie: lokalne udziały plikowe, których dane faktycznie leżą w S3.", "en": "A Storage Gateway type that appears to local systems as a standard file server (NFS/SMB), while files written to it are automatically uploaded to Amazon S3 as objects. It keeps recently used data in a local cache, so applications keep working with files as before. Use case: on-premises file shares whose data actually lives in S3."},
{"name": "Amazon S3 object / Obiekt S3", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Podstawowa jednostka danych w S3: przesłany plik dowolnego typu staje się obiektem. Obiekt składa się z danych, metadanych (systemowych – np. data utworzenia, rozmiar, klasa pamięci – oraz zdefiniowanych przez użytkownika) i klucza, czyli unikalnej w buckecie nazwy. Pojedynczy obiekt może mieć od kilku bajtów do kilku terabajtów.", "en": "The fundamental unit of data in S3: any file you upload becomes an object. An object consists of the data, metadata (system-defined, such as creation date, size and storage class, plus user-defined) and a key – a name unique within the bucket. A single object can range from a few bytes to several terabytes."},
{"name": "Amazon S3 on Outposts", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Klasa, która udostępnia pamięć obiektową S3 (te same API i funkcje) lokalnie, w Twoim środowisku AWS Outposts on-premises. Służy obciążeniom z wymogiem lokalnego przechowywania danych (data residency) i aplikacjom, które dla wydajności potrzebują danych bardzo blisko siebie.", "en": "A storage class that delivers S3 object storage (the same S3 APIs and features) on premises in your AWS Outposts environment. It serves workloads with local data residency requirements and applications that need data in close proximity for performance."},
{"name": "Amazon Simple Storage Service (Amazon S3)", "category": "Pamięć masowa", "kind": "usługa", "module": 6, "pl": "W pełni zarządzana usługa pamięci obiektowej o praktycznie nieograniczonej pojemności – płacisz tylko za to, co przechowujesz. Pliki zapisuje jako obiekty w kontenerach zwanych bucketami; zapewnia trwałość 99,999999999% („11 dziewiątek”), a wszystkie dane są domyślnie prywatne. Oferuje wersjonowanie, zarządzanie cyklem życia, klasy pamięci i szyfrowanie; zastosowania: kopie zapasowe, archiwa, jeziora danych, statyczne strony WWW, dystrybucja treści.", "en": "A fully managed object storage service with virtually unlimited capacity – you pay only for what you store. It stores files as objects in containers called buckets; it offers 99.999999999% durability (11 nines), and all data is private by default. It provides versioning, lifecycle management, storage classes and encryption; use cases: backups, archives, data lakes, static websites, content distribution."},
{"name": "AWS Backup", "category": "Pamięć masowa", "kind": "usługa", "module": 7, "pl": "Scentralizowana usługa do automatyzacji i zarządzania kopiami zapasowymi wielu usług AWS (np. EC2, EBS, RDS, DynamoDB, EFS, S3) oraz zasobów on-premises. Pozwala definiować zasady (plany) tworzenia kopii na poziomie organizacji i stosować je automatycznie w wielu kontach i regionach AWS, z centralnym monitorowaniem. Na egzaminie: „centralne zarządzanie kopiami zapasowymi wielu usług” → AWS Backup.", "en": "A centralized service for automating and managing backups across many AWS services (e.g. EC2, EBS, RDS, DynamoDB, EFS, S3) and on-premises resources. You can define backup policies (plans) at the organization level and apply them automatically across multiple AWS accounts and Regions, with central monitoring. On the exam: “centrally manage backups across services” → AWS Backup."},
{"name": "AWS Elastic Disaster Recovery", "category": "Pamięć masowa", "kind": "usługa", "module": 6, "pl": "W pełni zarządzana usługa odtwarzania po awarii, która stale replikuje dane blokowe serwerów fizycznych, wirtualnych i chmurowych do AWS. W razie awarii pozwala uruchomić odtworzone serwery w AWS w ciągu minut, a testy odtwarzania można prowadzić bez zakłócania pracy. Eliminuje koszt utrzymywania zapasowego centrum danych – płacisz tylko za faktyczne użycie; przykłady: szpitale, banki, zakłady produkcyjne.", "en": "A fully managed disaster recovery service that continuously replicates the block-level data of physical, virtual and cloud-based servers to AWS. In a disruption you can launch recovered servers in AWS within minutes, and you can run non-disruptive recovery drills. It eliminates the cost of a secondary data center – you pay only for what you use; examples: hospitals, banks, manufacturers."},
{"name": "AWS Storage Gateway", "category": "Pamięć masowa", "kind": "usługa", "module": 6, "pl": "Usługa chmury hybrydowej, która łączy środowisko on-premises z pamięcią masową AWS i daje lokalnym aplikacjom dostęp do praktycznie nieograniczonej przestrzeni w chmurze. Często używane dane trzyma lokalnie w pamięci podręcznej, aby zapewnić niskie opóźnienia. Ma trzy typy bram: S3 File Gateway (pliki), Volume Gateway (woluminy iSCSI) i Tape Gateway (wirtualne taśmy); zastosowania: kopie zapasowe w chmurze, udziały plikowe oparte na chmurze, odtwarzanie po awarii.", "en": "A hybrid cloud storage service that connects on-premises environments with AWS storage, giving local applications access to virtually unlimited cloud storage. It caches frequently accessed data locally for low-latency access. It has three gateway types: S3 File Gateway (files), Volume Gateway (iSCSI volumes) and Tape Gateway (virtual tapes); use cases: moving backups to the cloud, cloud-backed file shares, disaster recovery."},
{"name": "Block storage / Pamięć blokowa", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Typ pamięci, w którym dane są zapisywane w blokach na woluminach podłączanych do instancji EC2 jak fizyczne dyski twarde. Zapewnia niskie opóźnienia i nadaje się do systemów operacyjnych, baz danych i aplikacji transakcyjnych. Usługi blokowe w AWS to Amazon EBS (trwała) i magazyn instancji EC2 (tymczasowy).", "en": "A storage type in which data is stored in blocks on volumes that attach to EC2 instances like physical hard drives. It provides low latency and suits operating systems, databases and transactional applications. AWS block storage options are Amazon EBS (persistent) and EC2 instance store (temporary)."},
{"name": "File storage / Pamięć plikowa", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Współdzielone systemy plików dostępne przez sieć, z których wielu użytkowników, aplikacji i instancji może korzystać jednocześnie. Dane są zorganizowane hierarchicznie w katalogi i pliki, a pojemność rośnie bez zarządzania sprzętem. Usługi plikowe w AWS to Amazon EFS (NFS, Linux) i Amazon FSx (Windows, Lustre, NetApp ONTAP, OpenZFS).", "en": "Shared file systems accessible over the network so that many users, applications and instances can access the same data at the same time. Data is organized hierarchically in directories and files, and capacity grows without managing hardware. AWS file storage services are Amazon EFS (NFS, Linux) and Amazon FSx (Windows, Lustre, NetApp ONTAP, OpenZFS)."},
{"name": "Object storage / Pamięć obiektowa", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Architektura, w której dane są przechowywane jako obiekty (dane + metadane + unikalny klucz) w płaskiej przestrzeni adresowej, bez hierarchii katalogów jak w systemie plików. Oferuje praktycznie nieograniczoną skalowalność i bogate metadane, więc świetnie nadaje się do dużych ilości danych nieustrukturyzowanych: dokumentów, zdjęć, filmów, kopii zapasowych. Główna usługa: Amazon S3.", "en": "An architecture that stores data as objects (data + metadata + a unique key) in a flat address space, without a directory hierarchy like a file system. It offers virtually unlimited scalability and rich metadata, so it is ideal for large amounts of unstructured data: documents, images, videos, backups. Primary service: Amazon S3."},
{"name": "S3 bucket policy / Polityka bucketa S3", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Polityka oparta na zasobach (resource-based) w formacie JSON, dołączana wyłącznie do bucketa S3; określa, jakie akcje są dozwolone lub zabronione na buckecie i wszystkich jego obiektach, np. dostęp z innego konta. Uzupełniają ją polityki oparte na tożsamości (identity-based) dołączane do użytkowników, grup i ról IAM. Pamiętaj: wszystko w S3 jest domyślnie prywatne – dostęp trzeba jawnie przyznać.", "en": "A resource-based JSON policy that can be attached only to an S3 bucket; it specifies which actions are allowed or denied on the bucket and every object in it, e.g. cross-account access. It is complemented by identity-based policies attached to IAM users, groups and roles. Remember: everything in S3 is private by default – access must be explicitly granted."},
{"name": "S3 Express One Zone", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Klasa o wysokiej wydajności przechowująca dane w jednej AZ, zaprojektowana dla najczęściej używanych danych i aplikacji wrażliwych na opóźnienia. Zapewnia stały dostęp w pojedynczych milisekundach – do 10 razy szybciej i z kosztami żądań do 80% niższymi niż S3 Standard. Przydaje się m.in. przy intensywnej analityce i uczeniu maszynowym wymagających bardzo szybkiego dostępu.", "en": "A high-performance storage class that keeps data in a single AZ, purpose-built for your most frequently accessed data and latency-sensitive applications. It delivers consistent single-digit millisecond access – up to 10x faster and with request costs up to 80% lower than S3 Standard. It is useful for compute-intensive analytics and machine learning that need very fast access."},
{"name": "S3 Glacier Deep Archive", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Najtańsza klasa pamięci w Amazon S3, przeznaczona do długoterminowego przechowywania i archiwizacji danych używanych najwyżej raz lub dwa razy w roku. Domyślny czas odzyskania danych to 12 godzin. Typowo dla danych przechowywanych przez 7–10 lat lub dłużej ze względu na przepisy – w finansach, ochronie zdrowia, sektorze publicznym; zastępuje archiwa taśmowe.", "en": "The lowest-cost Amazon S3 storage class, designed for long-term retention and digital preservation of data accessed once or twice a year at most. The default retrieval time is 12 hours. Typical for data kept for 7–10 years or longer to meet regulatory requirements – in financial services, healthcare and the public sector; it replaces tape archives."},
{"name": "S3 Glacier Flexible Retrieval", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Tania klasa archiwalna dla danych używanych 1–2 razy w roku, przy których nie potrzeba natychmiastowego dostępu. Dane można odzyskać w 1–5 minut (odczyt przyspieszony, expedited) albo bez dodatkowych opłat w trybie zbiorczym (bulk) w 5–12 godzin. Zastosowania: kopie zapasowe, odtwarzanie po awarii, przechowywanie danych poza siedzibą firmy.", "en": "A low-cost archive storage class for data accessed 1–2 times a year that does not need immediate access. Data can be retrieved in 1–5 minutes with expedited retrieval or at no additional cost with bulk retrieval in 5–12 hours. Use cases: backups, disaster recovery, offsite data storage."},
{"name": "S3 Glacier Instant Retrieval", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Klasa archiwalna dla danych używanych bardzo rzadko, które jednak trzeba odczytać w milisekundach. Kosztuje do 68% mniej niż S3 Standard-IA przy takich samych opóźnieniach i przepustowości. Przykład: archiwum zdjęć medycznych lub materiałów medialnych, do którego sięga się raz na kwartał, ale wtedy natychmiast.", "en": "An archive storage class for rarely accessed data that still requires millisecond retrieval. It costs up to 68% less than S3 Standard-IA with the same latency and throughput. Example: an archive of medical images or media assets accessed about once a quarter, but needed immediately when it is."},
{"name": "S3 Intelligent-Tiering", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Klasa dla danych o nieznanym lub zmiennym wzorcu dostępu. S3 monitoruje, jak często używasz obiektów, i automatycznie przenosi je między warstwami: częstego dostępu, rzadkiego dostępu i archiwum z natychmiastowym dostępem – do najtańszej odpowiedniej. Wskazówka egzaminacyjna: „nieprzewidywalny dostęp” + „automatyczna optymalizacja kosztów” = Intelligent-Tiering.", "en": "A storage class for data with unknown or changing access patterns. S3 monitors how often objects are accessed and automatically moves them between a frequent access tier, an infrequent access tier and an archive instant access tier – to the most cost-effective one. Exam cue: unpredictable access + automatic cost optimization = Intelligent-Tiering."},
{"name": "S3 Lifecycle / Cykl życia S3", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Konfiguracja reguł, która automatycznie zarządza obiektami w czasie, bez ręcznej pracy. Akcje przejścia (transition) przenoszą obiekty do tańszej klasy pamięci po określonym czasie, a akcje wygaśnięcia (expiration) trwale je usuwają. Przykład: po 30 dniach Standard → Standard-IA, po kolejnych 60 dniach → Glacier Instant Retrieval, po 365 dniach usunięcie; zastosowania: logi i dokumenty potrzebne z czasem coraz rzadziej.", "en": "A set of rules that automatically manages objects over time without manual work. Transition actions move objects to a cheaper storage class after a set period, and expiration actions permanently delete them. Example: after 30 days Standard → Standard-IA, after 60 more days → Glacier Instant Retrieval, after 365 days delete; use cases: periodic logs and documents that are accessed less and less often."},
{"name": "S3 One Zone-Infrequent Access (S3 One Zone-IA)", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Klasa dla rzadko używanych danych przechowywanych tylko w jednej strefie dostępności, dzięki czemu jest tańsza od S3 Standard-IA (która używa trzech AZ). Nie chroni przed utratą całej AZ, więc nadaje się do danych, które łatwo odtworzyć, lub do zapasowych kopii kopii zapasowych. Wskazówka egzaminacyjna: „łatwe do odtworzenia” + „najtańszy rzadki dostęp”.", "en": "A storage class for infrequently accessed data stored in a single Availability Zone, which makes it cheaper than S3 Standard-IA (which uses three AZs). It does not protect against the loss of an entire AZ, so it suits easily re-creatable data or secondary backup copies. Exam cue: easily re-creatable + lowest-cost infrequent access."},
{"name": "S3 Standard", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Domyślna klasa pamięci ogólnego przeznaczenia dla często używanych danych – obiekt bez wskazanej klasy trafia właśnie tutaj. Zapewnia wysoką trwałość, dostępność i wydajność, a dane są przechowywane w co najmniej trzech AZ. Zastosowania: aplikacje chmurowe, dynamiczne strony, dystrybucja treści, gry i aplikacje mobilne, analiza big data.", "en": "The default general-purpose storage class for frequently accessed data – objects uploaded without a storage class land here. It offers high durability, availability and performance, with data stored across at least three AZs. Use cases: cloud applications, dynamic websites, content distribution, mobile and gaming apps, big data analytics."},
{"name": "S3 Standard-Infrequent Access (S3 Standard-IA)", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Klasa dla danych używanych rzadko, ale wymagających szybkiego dostępu, gdy są potrzebne. Ma tę samą wysoką trwałość, przepustowość i niskie opóźnienia co S3 Standard (dane w trzech AZ), ale niższą cenę za GB przechowywania i dodatkową opłatę za GB odczytu. Zastosowania: długoterminowe kopie zapasowe, pliki do odtwarzania po awarii.", "en": "A storage class for data accessed less frequently but requiring rapid access when needed. It has the same high durability, throughput and low latency as S3 Standard (data in three AZs), but a lower per-GB storage price plus a per-GB retrieval fee. Use cases: long-term backups, disaster recovery files."},
{"name": "S3 static website hosting / Hosting statycznych stron w S3", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Funkcja S3, która pozwala udostępnić stronę WWW złożoną z plików statycznych (HTML, CSS, JavaScript, obrazy) bezpośrednio z bucketa – bez serwerów. Wystarczy przesłać pliki i włączyć hosting statycznej strony w ustawieniach bucketa. S3 automatycznie skaluje się przy dowolnym ruchu, a płacisz za przechowywanie i transfer danych; często łączy się to z CloudFront.", "en": "An S3 feature that serves a website made of static files (HTML, CSS, JavaScript, images) directly from a bucket – no servers needed. You just upload the files and enable static website hosting in the bucket settings. S3 scales automatically to any traffic, and you pay for storage and data transferred out; it is often combined with CloudFront."},
{"name": "S3 Versioning / Wersjonowanie S3", "category": "Pamięć masowa", "kind": "pojęcie", "module": 6, "pl": "Funkcja bucketa, która przechowuje wiele wersji tego samego obiektu – każda zmiana lub usunięcie tworzy nową wersję, zamiast nadpisywać dane. Pozwala odzyskać pliki po przypadkowym usunięciu lub niechcianej modyfikacji. Włącza się ją w ustawieniach bucketa; każda wersja ma własny identyfikator (version ID).", "en": "A bucket feature that keeps multiple versions of the same object – every change or deletion creates a new version instead of overwriting data. It lets you recover from unintended deletions or modifications. You enable it in the bucket settings; each version has its own version ID."},
{"name": "Tape Gateway", "category": "Pamięć masowa", "kind": "usługa", "module": 6, "pl": "Typ Storage Gateway, który zastępuje fizyczne taśmy wirtualnymi: dla oprogramowania do kopii zapasowych wygląda jak zwykły sprzęt taśmowy, a dane są zapisywane w Amazon S3. Nie trzeba zmieniać istniejących procesów tworzenia kopii zapasowych. Rzadziej używane dane może automatycznie przenosić do tańszej klasy pamięci (archiwum) na potrzeby długoterminowego przechowywania.", "en": "A Storage Gateway type that replaces physical tapes with virtual ones: to backup software it looks like standard tape hardware, while the data is stored in Amazon S3. Existing backup processes don’t need to change. It can automatically move less frequently accessed data to a cheaper (archive) storage class for long-term retention."},
{"name": "Volume Gateway", "category": "Pamięć masowa", "kind": "usługa", "module": 6, "pl": "Typ Storage Gateway, który udostępnia lokalnym aplikacjom woluminy blokowe iSCSI oparte na pamięci w chmurze. Działa w dwóch trybach: buforowanym (cached) – główne dane w chmurze, a często używane w lokalnej pamięci podręcznej – oraz przechowywanym (stored) – cały zbiór danych lokalnie, z asynchroniczną kopią w chmurze w postaci migawek EBS.", "en": "A Storage Gateway type that presents cloud-backed iSCSI block volumes to on-premises applications. It works in two modes: cached – primary data in the cloud with frequently accessed data cached locally – and stored – the complete dataset kept locally and asynchronously backed up to the cloud as EBS snapshots."},
{"name": "Amazon Aurora", "category": "Bazy danych", "kind": "usługa", "module": 7, "pl": "Zarządzana relacyjna baza danych stworzona przez AWS, zgodna z MySQL i PostgreSQL. Zapewnia do 5 razy większą przepustowość niż standardowy MySQL i do 3 razy większą niż PostgreSQL, przy koszcie ok. 1/10 komercyjnych baz klasy enterprise. Przechowuje 6 kopii danych w 3 strefach dostępności (dostępność 99,99%), sama powiększa pamięć od 10 GB do 128 TB i stale tworzy kopie zapasowe w Amazon S3. Zastosowania: zastąpienie drogich komercyjnych baz, gry, zarządzanie treścią, analityka w czasie rzeczywistym.", "en": "A managed relational database built by AWS, compatible with MySQL and PostgreSQL. It delivers up to five times the throughput of standard MySQL and three times that of PostgreSQL, at about one-tenth the cost of commercial enterprise databases. It keeps six copies of data across three Availability Zones (99.99% availability), automatically grows storage from 10 GB to 128 TB, and continuously backs up to Amazon S3. Use cases: replacing costly commercial databases, gaming, content management, real-time analytics."},
{"name": "Amazon DocumentDB (with MongoDB compatibility)", "category": "Bazy danych", "kind": "usługa", "module": 7, "pl": "W pełni zarządzana dokumentowa baza danych zgodna z MongoDB, przeznaczona do krytycznych obciążeń i automatycznie skalowana. Dobrze radzi sobie z danymi półustrukturyzowanymi (dokumenty JSON). Typowe zastosowania: katalogi produktów w e-commerce, zarządzanie treścią, profile użytkowników. Na egzaminie: „MongoDB” lub „dokumenty JSON” → DocumentDB.", "en": "A fully managed, MongoDB-compatible document database designed for mission-critical workloads with automatic scaling. It handles semistructured data (JSON documents) well. Typical use cases: e-commerce product catalogs, content management, user profiles. On the exam: “MongoDB” or “JSON documents” → DocumentDB."},
{"name": "Amazon DynamoDB", "category": "Bazy danych", "kind": "usługa", "module": 7, "pl": "W pełni zarządzana, bezserwerowa baza NoSQL typu klucz–wartość i dokumentowa. Daje czasy odpowiedzi rzędu pojedynczych milisekund w dowolnej skali, automatycznie skaluje przepustowość i nie ma praktycznych limitów rozmiaru tabeli. Replikuje dane między kilkoma obiektami w regionie (i opcjonalnie między regionami) oraz domyślnie szyfruje dane. Zastosowania: gry, aplikacje finansowe, aplikacje mobilne z globalną bazą użytkowników.", "en": "A fully managed, serverless NoSQL key-value and document database. It delivers single-digit millisecond response times at any scale, automatically scales throughput, and has no practical limits on table size. It replicates data across multiple facilities within a Region (and optionally across Regions) and encrypts data by default. Use cases: gaming, financial services applications, mobile apps with global user bases."},
{"name": "Amazon ElastiCache", "category": "Bazy danych", "kind": "usługa", "module": 7, "pl": "W pełni zarządzana usługa pamięci podręcznej w pamięci RAM, zgodna z Redis, Valkey i Memcached. Zapewnia opóźnienia poniżej milisekundy, odciąża bazę danych i przyspiesza aplikację. Sama wykrywa i zastępuje uszkodzone węzły, przy awarii promuje replikę na węzeł główny, może replikować dane między strefami dostępności i szyfruje dane. Zastosowania: dane sesji, przyspieszanie zapytań do bazy, rankingi w grach.", "en": "A fully managed in-memory caching service compatible with Redis, Valkey and Memcached. It provides sub-millisecond latency, reduces database load and speeds up applications. It automatically detects and replaces failed nodes, promotes a replica to primary on failure, can replicate across Availability Zones, and encrypts data. Use cases: session data, speeding up database queries, gaming leaderboards."},
{"name": "Amazon Neptune", "category": "Bazy danych", "kind": "usługa", "module": 7, "pl": "W pełni zarządzana grafowa baza danych, zoptymalizowana do przechowywania i odpytywania silnie powiązanych danych z opóźnieniem rzędu milisekund. Sprawdza się tam, gdzie liczą się relacje między obiektami: sieci społecznościowe, silniki rekomendacji, wykrywanie oszustw, grafy wiedzy. Na egzaminie: „relacje”, „powiązania”, „graf” → Neptune.", "en": "A fully managed graph database optimized for storing and querying highly connected data with millisecond latency. It fits cases where relationships between entities matter: social networks, recommendation engines, fraud detection, knowledge graphs. On the exam: “relationships”, “connections”, “graph” → Neptune."},
{"name": "Amazon Relational Database Service (Amazon RDS)", "category": "Bazy danych", "kind": "usługa", "module": 7, "pl": "Zarządzana usługa relacyjnych baz danych w chmurze. AWS automatyzuje rutynowe zadania: kopie zapasowe, łatki i provisioning sprzętu. Obsługuje silniki Amazon Aurora, MySQL, PostgreSQL, MariaDB, Oracle Database i Microsoft SQL Server. Oferuje wdrożenia Multi-AZ, automatyczne kopie i migawki (DB snapshots), repliki do odczytu, izolację w VPC oraz szyfrowanie w spoczynku i w tranzycie. Zastosowania: aplikacje webowe, systemy firmowe, katalogi produktów w e-commerce.", "en": "A managed relational database service in the cloud. AWS automates routine tasks such as backups, patching and hardware provisioning. It supports the Amazon Aurora, MySQL, PostgreSQL, MariaDB, Oracle Database and Microsoft SQL Server engines. It offers Multi-AZ deployments, automated backups and DB snapshots, read replicas, VPC isolation, and encryption at rest and in transit. Use cases: web applications, enterprise workloads, e-commerce product inventories."},
{"name": "Automated backups and DB snapshots (Amazon RDS) / Kopie automatyczne i migawki bazy", "category": "Bazy danych", "kind": "pojęcie", "module": 7, "pl": "Dwa sposoby tworzenia kopii zapasowych w Amazon RDS. Kopie automatyczne RDS wykonuje sam i pozwalają one odtworzyć bazę do wybranego momentu (point-in-time recovery). Migawki (DB snapshots) tworzysz ręcznie – to pełne kopie całej instancji bazy, przydatne do odtworzenia stanu z konkretnej chwili lub długoterminowej archiwizacji.", "en": "Two ways to back up Amazon RDS. Automated backups are performed by RDS and allow point-in-time recovery. DB snapshots are created manually – they are full backups of the entire database instance, useful for restoring a specific point in time or for long-term archiving."},
{"name": "Database on Amazon EC2 (lift and shift) / Baza danych na instancji EC2", "category": "Bazy danych", "kind": "pojęcie", "module": 7, "pl": "Przeniesienie istniejącej bazy danych z serwerowni on-premises na instancję Amazon EC2 bez zmian („lift and shift”). To rozwiązanie niezarządzane: masz pełną kontrolę nad systemem operacyjnym, instalacją i konfiguracją bazy, ale sam(a) odpowiadasz za łatki, kopie zapasowe, bezpieczeństwo i wysoką dostępność. Wybierz je, gdy potrzebujesz dostępu do systemu operacyjnego lub konfiguracji niedostępnej w usługach zarządzanych.", "en": "Moving an existing on-premises database onto an Amazon EC2 instance as is (“lift and shift”). It is an unmanaged option: you get full control over the operating system, database installation and configuration, but you are responsible for patching, backups, security and high availability. Choose it when you need OS-level access or configuration that managed services don’t allow."},
{"name": "Fully managed vs managed vs unmanaged databases / Bazy w pełni zarządzane, zarządzane i niezarządzane", "category": "Bazy danych", "kind": "pojęcie", "module": 7, "pl": "Podział usług wg modelu współdzielonej odpowiedzialności. W pełni zarządzane (np. DynamoDB): AWS robi prawie wszystko – provisioning, skalowanie, łatki, kopie zapasowe – a Ty odpowiadasz tylko za projekt struktur danych i kontrolę dostępu. Zarządzane (np. RDS): AWS dba o kopie, łatki i sprzęt, a Ty o konfigurację bazy, optymalizację zapytań i strojenie wydajności. Niezarządzane (baza zainstalowana na EC2): wszystko – instalacja, łatki, bezpieczeństwo, kopie, wysoka dostępność – należy do Ciebie.", "en": "Categories of services under the shared responsibility model. Fully managed (e.g. DynamoDB): AWS handles nearly everything – provisioning, scaling, patching, backups – and you are responsible only for designing data structures and managing access controls. Managed (e.g. RDS): AWS handles backups, patching and hardware, while you handle database configuration, query optimization and performance tuning. Unmanaged (a database installed on EC2): installation, patching, security, backups and high availability are all on you."},
{"name": "In-memory cache / Pamięć podręczna w pamięci RAM", "category": "Bazy danych", "kind": "pojęcie", "module": 7, "pl": "Szybka warstwa przechowywania, która tymczasowo trzyma często używane dane w pamięci operacyjnej (RAM) zamiast na dysku. Aplikacja najpierw sprawdza cache, a dopiero potem pyta główną bazę danych, co skraca czas odpowiedzi i odciąża bazę. Typowo przechowuje dane sesji, odpowiedzi API i wyniki zapytań. W AWS: Amazon ElastiCache.", "en": "A high-speed storage layer that temporarily keeps frequently accessed data in main memory (RAM) instead of on disk. Applications check the cache first before querying the primary database, which speeds up responses and reduces database load. Typical contents are session data, API responses and query results. On AWS: Amazon ElastiCache."},
{"name": "Multi-AZ deployment (Amazon RDS) / Wdrożenie Multi-AZ", "category": "Bazy danych", "kind": "pojęcie", "module": 7, "pl": "Funkcja Amazon RDS, która automatycznie replikuje dane do instancji rezerwowej (standby) w innej strefie dostępności. Przy awarii, konserwacji lub problemie ze strefą RDS sam przełącza ruch na instancję rezerwową (failover), bez ręcznej interwencji i z minimalnym przestojem. Służy wysokiej dostępności i niezawodności, a nie skalowaniu odczytów – do tego są repliki do odczytu.", "en": "An Amazon RDS feature that automatically replicates data to a standby instance in a different Availability Zone. During failures, maintenance or zone disruptions, RDS automatically fails over to the standby without manual intervention and with minimal downtime. It is for high availability and reliability, not for scaling reads – read replicas do that."},
{"name": "NoSQL (nonrelational) database / Nierelacyjna baza danych", "category": "Bazy danych", "kind": "pojęcie", "module": 7, "pl": "Baza danych z elastycznym schematem, która nie opiera się na tabelach z relacjami. Dane są zapisywane np. jako pary klucz–wartość: element ma unikalny klucz i dowolny zestaw atrybutów, które można dodawać lub usuwać w każdej chwili, a elementy nie muszą mieć takich samych atrybutów. Inne modele NoSQL to bazy dokumentowe (DocumentDB) i grafowe (Neptune). Kluczowa różnica wobec baz relacyjnych to elastyczny schemat zamiast sztywnej struktury tabel.", "en": "A database with a flexible schema that does not rely on related tables. Data can be stored, for example, as key-value pairs: each item has a unique key and any set of attributes, which can be added or removed at any time, and items don’t need the same attributes. Other NoSQL models include document (DocumentDB) and graph (Neptune) databases. The key difference from relational databases is a flexible schema instead of rigid table structures."},
{"name": "Read replica / Replika do odczytu", "category": "Bazy danych", "kind": "pojęcie", "module": 7, "pl": "Kopia bazy danych (np. w Amazon RDS lub Aurora), która obsługuje wyłącznie zapytania odczytu. Przejmuje część ruchu odczytu z instancji głównej, dzięki czemu poprawia wydajność aplikacji z dużą liczbą odczytów. Na egzaminie: repliki do odczytu = skalowanie wydajności odczytów, Multi-AZ = wysoka dostępność.", "en": "A copy of a database (for example in Amazon RDS or Aurora) that serves read queries only. It offloads read traffic from the primary instance, improving performance for read-heavy applications. On the exam: read replicas = scaling read performance, Multi-AZ = high availability."},
{"name": "Relational database / Relacyjna baza danych", "category": "Bazy danych", "kind": "pojęcie", "module": 7, "pl": "Baza danych o sztywnym schemacie, która przechowuje dane w tabelach z wierszami i kolumnami oraz definiuje relacje między tabelami. Do zarządzania danymi i zapytań używa języka SQL. Sprawdza się przy danych ustrukturyzowanych i transakcyjnych, np. zamówieniach, zapasach czy systemach księgowych. W AWS: Amazon RDS i Amazon Aurora.", "en": "A database with a rigid schema that organizes data into tables with rows and columns, with relationships defined between tables. It uses SQL to manage and query data. It is a good fit for structured, transactional data such as orders, inventory or accounting. On AWS: Amazon RDS and Amazon Aurora."},
{"name": "SQL (Structured Query Language)", "category": "Bazy danych", "kind": "pojęcie", "module": 7, "pl": "Strukturalny język zapytań – standardowy sposób pracy z relacyjnymi bazami danych (tworzenie tabel, wstawianie, odczyt i łączenie danych). Działa w silnikach takich jak MySQL, PostgreSQL czy Microsoft SQL Server. Na egzaminie „SQL” zwykle wskazuje na bazę relacyjną (RDS, Aurora) albo na zapytania analityczne (Athena, Redshift).", "en": "Structured Query Language – the standard way to work with relational databases (creating tables, inserting, reading and joining data). It runs on engines such as MySQL, PostgreSQL and Microsoft SQL Server. On the exam, “SQL” usually points to a relational database (RDS, Aurora) or to analytical queries (Athena, Redshift)."},
{"name": "Amazon Bedrock", "category": "AI/ML i generatywna AI", "kind": "usługa", "module": 8, "pl": "W pełni zarządzana usługa do budowania aplikacji generatywnej AI na modelach podstawowych (FM) od Amazon i wiodących firm AI (np. Claude, Stable Diffusion), dostępnych przez jedno, ujednolicone API. Pozwala eksperymentować z modelami, dostrajać je własnymi danymi i integrować z aplikacjami AWS bez zarządzania infrastrukturą, z bezpieczeństwem i prywatnością klasy enterprise. Zastosowania: produkcyjne aplikacje generatywnej AI, generowanie treści multimodalnych, zaawansowani asystenci konwersacyjni.", "en": "A fully managed service for building generative AI applications on foundation models (FMs) from Amazon and leading AI companies (e.g. Claude, Stable Diffusion), accessed through a single unified API. You can experiment with models, fine-tune them with your own data, and integrate them into AWS applications without managing infrastructure, with enterprise-grade security and privacy. Use cases: production generative AI apps, multimodal content generation, advanced conversational agents."},
{"name": "Amazon Comprehend", "category": "AI/ML i generatywna AI", "kind": "usługa", "module": 8, "pl": "Usługa przetwarzania języka naturalnego (NLP), która wyciąga z tekstu i dokumentów kluczowe informacje: frazy kluczowe, język, wydźwięk (sentiment), encje i inne elementy. Zastosowania: klasyfikacja treści, analiza opinii klientów, monitorowanie zgodności. Na egzaminie: „analiza wydźwięku/sentymentu tekstu” → Comprehend.", "en": "A natural language processing (NLP) service that extracts key insights from text and documents: key phrases, language, sentiment, entities and other elements. Use cases: content classification, customer sentiment analysis, compliance monitoring. On the exam: “sentiment analysis of text” → Comprehend."},
{"name": "Amazon Kendra", "category": "AI/ML i generatywna AI", "kind": "usługa", "module": 8, "pl": "Inteligentna wyszukiwarka dla firmowych treści, oparta na przetwarzaniu języka naturalnego. Rozumie kontekst pytania, więc zwraca konkretne, trafne odpowiedzi z dużych zbiorów dokumentów, a nie tylko listę dokumentów z pasującymi słowami. Zastosowania: inteligentne wyszukiwanie w firmie, chatboty, wyszukiwanie w aplikacjach.", "en": "An intelligent enterprise search service powered by natural language processing. It understands the context of a query, so it returns precise, relevant answers from large amounts of enterprise content rather than just a list of documents with matching keywords. Use cases: intelligent enterprise search, chatbots, application search integration."},
{"name": "Amazon Lex", "category": "AI/ML i generatywna AI", "kind": "usługa", "module": 8, "pl": "Usługa do dodawania do aplikacji konwersacyjnych interfejsów głosowych i tekstowych (chatbotów). Łączy rozumienie języka naturalnego (NLU) z automatycznym rozpoznawaniem mowy (ASR), aby prowadzić naturalne rozmowy. Zastosowania: wirtualni asystenci, wyszukiwanie odpowiedzi w FAQ, boty w aplikacjach i call center.", "en": "A service for adding voice and text conversational interfaces (chatbots) to applications. It combines natural language understanding (NLU) with automatic speech recognition (ASR) to create lifelike conversations. Use cases: virtual assistants, natural language FAQ search, application and contact center bots."},
{"name": "Amazon Personalize", "category": "AI/ML i generatywna AI", "kind": "usługa", "module": 8, "pl": "Usługa, która na podstawie danych historycznych tworzy spersonalizowane rekomendacje dla klientów, bez potrzeby budowania własnych modeli ML. Zastosowania: rekomendacje produktów, treści w serwisach streamingowych, popularne pozycje. Na egzaminie: „rekomendacje dla użytkowników” → Personalize.", "en": "A service that uses historical data to build personalized recommendations for customers, without building your own ML models. Use cases: product recommendations, streaming content, trending items. On the exam: “recommendations for users” → Personalize."},
{"name": "Amazon Polly", "category": "AI/ML i generatywna AI", "kind": "usługa", "module": 8, "pl": "Usługa zamiany tekstu na realistyczną mowę (text-to-speech). Obsługuje wiele języków, różne głosy i akcenty. Zastosowania: wirtualni asystenci, e-learning, ułatwienia dostępu dla osób słabowidzących. Na egzaminie: tekst → mowa = Polly, mowa → tekst = Transcribe.", "en": "A service that converts text into lifelike speech (text-to-speech). It supports multiple languages, different voices and accents. Use cases: virtual assistants, e-learning applications, accessibility for visually impaired users. On the exam: text → speech = Polly, speech → text = Transcribe."},
{"name": "Amazon Q Business", "category": "AI/ML i generatywna AI", "kind": "usługa", "module": 8, "pl": "Asystent generatywnej AI dla pracowników firmy, połączony z jej repozytoriami informacji i popularnymi systemami. Odpowiada na pytania, pomaga rozwiązywać problemy i wykonywać działania na podstawie danych i wiedzy firmy. Zastosowania: obsługa zapytań o informacje, automatyzacja przepływów pracy, wyciąganie wniosków z danych.", "en": "A generative AI assistant for company employees, connected to the company’s information repositories and commonly used systems. It answers questions, helps solve problems and takes actions using the company’s data and expertise. Use cases: information requests, automated workflows, insight extraction."},
{"name": "Amazon Q Developer", "category": "AI/ML i generatywna AI", "kind": "usługa", "module": 8, "pl": "Asystent generatywnej AI dla programistów, zintegrowany z wieloma środowiskami IDE. Podpowiada kod i generuje całe funkcje oraz bloki logiki m.in. w C#, Javie, JavaScripcie, Pythonie i TypeScripcie. Zastosowania: szybsze pisanie kodu, poprawa niezawodności i bezpieczeństwa, automatyczne przeglądy kodu.", "en": "A generative AI assistant for developers that integrates with multiple IDEs. It provides code recommendations and generates entire functions and logical blocks of code in languages including C#, Java, JavaScript, Python and TypeScript. Use cases: faster code generation, improved reliability and security, automated code reviews."},
{"name": "Amazon Rekognition", "category": "AI/ML i generatywna AI", "kind": "usługa", "module": 8, "pl": "Usługa analizy obrazów i wideo (widzenie komputerowe). Rozpoznaje obiekty, osoby, twarze, tekst, sceny i czynności na obrazach i filmach, np. przechowywanych w Amazon S3. Zastosowania: moderacja treści, weryfikacja tożsamości, analiza mediów, inteligentny dom. Na egzaminie: „rozpoznawanie twarzy/obiektów na zdjęciach lub wideo” → Rekognition.", "en": "An image and video analysis service (computer vision). It identifies objects, people, faces, text, scenes and activities in images and videos, for example those stored in Amazon S3. Use cases: content moderation, identity verification, media analysis, home automation. On the exam: “recognize faces/objects in images or video” → Rekognition."},
{"name": "Amazon SageMaker AI", "category": "AI/ML i generatywna AI", "kind": "usługa", "module": 8, "pl": "W pełni zarządzana usługa do budowania, trenowania i wdrażania własnych modeli ML bez zarządzania infrastrukturą – środkowa warstwa stosu AI/ML AWS. Oferuje zintegrowane środowisko (IDE) dla data scientistów i interfejs bez kodu dla analityków biznesowych, śledzenie eksperymentów, wizualizację danych, debugowanie, monitorowanie oraz setki wstępnie wytrenowanych modeli. Pomaga automatyzować i standaryzować praktyki MLOps i nadzór nad modelami.", "en": "A fully managed service to build, train and deploy your own ML models without managing infrastructure – the middle tier of the AWS AI/ML stack. It offers an integrated development environment (IDE) for data scientists and a no-code interface for business analysts, experiment tracking, data visualization, debugging, monitoring, and hundreds of pre-trained models. It helps automate and standardize MLOps practices and model governance."},
{"name": "Amazon SageMaker JumpStart", "category": "AI/ML i generatywna AI", "kind": "usługa", "module": 8, "pl": "Centrum (hub) uczenia maszynowego w SageMaker AI z biblioteką wstępnie wytrenowanych modeli, modeli podstawowych (FM) i gotowych rozwiązań ML, np. do widzenia komputerowego, NLP i danych tabelarycznych. Modele można dostroić własnymi danymi i wdrożyć kilkoma kliknięciami. Zastosowania: szybkie wdrożenia bez dużej wiedzy z ML, dostrajanie FM, eksperymenty i prototypy.", "en": "A machine learning hub within SageMaker AI with a library of pre-trained models, foundation models (FMs) and pre-built ML solutions, e.g. for computer vision, NLP and tabular data. Models can be fine-tuned with your own data and deployed in a few clicks. Use cases: rapid deployments without deep ML expertise, fine-tuning FMs, experiments and prototypes."},
{"name": "Amazon Textract", "category": "AI/ML i generatywna AI", "kind": "usługa", "module": 8, "pl": "Usługa, która wykrywa i wyodrębnia tekst drukowany i odręczny z dokumentów, w tym dane z formularzy i tabel – więcej niż zwykłe OCR. Zastosowania: szybkie przetwarzanie formularzy finansowych, medycznych i urzędowych. Na egzaminie: „wyciągnij dane ze skanów/formularzy” → Textract.", "en": "A service that detects and extracts typed and handwritten text from documents, including data from forms and tables – more than plain OCR. Use cases: fast processing of financial, healthcare and government forms. On the exam: “extract data from scanned documents/forms” → Textract."},
{"name": "Amazon Transcribe", "category": "AI/ML i generatywna AI", "kind": "usługa", "module": 8, "pl": "Usługa zamiany mowy na tekst (speech-to-text). Obsługuje wiele języków i oferuje m.in. rozpoznawanie mówców, własne słowniki i transkrypcję w czasie rzeczywistym. Zastosowania: transkrypcja rozmów z klientami, automatyczne napisy, generowanie metadanych do materiałów multimedialnych.", "en": "A service that converts speech into text (speech-to-text). It supports multiple languages and offers features such as speaker identification, custom vocabulary and real-time transcription. Use cases: customer call transcription, automated subtitling, metadata generation for media content."},
{"name": "Amazon Translate", "category": "AI/ML i generatywna AI", "kind": "usługa", "module": 8, "pl": "Usługa tłumaczenia maszynowego tekstu między wieloma językami, w czasie rzeczywistym lub wsadowo. Zastosowania: tłumaczenie dokumentów, aplikacje wielojęzyczne, komunikacja globalna. Tłumaczy tekst – do mowy służą Transcribe i Polly.", "en": "A text translation service across multiple languages, in real time or in batches. Use cases: document translation, multi-language applications, global communication. It translates text – Transcribe and Polly handle speech."},
{"name": "Artificial intelligence (AI) / Sztuczna inteligencja", "category": "AI/ML i generatywna AI", "kind": "pojęcie", "module": 8, "pl": "Szeroka dziedzina zajmująca się tworzeniem inteligentnych systemów komputerowych, które potrafią wykonywać zadania podobne do ludzkich, np. rozumieć język, rozpoznawać obrazy czy podejmować decyzje. Uczenie maszynowe (ML) jest podzbiorem AI, uczenie głębokie (DL) – podzbiorem ML, a generatywna AI – rodzajem uczenia głębokiego.", "en": "A broad field focused on building intelligent computer systems capable of performing humanlike tasks, such as understanding language, recognizing images or making decisions. Machine learning (ML) is a subset of AI, deep learning (DL) is a subset of ML, and generative AI is a type of deep learning."},
{"name": "AWS AI/ML stack (three tiers) / Stos AI/ML AWS (trzy warstwy)", "category": "AI/ML i generatywna AI", "kind": "pojęcie", "module": 8, "pl": "Trzy warstwy rozwiązań AI/ML w AWS, od gotowych do w pełni własnych. 1) Usługi AI (AI services) – gotowe, wytrenowane modele do konkretnych zadań (np. Rekognition, Polly, Comprehend), nie wymagają wiedzy z ML. 2) Usługi ML (ML services) – Amazon SageMaker AI do budowania, trenowania i wdrażania własnych modeli na zarządzanej infrastrukturze. 3) Frameworki i infrastruktura ML – pełna kontrola: frameworki (PyTorch, TensorFlow, Apache MXNet) i infrastruktura AWS, np. instancje EC2 zoptymalizowane pod ML, Amazon EMR, Amazon ECS.", "en": "Three tiers of AWS AI/ML solutions, from ready-made to fully custom. 1) AI services – pre-built, already trained models for specific functions (e.g. Rekognition, Polly, Comprehend), requiring no ML expertise. 2) ML services – Amazon SageMaker AI to build, train and deploy your own models on fully managed infrastructure. 3) ML frameworks and infrastructure – full control: frameworks (PyTorch, TensorFlow, Apache MXNet) plus AWS infrastructure such as ML-optimized EC2 instances, Amazon EMR and Amazon ECS."},
{"name": "Deep learning (DL) / Uczenie głębokie", "category": "AI/ML i generatywna AI", "kind": "pojęcie", "module": 8, "pl": "Podzbiór uczenia maszynowego, w którym modele trenuje się za pomocą warstw sztucznych neuronów naśladujących ludzki mózg (sieci neuronowe). Każda warstwa podsumowuje informacje i przekazuje je do następnej, aż powstanie końcowy model. Pozwala rozwiązywać bardziej złożone problemy, np. widzenie komputerowe i przetwarzanie języka naturalnego.", "en": "A subset of machine learning in which models are trained using layers of artificial neurons that mimic the human brain (neural networks). Each layer summarizes information and feeds it to the next until a final model is produced. It tackles more complex problems such as computer vision and natural language processing."},
{"name": "Fine-tuning / Dostrajanie modelu", "category": "AI/ML i generatywna AI", "kind": "pojęcie", "module": 8, "pl": "Dalsze trenowanie wstępnie wytrenowanego modelu (np. FM) na Twoich własnych danych z danej dziedziny, aby lepiej wykonywał konkretne zadania. Jest tańsze i szybsze niż trenowanie modelu od zera. W AWS umożliwiają je m.in. Amazon Bedrock i SageMaker JumpStart.", "en": "Further training of a pre-trained model (such as an FM) on your own domain-specific data so that it performs specific tasks better. It is cheaper and faster than training a model from scratch. On AWS it is supported by Amazon Bedrock and SageMaker JumpStart, among others."},
{"name": "Foundation model (FM) / Model podstawowy", "category": "AI/ML i generatywna AI", "kind": "pojęcie", "module": 8, "pl": "Bardzo duży model ML wstępnie wytrenowany na ogromnych zbiorach danych, będący podstawą generatywnej AI. Jeden FM można dostosować (np. przez dostrajanie) do wielu różnych zadań. Popularnym rodzajem FM są duże modele językowe (LLM). FM są dostępne w AWS m.in. przez Amazon Bedrock i SageMaker JumpStart.", "en": "An extremely large ML model pre-trained on vast collections of data, forming the basis of generative AI. A single FM can be adapted (for example through fine-tuning) to many different tasks. Large language models (LLMs) are a popular type of FM. On AWS, FMs are available through Amazon Bedrock and SageMaker JumpStart, among others."},
{"name": "Generative AI / Generatywna AI", "category": "AI/ML i generatywna AI", "kind": "pojęcie", "module": 8, "pl": "Rodzaj uczenia głębokiego oparty na bardzo dużych modelach ML, tzw. modelach podstawowych (FM). Potrafi tworzyć nowe treści: tekst, obrazy, wideo, muzykę czy kod. W odróżnieniu od tradycyjnych modeli ML, trenowanych do jednego zadania, modele generatywne można dostosować do wielu zadań. Rozwiązania AWS: Amazon Bedrock, Amazon SageMaker JumpStart, Amazon Q.", "en": "A type of deep learning powered by extremely large ML models called foundation models (FMs). It can create new content: text, images, video, music or code. Unlike traditional ML models trained for a single task, generative models can be adapted to many tasks. AWS solutions: Amazon Bedrock, Amazon SageMaker JumpStart, Amazon Q."},
{"name": "Large language model (LLM) / Duży model językowy", "category": "AI/ML i generatywna AI", "kind": "pojęcie", "module": 8, "pl": "Popularny rodzaj modelu podstawowego (FM), wytrenowany do rozumienia i generowania ludzkiego języka. Odpowiada na pytania, streszcza, tłumaczy, pisze teksty i kod. Przykład z kursu: Claude dostępny w Amazon Bedrock.", "en": "A popular type of foundation model (FM) trained to understand and generate human language. It answers questions, summarizes, translates, and writes text and code. Example from the course: Claude, available in Amazon Bedrock."},
{"name": "Machine learning (ML) / Uczenie maszynowe", "category": "AI/ML i generatywna AI", "kind": "pojęcie", "module": 8, "pl": "Rodzaj AI, w którym maszyny uczą się wykonywać złożone zadania bez jawnie zaprogramowanych instrukcji. Trenowanie wyszukuje wzorce w dużych ilościach danych historycznych i tworzy model ML, który potem stosuje się do nowych danych, aby przewidywać lub podejmować decyzje. Typowe zastosowania biznesowe: przewidywanie trendów (np. cen), podejmowanie decyzji (np. kierowanie rozmów do właściwego działu), wykrywanie anomalii (np. oszustw bankowych), rekomendacje.", "en": "A type of AI that trains machines to perform complex tasks without explicit instructions. Training finds patterns hidden in large amounts of historical data and produces an ML model, which is then applied to new data to make predictions or decisions. Common business use cases: predicting trends (e.g. prices), making decisions (e.g. routing callers to the right department), detecting anomalies (e.g. bank fraud), recommendations."},
{"name": "ML framework / Framework uczenia maszynowego", "category": "AI/ML i generatywna AI", "kind": "pojęcie", "module": 8, "pl": "Biblioteka programistyczna lub narzędzie, które daje doświadczonym specjalistom ML gotowe, zoptymalizowane komponenty do budowania modeli. AWS obsługuje m.in. PyTorch, TensorFlow i Apache MXNet. To najniższa, najbardziej elastyczna warstwa stosu AI/ML AWS – dla organizacji, które chcą pełnej kontroli nad trenowaniem modeli.", "en": "A software library or tool that provides experienced ML practitioners with pre-built, optimized components for building models. AWS supports PyTorch, TensorFlow and Apache MXNet, among others. It is the lowest, most flexible tier of the AWS AI/ML stack – for organizations that want complete control over model training."},
{"name": "Natural language processing (NLP) / Przetwarzanie języka naturalnego", "category": "AI/ML i generatywna AI", "kind": "pojęcie", "module": 8, "pl": "Dziedzina AI, która pozwala komputerom rozumieć, interpretować i przetwarzać ludzki język w tekście lub mowie. Wykorzystują ją m.in. Amazon Comprehend (analiza tekstu), Amazon Kendra (inteligentne wyszukiwanie) i Amazon Lex (rozumienie języka naturalnego w chatbotach).", "en": "A field of AI that lets computers understand, interpret and process human language in text or speech. It is used, among others, by Amazon Comprehend (text analysis), Amazon Kendra (intelligent search) and Amazon Lex (natural language understanding in chatbots)."},
{"name": "Amazon Athena", "category": "Analiza danych", "kind": "usługa", "module": 8, "pl": "Bezserwerowa, w pełni zarządzana usługa do interaktywnych zapytań SQL bezpośrednio na danych, głównie w Amazon S3, a także w źródłach relacyjnych, nierelacyjnych, on-premises i w innych chmurach. Nie trzeba ładować danych ani zarządzać serwerami; płacisz tylko za wykonane zapytania. Na egzaminie: „zapytania SQL do danych w S3 bez infrastruktury” → Athena.", "en": "A serverless, fully managed service for interactive SQL queries directly on data, mainly in Amazon S3, as well as relational, nonrelational, on-premises and multi-cloud sources. There is nothing to load and no servers to manage; you pay only for the queries you run. On the exam: “SQL queries on data in S3 without infrastructure” → Athena."},
{"name": "Amazon Data Firehose", "category": "Analiza danych", "kind": "usługa", "module": 8, "pl": "W pełni zarządzana usługa pozyskiwania danych prawie w czasie rzeczywistym, która w ciągu sekund dostarcza dane strumieniowe do jezior danych (np. Amazon S3), hurtowni (np. Amazon Redshift) i usług analitycznych. Sama przydziela i skaluje zasoby. Wcześniej nazywała się Amazon Kinesis Data Firehose.", "en": "A fully managed service for near real-time data ingestion that delivers streaming data within seconds to data lakes (e.g. Amazon S3), data warehouses (e.g. Amazon Redshift) and analytics services. It automatically provisions and scales. It was formerly called Amazon Kinesis Data Firehose."},
{"name": "Amazon EMR", "category": "Analiza danych", "kind": "usługa", "module": 8, "pl": "Zarządzana platforma do przetwarzania dużych zbiorów danych (big data) z popularnymi frameworkami open source, takimi jak Apache Spark, Apache Hadoop i Apache Hive. Automatycznie zajmuje się provisioningiem infrastruktury, zarządzaniem klastrami i skalowaniem. Dla organizacji, które mają już doświadczenie z big data; może też służyć jako infrastruktura dla własnych rozwiązań ML.", "en": "A managed platform for large-scale (big data) processing with popular open-source frameworks such as Apache Spark, Apache Hadoop and Apache Hive. It automatically handles infrastructure provisioning, cluster management and scaling. Aimed at organizations with existing big data expertise; it can also serve as infrastructure for custom ML solutions."},
{"name": "Amazon Kinesis Data Streams", "category": "Analiza danych", "kind": "usługa", "module": 8, "pl": "Bezserwerowa usługa do pozyskiwania w czasie rzeczywistym terabajtów danych strumieniowych z aplikacji, strumieni i czujników, np. kliknięć, logów, danych IoT. W trybie na żądanie (on-demand) automatycznie przydziela i skaluje zasoby. Na egzaminie: „strumienie danych w czasie rzeczywistym” → Kinesis Data Streams.", "en": "A serverless service for real-time ingestion of terabytes of streaming data from applications, streams and sensors, such as clickstreams, logs or IoT data. In on-demand mode it automatically provisions and scales capacity. On the exam: “real-time data streams” → Kinesis Data Streams."},
{"name": "Amazon OpenSearch Service", "category": "Analiza danych", "kind": "usługa", "module": 8, "pl": "Zarządzana usługa wyszukiwania i analityki, która pozwala znajdować treści przez dokładne dopasowanie słów kluczowych lub zapytania w języku naturalnym. Ujednolicone pulpity wizualizują dane w czasie rzeczywistym przy analizie i monitorowaniu logów, śladów (traces) i metryk aplikacji. Zastosowania: wyszukiwarki w aplikacjach, analiza logów.", "en": "A managed search and analytics service that lets you find content through precise keyword matching or natural language queries. Unified dashboards provide real-time visualization as you analyze and monitor logs, traces and metrics for applications. Use cases: application search, log analytics."},
{"name": "Amazon QuickSight", "category": "Analiza danych", "kind": "usługa", "module": 8, "pl": "Usługa analityki biznesowej (BI), w której zarówno osoby techniczne, jak i nietechniczne szybko tworzą interaktywne pulpity i raporty z wielu źródeł danych bez zarządzania infrastrukturą. Funkcja Amazon Q in QuickSight pozwala zadawać pytania językiem naturalnym i w kilka sekund tworzyć oraz udostępniać wnioski. Na egzaminie: „pulpity, wizualizacje, BI” → QuickSight.", "en": "A business intelligence (BI) service where both technical and non-technical users quickly create interactive dashboards and reports from many data sources without managing infrastructure. Amazon Q in QuickSight lets users ask questions in natural language and build and share insights in seconds. On the exam: “dashboards, visualizations, BI” → QuickSight."},
{"name": "Amazon Redshift", "category": "Analiza danych", "kind": "usługa", "module": 8, "pl": "W pełni zarządzana hurtownia danych, która przechowuje petabajty danych ustrukturyzowanych i półustrukturyzowanych. Dzięki kolumnowemu przechowywaniu danych i masowo równoległemu przetwarzaniu (MPP) szybko wykonuje złożone zapytania SQL na dużych zbiorach – idealna do częstych, wydajnych obciążeń analitycznych i BI. Model płatności za faktyczne użycie.", "en": "A fully managed data warehouse that stores petabytes of structured and semistructured data. Its columnar storage and massively parallel processing (MPP) architecture run complex SQL queries on large datasets quickly – ideal for frequent, high-performance analytics and BI workloads. Pay-as-you-go pricing."},
{"name": "AWS Glue", "category": "Analiza danych", "kind": "usługa", "module": 8, "pl": "W pełni zarządzana, bezserwerowa usługa ETL, która upraszcza i przyspiesza przygotowanie danych do analizy oraz obniża jego koszt. Zadania ETL w Glue czyszczą i przekształcają dane, korzystając z metadanych z AWS Glue Data Catalog. Na egzaminie: „bezserwerowe ETL” → AWS Glue.", "en": "A fully managed, serverless ETL service that makes data preparation simpler, faster and more cost-effective. Glue ETL jobs clean and transform data, using metadata from the AWS Glue Data Catalog. On the exam: “serverless ETL” → AWS Glue."},
{"name": "AWS Glue Data Catalog", "category": "Analiza danych", "kind": "usługa", "module": 8, "pl": "Scentralizowane, skalowalne i zarządzane repozytorium metadanych, czyli inwentarz danych organizacji. Ułatwia odnajdowanie danych i dostarcza metadane do różnych magazynów danych i usług analitycznych (np. Athena, EMR, Redshift). Zadania ETL w AWS Glue korzystają z niego, aby poznać strukturę źródeł danych.", "en": "A centralized, scalable and managed metadata repository – an inventory of your organization’s data. It improves data discovery and delivers metadata to various data stores and analytics services (e.g. Athena, EMR, Redshift). AWS Glue ETL jobs use it to learn about the structure of data sources."},
{"name": "Data analytics / Analiza danych", "category": "Analiza danych", "kind": "pojęcie", "module": 8, "pl": "Przekształcanie surowych danych historycznych w wartościowe wnioski i trendy. Przykłady: firmy pożyczkowe wyjaśniające decyzje kredytowe, badania kliniczne z testowaniem hipotez, przejrzyste modele ryzyka dla regulatorów. Analiza danych opisuje przeszłość, a ML służy głównie do przewidywania przyszłości – oba potrzebują czystych, dobrze przygotowanych danych.", "en": "Transforming raw historical data into valuable insights and trends. Examples: lenders explaining lending decisions, clinical trial analysis through hypothesis testing, transparent risk models for regulators. Data analytics explains the past, while ML mainly predicts the future – both depend on clean, well-prepared data."},
{"name": "Data lake / Jezioro danych", "category": "Analiza danych", "kind": "pojęcie", "module": 8, "pl": "Elastyczne, centralne repozytorium, które przechowuje ogromne ilości surowych danych w dowolnym formacie – ustrukturyzowanych i nieustrukturyzowanych. Dane trafiają tam w oryginalnej postaci i są przetwarzane dopiero przy analizie. Popularnym wyborem na jezioro danych jest Amazon S3. Przeciwieństwo: bardziej uporządkowana hurtownia danych.", "en": "A flexible, central repository that stores vast amounts of raw data in any format – structured and unstructured. Data lands in its original form and is processed only when analyzed. Amazon S3 is a popular choice for data lakes. Contrast: the more structured data warehouse."},
{"name": "Data pipeline / Potok danych", "category": "Analiza danych", "kind": "pojęcie", "module": 8, "pl": "Zautomatyzowana „linia montażowa”, która sprawia, że proces ETL jest wydajny i powtarzalny. Typowe etapy potoku w AWS: pozyskiwanie danych (Kinesis Data Streams, Data Firehose), przechowywanie (Amazon S3, Amazon Redshift), katalogowanie (AWS Glue Data Catalog), przetwarzanie (AWS Glue, Amazon EMR) oraz analiza i wizualizacja (Athena, Redshift, QuickSight, OpenSearch Service).", "en": "An automated assembly line that makes the ETL process efficient and repeatable. Typical AWS pipeline stages: ingestion (Kinesis Data Streams, Data Firehose), storage (Amazon S3, Amazon Redshift), cataloging (AWS Glue Data Catalog), processing (AWS Glue, Amazon EMR), and analysis and visualization (Athena, Redshift, QuickSight, OpenSearch Service)."},
{"name": "Data warehouse / Hurtownia danych", "category": "Analiza danych", "kind": "pojęcie", "module": 8, "pl": "Uporządkowane repozytorium danych ustrukturyzowanych lub półustrukturyzowanych, zoptymalizowane pod analitykę biznesową (BI) i złożone zapytania SQL na dużych zbiorach danych. W AWS: Amazon Redshift. Na egzaminie: hurtownia danych = analityka (OLAP), baza relacyjna typu RDS = transakcje (OLTP).", "en": "A structured repository for structured or semistructured data, optimized for business intelligence (BI) and complex SQL queries over large datasets. On AWS: Amazon Redshift. On the exam: data warehouse = analytics (OLAP), relational database like RDS = transactions (OLTP)."},
{"name": "ETL (Extract, Transform, Load)", "category": "Analiza danych", "kind": "pojęcie", "module": 8, "pl": "Proces przygotowania danych do analizy i AI/ML w trzech krokach: wyodrębnij (extract) dane z różnych źródeł, przekształć (transform) je do spójnego, użytecznego formatu i załaduj (load) do systemu docelowego, np. hurtowni danych lub platformy analitycznej. W AWS typową usługą ETL jest AWS Glue.", "en": "A process that prepares data for analytics and AI/ML in three steps: extract data from various sources, transform it into a consistent, usable format, and load it into a destination system such as a data warehouse or analytics platform. On AWS, the typical ETL service is AWS Glue."},
{"name": "Real-time vs batch ingestion / Pozyskiwanie danych w czasie rzeczywistym i wsadowe", "category": "Analiza danych", "kind": "pojęcie", "module": 8, "pl": "Pozyskiwanie danych (ingestion) to przenoszenie danych z systemów źródłowych do wybranego miejsca przechowywania. Pozyskiwania w czasie rzeczywistym używa się, gdy dane są potrzebne natychmiast (np. Kinesis Data Streams), a wsadowego – gdy pewne opóźnienie jest akceptowalne. Data Firehose dostarcza dane prawie w czasie rzeczywistym (w ciągu sekund).", "en": "Data ingestion means moving data from source systems into your chosen storage. Use real-time ingestion when data is needed immediately (e.g. Kinesis Data Streams) and batch ingestion when some latency is tolerable. Data Firehose delivers data in near real time (within seconds)."},
{"name": "Amazon Detective", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "usługa", "module": 9, "pl": "Usługa do badania pierwotnej przyczyny (root cause) zagrożenia, które zostało już wykryte (np. przez GuardDuty). Pokazuje interaktywne wizualizacje interakcji zasobów i użytkowników na konfigurowalnej osi czasu w jednym widoku konsoli, z zaleceniami naprawy. Kolejność: GuardDuty wykrywa → Detective bada.", "en": "A service to investigate the root cause of a threat after it has been detected (e.g., by GuardDuty). It analyzes threats with interactive visualizations of resource and user interactions over a configurable timeline in a unified console view, with recommended remediation steps. Order of use: GuardDuty detects → Detective investigates."},
{"name": "Amazon GuardDuty", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "usługa", "module": 9, "pl": "Inteligentne wykrywanie zagrożeń w Twojej infrastrukturze i zasobach. Stale analizuje strumienie metadanych konta i aktywności sieciowej, korzystając ze znanych złośliwych adresów IP, wykrywania anomalii i uczenia maszynowego. Wyniki (findings) zawierają zalecane kroki naprawcze, a naprawę można zautomatyzować funkcjami AWS Lambda.", "en": "Intelligent threat detection across your infrastructure and resources. It continuously monitors streams of account metadata and network activity, using known malicious IP addresses, anomaly detection, and machine learning to identify threats. Findings include recommended remediation steps, and you can configure AWS Lambda functions to remediate automatically."},
{"name": "Amazon Inspector", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "usługa", "module": 9, "pl": "Usługa uruchamiająca automatyczne oceny bezpieczeństwa instancji Amazon EC2, kontenerów i funkcji AWS Lambda. Szuka podatności (np. podatnych wersji oprogramowania) i odstępstw od dobrych praktyk, np. otwartego dostępu do EC2; wyniki są uporządkowane według ważności i zawierają zalecenia naprawy. Wyróżnik: skanowanie podatności (vulnerabilities), a nie wykrywanie zagrożeń w aktywności konta – to robi GuardDuty.", "en": "A service that runs automated security assessments for Amazon EC2 instances, containers, and AWS Lambda functions. It checks for software vulnerabilities and deviations from security best practices, such as open access to EC2 instances; findings are prioritized by severity and include remediation recommendations. Differentiator: vulnerability scanning, not threat detection in account activity – that is GuardDuty."},
{"name": "Amazon Macie", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "usługa", "module": 9, "pl": "Usługa, która za pomocą uczenia maszynowego i automatyzacji wykrywa dane wrażliwe (np. dane osobowe, PII) przechowywane w Amazon S3 i pomaga je chronić. Pozwala monitorować bezpieczeństwo danych w spoczynku i oceniać stan zabezpieczeń, co ułatwia spełnienie wymagań zgodności. Słowa kluczowe na egzaminie: „dane wrażliwe / PII w S3” → Macie.", "en": "A service that uses machine learning and automation to discover sensitive data (such as personally identifiable information, PII) stored in Amazon S3 and help protect it. It lets you monitor sensitive data at rest and assess your security posture, which helps meet compliance requirements. Exam keyword: “sensitive data / PII in S3” → Macie."},
{"name": "Authentication / Uwierzytelnianie", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 9, "pl": "Proces potwierdzania tożsamości użytkownika lub podmiotu na podstawie poświadczeń, np. nazwy użytkownika i hasła (często z MFA). Odpowiada na pytanie „kim jesteś?”. Przykład: pracownik loguje się do portalu pracowniczego. Następuje przed autoryzacją, która decyduje o uprawnieniach.", "en": "The process of verifying the identity of a user or entity through credentials, such as a username and password combination (often with MFA). It answers the question “who are you?”. Example: an employee logs in to an employee portal. It happens before authorization, which determines what the user is allowed to do."},
{"name": "Authorization / Autoryzacja", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 9, "pl": "Nadawanie użytkownikom praw dostępu i uprawnień, które określają, jakie działania mogą wykonywać w systemie lub aplikacji. Odpowiada na pytanie „co możesz zrobić?”. Przykład: pracownik widzi w portalu tylko własną kartotekę. W AWS autoryzację definiuje się głównie politykami IAM.", "en": "Granting users access rights and permissions that determine which actions they can perform in a system or application. It answers the question “what are you allowed to do?”. Example: an employee can only access their own records in the employee portal. In AWS, authorization is mainly defined with IAM policies."},
{"name": "AWS account root user / Użytkownik root konta AWS", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 9, "pl": "Tożsamość tworzona automatycznie razem z kontem AWS – właściciel konta, który może zrobić na nim wszystko. Dobre praktyki: silne hasło, włączone MFA i nieużywanie roota do codziennej pracy – do tego tworzy się użytkowników IAM lub role. Uprawnień roota nie da się ograniczyć politykami IAM, dlatego wymaga szczególnej ochrony.", "en": "The identity created automatically with every AWS account – the account owner, with permission to do anything in the account. Best practices: use a strong password, turn on MFA, and don't use the root user for daily tasks – create IAM users or roles instead. Its permissions cannot be restricted with IAM policies, so it needs special protection."},
{"name": "AWS Artifact", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "usługa", "module": 10, "pl": "Bezpłatny portal samoobsługowy z dostępem na żądanie do raportów bezpieczeństwa i zgodności AWS oraz wybranych umów online. Składa się z dwóch części: AWS Artifact Reports i AWS Artifact Agreements. Słowa kluczowe na egzaminie: „pobierz raport zgodności AWS (np. SOC, ISO) dla audytora” → AWS Artifact.", "en": "A no-cost, self-service portal that provides on-demand access to AWS security and compliance reports and select online agreements. It has two parts: AWS Artifact Reports and AWS Artifact Agreements. Exam keyword: “download an AWS compliance report (e.g., SOC, ISO) for an auditor” → AWS Artifact."},
{"name": "AWS Artifact Agreements", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 10, "pl": "Część AWS Artifact, w której przeglądasz, akceptujesz i zarządzasz umowami z AWS – dla pojedynczego konta albo dla wszystkich kont w AWS Organizations. Oferuje umowy dla klientów podlegających określonym regulacjom, np. umowę BAA (Business Associate Addendum) dla HIPAA. Przykład: firma musi podpisać z AWS umowę dotyczącą przetwarzania określonych danych.", "en": "The part of AWS Artifact where you review, accept, and manage agreements with AWS for an individual account or for all your accounts in AWS Organizations. It offers agreements for customers subject to specific regulations, such as the Business Associate Addendum (BAA) for HIPAA. Example: a company needs to sign an agreement with AWS about using certain types of information."},
{"name": "AWS Artifact Reports", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 10, "pl": "Część AWS Artifact z raportami zgodności od niezależnych audytorów, którzy sprawdzili, że AWS spełnia globalne, regionalne i branżowe standardy bezpieczeństwa oraz regulacje. Raporty są na bieżąco aktualizowane; możesz przekazać je swoim audytorom lub regulatorom jako dowód mechanizmów kontroli bezpieczeństwa AWS.", "en": "The part of AWS Artifact that provides compliance reports from third-party auditors who have tested and verified that AWS complies with global, regional, and industry-specific security standards and regulations. Reports stay up to date, and you can provide them to your auditors or regulators as evidence of AWS security controls."},
{"name": "AWS Audit Manager", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "usługa", "module": 10, "pl": "W pełni zarządzana usługa, która stale audytuje korzystanie z AWS, aby uprościć ocenę ryzyka i zgodności. Automatycznie zbiera dowody (evidence), porządkuje dane audytowe, ma gotowe frameworki dla standardów branżowych i pomaga tworzyć raporty gotowe do audytu. Różnica: AWS Config ocenia konfiguracje zasobów, a Audit Manager zbiera dowody zgodności dla audytorów.", "en": "A fully managed service that continually audits your AWS usage to simplify risk and compliance assessment. It automates evidence collection, manages audit data, includes prebuilt frameworks for industry standards, and helps build audit-ready reports. Difference: AWS Config evaluates resource configurations, while Audit Manager collects compliance evidence for auditors."},
{"name": "AWS Certificate Manager (ACM)", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "usługa", "module": 9, "pl": "Usługa centralizująca tworzenie certyfikatów SSL/TLS i zarządzanie nimi; certyfikaty zapewniają szyfrowanie danych w tranzycie. Chroni różne usługi AWS (np. load balancery, CloudFront) oraz połączone zasoby on-premises. Słowa kluczowe na egzaminie: „certyfikaty SSL/TLS, HTTPS” → ACM.", "en": "A service that centralizes creating and managing SSL/TLS certificates, which provide data encryption in transit. It can protect various AWS services (e.g., load balancers, CloudFront) and your connected on-premises resources. Exam keyword: “SSL/TLS certificates, HTTPS” → ACM."},
{"name": "AWS Compliance Programs / Programy zgodności AWS", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 10, "pl": "Portal AWS Compliance z materiałami o zgodności: listą programów zgodności (standardów i certyfikacji, które spełnia AWS), historiami klientów z branż regulowanych, whitepaperami (np. odpowiedzi AWS na kluczowe pytania o zgodność, przegląd ryzyka i zgodności, lista kontrolna audytu bezpieczeństwa) oraz przewodnikami i szkoleniami. Same raporty audytorów pobiera się w AWS Artifact.", "en": "The AWS Compliance portal with compliance resources: the list of compliance programs (standards and certifications AWS meets), customer stories from regulated industries, whitepapers (e.g., AWS answers to key compliance questions, an overview of AWS risk and compliance, an auditing security checklist), and guides and training. The auditor reports themselves are downloaded from AWS Artifact."},
{"name": "AWS IAM Identity Center", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "usługa", "module": 9, "pl": "Usługa centralizująca zarządzanie tożsamością i dostępem w wielu kontach AWS i aplikacjach. Może połączyć się z istniejącym źródłem tożsamości (np. katalogiem firmowym) i dać pracownikom jednokrotne logowanie (single sign-on, SSO) do wszystkich podłączonych kont i aplikacji. To przykład federacyjnego zarządzania tożsamością (następca AWS Single Sign-On).", "en": "A service that centralizes identity and access management across AWS accounts and applications. It can connect to an existing identity source and give your workforce single sign-on (SSO) access to all connected AWS accounts and applications. This is called federated identity management (it is the successor to AWS Single Sign-On)."},
{"name": "AWS Identity and Access Management (IAM)", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "usługa", "module": 9, "pl": "Usługa do bezpiecznego zarządzania tożsamościami i dostępem do usług i zasobów AWS. Udostępnia użytkowników, grupy i role, a potrzebne uprawnienia definiuje się w politykach IAM. Domyślnie wszystkie działania są zabronione – każde uprawnienie trzeba jawnie przyznać, zgodnie z zasadą najmniejszych uprawnień. IAM jest usługą globalną, bez dodatkowych opłat.", "en": "A service to securely manage identities and access to AWS services and resources. It provides users, groups, and roles, and IAM policies define the access these identities need. By default, all actions are denied – you must explicitly grant permissions, following the principle of least privilege. IAM is a global service offered at no additional charge."},
{"name": "AWS Key Management Service (AWS KMS)", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "usługa", "module": 9, "pl": "Usługa do tworzenia kluczy kryptograficznych i zarządzania nimi; klucze służą do szyfrowania i odszyfrowywania danych. Pozwala kontrolować użycie kluczy w wielu usługach AWS i w aplikacjach, np. określić, którzy użytkownicy i role IAM mogą nimi zarządzać. Klucze nigdy nie opuszczają AWS KMS i można je tymczasowo wyłączyć.", "en": "A service to create and manage cryptographic keys, which are used to encrypt and decrypt your data. You can control the use of keys across a wide range of AWS services and in your applications, for example by specifying which IAM users and roles can manage keys. Your keys never leave AWS KMS, and you can temporarily disable them."},
{"name": "AWS Secrets Manager", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "usługa", "module": 9, "pl": "Usługa do bezpiecznego przechowywania, rotowania i pobierania sekretów – poświadczeń baz danych, kluczy API i innych poufnych danych – przez cały ich cykl życia. Aplikacje pobierają sekret w razie potrzeby, zamiast trzymać go w kodzie. Wyróżnik na egzaminie: automatyczna rotacja poświadczeń (np. do Amazon RDS).", "en": "A service to securely store, manage, rotate, and retrieve database credentials, API keys, and other secrets throughout their lifecycle. Applications retrieve secrets when needed instead of hardcoding them. Key exam differentiator: automatic rotation of credentials (e.g., for Amazon RDS)."},
{"name": "AWS security controls / Mechanizmy kontroli bezpieczeństwa AWS", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 9, "pl": "Mechanizmy i usługi AWS chroniące zasoby w chmurze, pogrupowane w kursie według celu: zapobieganie incydentom przez właściwe zarządzanie uprawnieniami i dostępem (np. IAM), ochrona sieci, aplikacji i danych (np. Shield, WAF, KMS) oraz wykrywanie incydentów i reagowanie na nie (np. GuardDuty, Inspector, Detective, Security Hub). Ten podział pomaga dopasować usługę do pytania egzaminacyjnego.", "en": "The AWS security mechanisms and services that protect cloud resources, grouped by purpose: preventing security incidents through proper permission and access management (e.g., IAM), protecting networks, applications, and data (e.g., Shield, WAF, KMS), and detecting and responding to security incidents as they occur (e.g., GuardDuty, Inspector, Detective, Security Hub)."},
{"name": "AWS Security Hub", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "usługa", "module": 9, "pl": "Usługa zbierająca w jednym miejscu i formacie wyniki z wielu usług bezpieczeństwa AWS i rozwiązań partnerów. Daje jeden przegląd stanu bezpieczeństwa i zgodności, grupuje wyniki w praktyczne zestawy zwane insights i skraca czas rozwiązania (TTR) dzięki automatycznej naprawie. Słowa kluczowe na egzaminie: „jeden widok / agregacja wyników bezpieczeństwa” → Security Hub.", "en": "A service that brings findings from multiple AWS security services and partner products together into a single place and format. It gives one comprehensive view of your security and compliance state, organizes findings into actionable groupings called insights, and accelerates time to resolution (TTR) with automated remediation. Exam keyword: “single view / aggregate security findings” → Security Hub."},
{"name": "AWS Shield Advanced", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "usługa", "module": 9, "pl": "Płatna usługa ochrony przed DDoS, dająca szczegółową diagnostykę ataków oraz wykrywanie i łagodzenie zaawansowanych ataków. Integruje się z Amazon CloudFront, Amazon Route 53 i ELB, a razem z AWS WAF pozwala pisać własne reguły przeciw złożonym atakom. Obejmuje też całodobowy dostęp do zespołu AWS Shield Response Team.", "en": "A paid DDoS protection service that provides detailed attack diagnostics and the ability to detect and mitigate sophisticated DDoS attacks. It integrates with Amazon CloudFront, Amazon Route 53, and ELB, and together with AWS WAF you can write custom rules against complex attacks. It also includes 24/7 access to the AWS Shield Response Team."},
{"name": "AWS Shield Standard", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "usługa", "module": 9, "pl": "Bezpłatna ochrona przed najczęstszymi atakami DDoS, włączona automatycznie dla wszystkich klientów AWS. W czasie rzeczywistym wykrywa i łagodzi złośliwy ruch; jest wbudowana m.in. w Elastic Load Balancing, Amazon CloudFront i Amazon Route 53. Nie wymaga konfiguracji – w odróżnieniu od płatnego Shield Advanced.", "en": "Free protection against the most common, frequently occurring types of DDoS attacks, automatically enabled for all AWS customers. It detects and mitigates malicious traffic in real time and is built into services such as Elastic Load Balancing, Amazon CloudFront, and Amazon Route 53. It requires no setup – unlike the paid Shield Advanced."},
{"name": "AWS WAF", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "usługa", "module": 9, "pl": "Zapora aplikacji internetowych (web application firewall), która monitoruje żądania HTTP(S) trafiające do Twoich aplikacji. Sprawdza je według reguł z listy kontroli dostępu (web ACL) – np. odrzuca żądania z zablokowanych adresów IP – a uprawniony ruch przepuszcza. Działa w warstwie aplikacji (np. z CloudFront, Application Load Balancer, API Gateway) i uzupełnia AWS Shield; nie myl jej z grupami zabezpieczeń ani z sieciowymi ACL.", "en": "A web application firewall that monitors HTTP(S) requests coming into your web applications. It checks requests against rules in a web access control list (web ACL) – for example, it denies requests from blocked IP addresses – and allows legitimate traffic. It works at the application layer (e.g., with CloudFront, Application Load Balancer, API Gateway) and complements AWS Shield; don't confuse it with security groups or network ACLs."},
{"name": "Compliance / Zgodność z przepisami", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 10, "pl": "Przestrzeganie przez zasoby i dane w chmurze odpowiednich przepisów, standardów branżowych i wewnętrznych zasad bezpieczeństwa i ochrony danych. AWS pomaga przez dziedziczenie mechanizmów kontroli, których używa we własnej infrastrukturze, zewnętrzną walidację tysięcy globalnych wymagań, automatyzację i raporty zgodności na żądanie (AWS Artifact). Zgodność to proces ciągły, a nie jednorazowe działanie.", "en": "Your cloud resources and data adhering to relevant regulations, industry standards, and internal policies for security and data protection. AWS helps by letting you inherit the security controls AWS uses on its own infrastructure, third-party validation for thousands of global requirements, streamlined and automated compliance, and on-demand compliance reports (AWS Artifact). Compliance is ongoing, not a one-time task."},
{"name": "Distributed denial of service (DDoS) / Rozproszony atak odmowy usługi", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 9, "pl": "Atak odmowy usługi (DoS) zalewa aplikację nadmiernym ruchem, aż przestaje ona odpowiadać prawdziwym klientom. W ataku rozproszonym (DDoS) ruch wysyła jednocześnie wiele zainfekowanych komputerów (botów „zombie”), np. w ataku UDP flood. AWS chroni przed nim swoją infrastrukturą (skala Regionów, grupy zabezpieczeń, ELB) oraz usługami AWS Shield i AWS WAF.", "en": "A denial of service (DoS) attack floods a web application with excessive traffic until it can no longer respond to legitimate requests. In a distributed attack (DDoS), many infected computers (zombie bots) send the traffic at once, e.g., a UDP flood. AWS protects against it through its infrastructure (Region scale, security groups, ELB) and services such as AWS Shield and AWS WAF."},
{"name": "Encryption at rest / Szyfrowanie w spoczynku", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 9, "pl": "Szyfrowanie danych, które się nie przemieszczają, tylko są przechowywane – np. w bazie danych, na woluminie lub w buckecie. W AWS jest często wbudowane: nowe buckety S3 domyślnie szyfrują przesłane obiekty, woluminy i migawki EBS można szyfrować, a DynamoDB szyfruje wszystkie dane tabel kluczami z AWS KMS.", "en": "Encryption of data that is idle and not moving, such as data stored in a database, volume, or bucket. In AWS it is often built in: new S3 buckets encrypt uploaded objects by default, EBS volumes and snapshots can be encrypted, and DynamoDB encrypts all table data with keys stored in AWS KMS."},
{"name": "Encryption in transit / Szyfrowanie w tranzycie", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 9, "pl": "Szyfrowanie danych przesyłanych między lokalizacjami, np. z bazy danych do aplikacji albo z przeglądarki do serwera. Zaszyfrowane połączenia sieciowe nawiązuje się za pomocą certyfikatów SSL/TLS (np. HTTPS). W AWS certyfikatami zarządza AWS Certificate Manager (ACM).", "en": "Encryption of data moving between locations, such as from a database to an application or from a browser to a server. Encrypted network connections are established with SSL/TLS certificates (e.g., HTTPS). In AWS, these certificates are managed with AWS Certificate Manager (ACM)."},
{"name": "Federated identity management / Federacyjne zarządzanie tożsamością", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 9, "pl": "System, w którym użytkownicy korzystają z wielu aplikacji, usług lub domen przy użyciu jednego zestawu poświadczeń, zwykle od zewnętrznego dostawcy tożsamości. Dzięki temu nie trzeba zakładać osobnych kont w każdym systemie. W AWS zapewnia to m.in. IAM Identity Center z jednokrotnym logowaniem (SSO).", "en": "A system that allows users to access multiple applications, services, or domains using a single set of credentials, usually from an external identity provider. Users don't need separate accounts in every system. In AWS, IAM Identity Center provides this with single sign-on (SSO)."},
{"name": "HIPAA and PCI DSS / Regulacje HIPAA i PCI DSS", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 10, "pl": "Przykłady regulacji, z którymi muszą być zgodne niektóre obciążenia robocze: HIPAA (Health Insurance Portability and Accountability Act) dotyczy danych medycznych w USA, a PCI DSS (Payment Card Industry Data Security Standard) – danych kart płatniczych. W AWS pomagają tu m.in. logi CloudTrail jako dowód zgodności, umowy w AWS Artifact Agreements (np. BAA dla HIPAA) i raporty w AWS Artifact Reports.", "en": "Examples of regulations some workloads must comply with: HIPAA (Health Insurance Portability and Accountability Act) covers healthcare data in the US, and PCI DSS (Payment Card Industry Data Security Standard) covers payment card data. In AWS, CloudTrail logs can serve as compliance evidence, AWS Artifact Agreements offers agreements such as the BAA for HIPAA, and AWS Artifact Reports provides audit reports."},
{"name": "IAM Access Analyzer", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "usługa", "module": 10, "pl": "Funkcja IAM pomagająca ustawiać, weryfikować i zawężać uprawnienia. Analizuje dostęp zewnętrzny (kto spoza konta ma dostęp do Twoich zasobów) i sprawdza, czy polityki są zgodne z firmowymi standardami bezpieczeństwa. Pomaga osiągnąć zasadę najmniejszych uprawnień i usuwać nieużywany lub zbyt szeroki dostęp – sięga głębiej w szczegółowe uprawnienia IAM niż Trusted Advisor.", "en": "An IAM capability that helps you set, verify, and refine permissions. It analyzes external access (who outside your account can access your resources) and validates that your policies match your corporate security standards. It helps you reach least privilege and remove unused or broad access – going deeper into fine-grained IAM permissions than Trusted Advisor."},
{"name": "IAM group / Grupa IAM", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 9, "pl": "Zbiór użytkowników IAM. Uprawnienia przypisane do grupy dziedziczą wszyscy jej członkowie, co upraszcza zarządzanie dostępem wielu osób (np. grupa „employees” z jednakowym podstawowym dostępem). Grupą nie można się zalogować i nie może ona zawierać innych grup.", "en": "A collection of IAM users. When you assign permissions to a group, all users in the group inherit them, which simplifies managing access for many people (e.g., an “employees” group with the same standard access). A group is not an identity you can sign in with, and groups cannot be nested."},
{"name": "IAM policy / Polityka IAM", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 9, "pl": "Dokument JSON, który zezwala (Allow) lub zabrania (Deny) dostępu do usług i zasobów AWS i może określać poziom dostępu, np. do wszystkich bucketów S3 albo tylko jednego. Instrukcja polityki zawiera m.in. efekt (Effect), akcję (Action, np. s3:ListBucket) i zasób (Resource). Polityki dołącza się do użytkowników, grup lub ról.", "en": "A JSON document that allows or denies permission to access AWS services and resources and can define the level of access, for example to all S3 buckets or only a specific one. A policy statement includes an Effect, an Action (e.g., s3:ListBucket), and a Resource. Policies are attached to users, groups, or roles."},
{"name": "IAM role / Rola IAM", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 9, "pl": "Tożsamość, którą można przyjąć (assume), aby uzyskać tymczasowe uprawnienia i poświadczenia. Po przyjęciu roli porzuca się dotychczasowe uprawnienia i dostaje uprawnienia nowej roli. Role przyjmują użytkownicy, aplikacje i usługi AWS (np. instancja EC2 z dostępem do S3) – bez długoterminowych kluczy dostępu.", "en": "An identity that you can assume to gain temporary permissions and credentials. When someone assumes a role, they give up their previous permissions and take on the permissions of the new role. Roles can be assumed by users, applications, and AWS services (e.g., an EC2 instance accessing S3) without long-term access keys."},
{"name": "IAM user / Użytkownik IAM", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 9, "pl": "Tożsamość reprezentująca osobę lub aplikację, która korzysta z usług i zasobów AWS; składa się z nazwy i poświadczeń. Nowy użytkownik IAM domyślnie nie ma żadnych uprawnień. AWS zaleca osobnego użytkownika dla każdej osoby, aby każda miała własne, unikalne poświadczenia.", "en": "An identity that represents a person or application that interacts with AWS services and resources; it consists of a name and credentials. A new IAM user has no permissions by default. AWS recommends creating an individual IAM user for each person who needs access, so each has their own unique set of security credentials."},
{"name": "Multi-factor authentication (MFA) / Uwierzytelnianie wieloskładnikowe", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 9, "pl": "Metoda logowania wymagająca co najmniej dwóch sposobów weryfikacji, np. hasła i losowego jednorazowego kodu (tokenu) z urządzenia. Znacznie utrudnia przejęcie konta nawet po wycieku hasła. AWS zaleca włączenie MFA dla użytkownika root i użytkowników IAM; można też wymagać MFA przy przyjmowaniu roli IAM.", "en": "A sign-in method that requires at least two verification methods, for example a password and a randomized token from a device. It makes account takeover much harder even if a password leaks. AWS recommends turning on MFA for the root user and IAM users; you can also require MFA to assume an IAM role."},
{"name": "Principle of least privilege / Zasada najmniejszych uprawnień", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 9, "pl": "Zasada, zgodnie z którą ludzie i systemy dostają dostęp tylko do tego, czego naprawdę potrzebują – i nic więcej. Uprawnienia przyznaje się wyłącznie według potrzeby (need-to-have). W AWS wspierają ją polityki IAM oraz m.in. IAM Identity Center, Secrets Manager, Systems Manager i IAM Access Analyzer.", "en": "The principle that people and systems should only be given access to what they need and nothing else. Permissions are granted on a need-to-have basis. In AWS it is supported by IAM policies and by services such as IAM Identity Center, Secrets Manager, Systems Manager, and IAM Access Analyzer."},
{"name": "SSL/TLS certificate / Certyfikat SSL/TLS", "category": "Bezpieczeństwo, tożsamość i zgodność", "kind": "pojęcie", "module": 9, "pl": "Cyfrowy certyfikat służący do nawiązywania zaszyfrowanych połączeń sieciowych między systemami (np. HTTPS) i potwierdzania tożsamości serwera. To podstawa szyfrowania w tranzycie. W AWS tworzy się je i zarządza nimi w AWS Certificate Manager.", "en": "A digital certificate used to establish encrypted network connections from one system to another (e.g., HTTPS) and to confirm the server's identity. It is the basis of encryption in transit. In AWS, you create and manage them with AWS Certificate Manager."},
{"name": "Account Factory", "category": "Monitorowanie i nadzór", "kind": "pojęcie", "module": 10, "pl": "Konfigurowalny szablon kont w AWS Control Tower, który standaryzuje tworzenie (provisioning) nowych kont AWS. Dzięki niemu każde nowe konto od początku ma zatwierdzone ustawienia sieci, bezpieczeństwa i zgodności.", "en": "A configurable account template in AWS Control Tower that standardizes the provisioning of new AWS accounts. Every new account starts with approved network, security, and compliance settings."},
{"name": "Amazon CloudWatch", "category": "Monitorowanie i nadzór", "kind": "usługa", "module": 10, "pl": "Usługa monitorująca w czasie rzeczywistym zasoby AWS i działające w AWS aplikacje (a także serwery on-premises). Daje wgląd w wykorzystanie zasobów, wydajność aplikacji i stan operacyjny; główne funkcje to metryki, alarmy, pulpity (dashboards) i logi (CloudWatch Logs). Zapamiętaj: CloudWatch = wydajność i metryki, CloudTrail = kto wywołał jakie API, Config = historia i zgodność konfiguracji.", "en": "A service that monitors your AWS resources and the applications you run on AWS (and on-premises servers) in real time. It gives system-wide visibility into resource utilization, application performance, and operational health; key features are metrics, alarms, dashboards, and CloudWatch Logs. Remember: CloudWatch = performance and metrics, CloudTrail = who made which API call, Config = configuration history and compliance."},
{"name": "Amazon CloudWatch Logs", "category": "Monitorowanie i nadzór", "kind": "usługa", "module": 10, "pl": "Funkcja CloudWatch centralizująca logi ze wszystkich używanych systemów, aplikacji i usług AWS. Logi można przeszukiwać i analizować, aby znaleźć przyczyny problemów z wydajnością lub błędów aplikacji. Nie myl ich z logami CloudTrail, które rejestrują wywołania API, czyli aktywność użytkowników.", "en": "A CloudWatch feature that centralizes the logs from all of the systems, applications, and AWS services that you use. You can search and analyze the logs to find the causes of performance issues or application errors. Don't confuse them with CloudTrail logs, which record API calls (user activity)."},
{"name": "Auditing / Audyt", "category": "Monitorowanie i nadzór", "kind": "pojęcie", "module": 10, "pl": "Okresowy przegląd i ocena skuteczności mechanizmów kontroli bezpieczeństwa oraz sprawdzenie, czy wymagania, zasady i procedury są przestrzegane. W kursie to trzeci etap: zabezpieczanie → monitorowanie → audyt → zgodność. W AWS audyt wspierają CloudTrail („kto, co, gdzie i kiedy”), AWS Config i AWS Audit Manager.", "en": "Periodically reviewing and assessing the effectiveness of security controls and checking that requirements, policies, and procedures are followed. In the course it is the third step: secure → monitor → audit → compliance. In AWS, auditing is supported by CloudTrail (“who did what, where, and when”), AWS Config, and AWS Audit Manager."},
{"name": "AWS CloudTrail", "category": "Monitorowanie i nadzór", "kind": "usługa", "module": 10, "pl": "Usługa audytowa rejestrująca aktywność użytkowników i wywołania API w AWS (każda akcja w AWS to wywołanie API – z konsoli, CLI czy SDK). Zapisuje, kto wykonał akcję, co zrobił, kiedy, skąd (adres IP) i jaki był wynik – odpowiada na pytanie „kto, co, gdzie i kiedy?”. Logi trafiają do bucketu S3, mają walidację integralności i mogą służyć jako dowód zgodności (np. PCI DSS, HIPAA).", "en": "An auditing service that records user activity and API calls in AWS (every action in AWS is an API call – from the console, CLI, or SDK). It records who made the request, what they did, when, from where (IP address), and the response – answering “who did what, where, and when?”. Logs are delivered to an S3 bucket, support log file integrity validation, and can serve as compliance evidence (e.g., PCI DSS, HIPAA)."},
{"name": "AWS Config", "category": "Monitorowanie i nadzór", "kind": "usługa", "module": 10, "pl": "Usługa, która stale rejestruje konfiguracje zasobów AWS i ich zmiany oraz ocenia je względem pożądanego stanu zdefiniowanego w regułach (Config rules). Powiadamia o zasobach niezgodnych, może uruchomić automatyczną naprawę i tworzy raporty zgodności. Słowa kluczowe na egzaminie: „historia konfiguracji / czy zasoby są zgodne z firmowymi regułami” → AWS Config.", "en": "A service that continuously records the configurations of your AWS resources and their changes and evaluates them against a desired state defined in rules (Config rules). It notifies you about noncompliant resources, can trigger automated remediation, and produces compliance reports. Exam keyword: “configuration history / do resources comply with company rules” → AWS Config."},
{"name": "AWS Control Tower", "category": "Monitorowanie i nadzór", "kind": "usługa", "module": 10, "pl": "Usługa do szybkiego skonfigurowania bezpiecznego, zgodnego, wielokontowego środowiska AWS według dobrych praktyk i do nadzoru nad nim. Wymusza reguły bezpieczeństwa, operacji i zgodności na dużą skalę we wszystkich kontach i organizacjach. Główne elementy: strefa lądowania (landing zone), mechanizmy kontrolne (controls/guardrails), Account Factory i pulpit. Działa na bazie AWS Organizations.", "en": "A service to quickly set up and govern a secure, compliant, multi-account AWS environment based on best practices. It enforces and manages governance rules for security, operations, and compliance at scale across all your organizations and accounts. Key elements: landing zone, controls (guardrails), Account Factory, and the dashboard. It builds on AWS Organizations."},
{"name": "AWS Health", "category": "Monitorowanie i nadzór", "kind": "usługa", "module": 10, "pl": "Główne źródło informacji o zdarzeniach i zmianach wpływających na stan (health) Twoich zasobów AWS. Powiadamia o zdarzeniach w usługach (np. awariach), planowanych zmianach (np. konserwacji) i powiadomieniach dotyczących konta. Dane są dostępne w AWS Health Dashboard i programowo przez AWS Health API.", "en": "The go-to data source for events and changes affecting the health of your AWS Cloud resources. It notifies you about service events (e.g., outages), planned changes (e.g., maintenance), and account notifications. The data is available in the AWS Health Dashboard and programmatically through the AWS Health API."},
{"name": "AWS Health Dashboard", "category": "Monitorowanie i nadzór", "kind": "usługa", "module": 10, "pl": "Widok w konsoli z informacjami o stanie usług AWS i zdarzeniami dotyczącymi Twojego konta (dawniej Personal Health Dashboard). Daje aktualne i praktyczne wskazówki naprawcze, pomaga planować zdarzenia cyklu życia i rozwiązywać incydenty. Dostęp programowy przez AWS Health API wymaga planu AWS Premium Support (Business lub wyższego).", "en": "A console view with AWS service health information and events specific to your account (formerly the Personal Health Dashboard). It provides timely, actionable remediation guidance, helps you plan for lifecycle events, and helps troubleshoot incidents. Programmatic access through the AWS Health API requires an AWS Premium Support plan (Business or higher)."},
{"name": "AWS License Manager", "category": "Monitorowanie i nadzór", "kind": "usługa", "module": 10, "pl": "Usługa do zarządzania licencjami oprogramowania (np. Microsoft) i optymalizacji ich kosztów. Daje wgląd w użycie licencji, śledzi je i ogranicza ryzyko naruszenia warunków licencji przez egzekwowanie limitów i blokowanie nowych uruchomień. Wspiera model BYOL, np. na Amazon EC2 Dedicated Hosts.", "en": "A service that helps you manage your software licenses (e.g., Microsoft) and fine-tune your licensing costs. It provides visibility into license usage, tracks licenses, and reduces the risk of noncompliance by enforcing license usage limits and blocking new launches. It supports the BYOL model, for example on Amazon EC2 Dedicated Hosts."},
{"name": "AWS Organizations", "category": "Monitorowanie i nadzór", "kind": "usługa", "module": 10, "pl": "Usługa do centralnego zarządzania wieloma kontami AWS i nadzoru nad nimi. Konta układa się w hierarchię (root → jednostki organizacyjne, OU), ograniczenia nakłada się politykami kontroli usług (SCP), a nowe konta można tworzyć programowo. Daje też rozliczenia skonsolidowane (consolidated billing) – jeden rachunek za wszystkie konta i wspólne rabaty ilościowe.", "en": "A service to centrally manage and govern multiple AWS accounts. Accounts are organized in a hierarchy (root → organizational units, OUs), restrictions are applied with service control policies (SCPs), and new accounts can be created programmatically. It also provides consolidated billing – one bill for all accounts with shared volume discounts."},
{"name": "AWS Service Catalog", "category": "Monitorowanie i nadzór", "kind": "usługa", "module": 10, "pl": "Usługa do tworzenia, udostępniania i porządkowania wyselekcjonowanego katalogu zatwierdzonych zasobów i usług AWS. Pracownicy samodzielnie (self-service) wdrażają tylko to, co jest w katalogu, np. bazowe zasoby sieciowe i narzędzia bezpieczeństwa dla nowych kont. Oszczędza czas i zapewnia spójny nadzór w wielu kontach.", "en": "A service to create, share, and organize a curated catalog of approved AWS resources and services. Employees can self-service deploy only what is in the catalog, such as baseline networking resources and security tools for new accounts. It saves time and keeps governance consistent across multiple accounts."},
{"name": "AWS Trusted Advisor", "category": "Monitorowanie i nadzór", "kind": "usługa", "module": 10, "pl": "Usługa, która stale ocenia Twoje środowisko AWS względem najlepszych praktyk AWS i zaleca konkretne działania. Kontrole dotyczą optymalizacji kosztów, wydajności, bezpieczeństwa, odporności na awarie i limitów usług – np. brak MFA dla roota, słabo wykorzystane instancje EC2, woluminy EBS bez migawek, publicznie otwarte grupy zabezpieczeń. Wszystkie plany wsparcia mają podstawowy zestaw kontroli; pełny zestaw daje plan Business i wyższe.", "en": "A service that continuously evaluates your AWS environment against AWS best practices and recommends actions. Its checks cover cost optimization, performance, security, fault tolerance, and service limits – e.g., no MFA on the root user, underutilized EC2 instances, EBS volumes without snapshots, security groups open to the public. All Support plans include a core set of checks; Business Support and higher plans unlock the full set."},
{"name": "CloudTrail event history / Historia zdarzeń CloudTrail", "category": "Monitorowanie i nadzór", "kind": "pojęcie", "module": 10, "pl": "Dostępny domyślnie, przeszukiwalny i niezmienny zapis zdarzeń zarządczych (management events) z ostatnich 90 dni w danym Regionie AWS – można go przeglądać, filtrować i pobierać. Przeglądanie historii zdarzeń jest bezpłatne. Do dłuższego przechowywania tworzy się trail, który zapisuje pliki logów w Amazon S3.", "en": "A viewable, searchable, downloadable, and immutable record of the past 90 days of management events in an AWS Region, available by default. There are no CloudTrail charges for viewing event history. For longer retention, you create a trail that delivers log files to Amazon S3."},
{"name": "CloudTrail Insights", "category": "Monitorowanie i nadzór", "kind": "pojęcie", "module": 10, "pl": "Funkcja CloudTrail analizująca normalne wzorce liczby wywołań API i odsetka błędów API. Gdy wartości odbiegają od normy, generuje zdarzenia Insights, co pomaga wykryć nietypowe zachowanie i podejrzaną aktywność. Włącza się ją w trailach lub magazynach danych zdarzeń (event data stores).", "en": "A CloudTrail feature that analyzes your normal patterns of API call volume and API error rates. When these deviate from normal patterns, it generates Insights events, which helps you detect anomalous behavior and unusual activity. You enable it in your trails or event data stores."},
{"name": "CloudWatch alarms / Alarmy CloudWatch", "category": "Monitorowanie i nadzór", "kind": "pojęcie", "module": 10, "pl": "Progi definiowane na metrykach CloudWatch; po ich przekroczeniu alarm wysyła powiadomienie (np. przez Amazon SNS) albo automatycznie zmienia zasoby. Przykład: gdy wykorzystanie EC2 jest zbyt wysokie przez dłuższy czas, alarm uruchamia skalowanie i dodaje instancje. Słowa kluczowe na egzaminie: „powiadom lub zareaguj, gdy metryka przekroczy próg” → alarm CloudWatch.", "en": "Thresholds defined on CloudWatch metrics; when a threshold is crossed, the alarm sends a notification (e.g., via Amazon SNS) or automatically makes changes to resources. Example: when EC2 utilization stays too high for an extended period, the alarm triggers scaling to add instances. Exam keyword: “notify or act when a metric crosses a threshold” → CloudWatch alarm."},
{"name": "CloudWatch dashboards / Pulpity CloudWatch", "category": "Monitorowanie i nadzór", "kind": "pojęcie", "module": 10, "pl": "Konfigurowalne strony główne w konsoli CloudWatch, na których monitorujesz swoje zasoby w jednym widoku. Łączą wykresy metryk i inne widżety z wielu usług i Regionów. Dają szybki przegląd stanu całego środowiska.", "en": "Customizable home pages in the CloudWatch console that you can use to monitor your resources in a single view. They combine metric graphs and other widgets from multiple services and Regions. They give a quick overview of the state of your whole environment."},
{"name": "CloudWatch metrics / Metryki CloudWatch", "category": "Monitorowanie i nadzór", "kind": "pojęcie", "module": 10, "pl": "Dane liczbowe zbierane w czasie, np. wykorzystanie procesora instancji EC2. CloudWatch zbiera metryki ze wszystkich zasobów, aplikacji i usług AWS oraz z serwerów on-premises; można też publikować metryki niestandardowe. Na metrykach opierają się alarmy i pulpity.", "en": "Numeric data collected over time, such as the CPU utilization of an EC2 instance. CloudWatch collects metrics from all your AWS resources, applications, and services and from on-premises servers; you can also publish custom metrics. Alarms and dashboards are built on metrics."},
{"name": "Controls (guardrails) / Mechanizmy kontrolne", "category": "Monitorowanie i nadzór", "kind": "pojęcie", "module": 10, "pl": "Ogólne reguły w AWS Control Tower zapewniające nadzór nad całym środowiskiem AWS – jak bariery ochronne na autostradzie. Automatycznie wymuszają zasady i dobre praktyki oraz pomagają wykrywać zasoby niezgodne z regułami, np. bez wymaganego tagu działu.", "en": "High-level rules in AWS Control Tower that provide governance for your overall AWS environment – like safety barriers on a highway. They automatically enforce policies and best practices and help detect noncompliant resources, for example resources missing a required department tag."},
{"name": "Governance / Nadzór", "category": "Monitorowanie i nadzór", "kind": "pojęcie", "module": 10, "pl": "Zasady i mechanizmy, dzięki którym organizacja kontroluje konta, usługi, zasoby i licencje w chmurze oraz egzekwuje wymagania firmy dotyczące bezpieczeństwa, operacji i zgodności. Staje się kluczowy, gdy firma rośnie i ma wiele kont AWS. Usługi nadzoru omawiane w kursie: AWS Organizations, AWS Control Tower, AWS Service Catalog i AWS License Manager.", "en": "The rules and mechanisms an organization uses to control its cloud accounts, services, resources, and licenses and to enforce company requirements for security, operations, and compliance. It becomes critical as a company grows to many AWS accounts. Governance services covered in the course: AWS Organizations, AWS Control Tower, AWS Service Catalog, and AWS License Manager."},
{"name": "Landing zone / Strefa lądowania", "category": "Monitorowanie i nadzór", "kind": "pojęcie", "module": 10, "pl": "Dobrze zaprojektowane (well-architected) środowisko wielokontowe oparte na dobrych praktykach bezpieczeństwa i zgodności, tworzone przez AWS Control Tower. To nadrzędny „kontener” obejmujący wszystkie OU, konta, użytkowników i zasoby, które mają podlegać regułom zgodności.", "en": "A well-architected multi-account environment based on security and compliance best practices, set up by AWS Control Tower. It is the enterprise-wide container that holds all of the OUs, accounts, users, and resources you want to regulate for compliance."},
{"name": "Management account / Konto zarządzające", "category": "Monitorowanie i nadzór", "kind": "pojęcie", "module": 10, "pl": "Centralne konto AWS, które tworzy organizację w AWS Organizations i nią zarządza. Odpowiada za ogólną kontrolę i nadzór, a przy rozliczeniach skonsolidowanych płaci za wszystkie konta członkowskie. Pozostałe konta w organizacji to konta członkowskie.", "en": "The central AWS account that creates and manages the organization in AWS Organizations. It is responsible for overall control and governance and, with consolidated billing, pays for all member accounts. All other accounts in the organization are member accounts."},
{"name": "Member account / Konto członkowskie", "category": "Monitorowanie i nadzór", "kind": "pojęcie", "module": 10, "pl": "Każde konto w organizacji AWS Organizations poza kontem zarządzającym. Może być w OU albo bezpośrednio pod rootem, jeśli ma unikalne wymagania. Nawet poza OU korzysta z zalet organizacji, takich jak rozliczenia skonsolidowane.", "en": "Any account in an AWS Organizations organization other than the management account. It can be placed in an OU or directly under the root if it has unique requirements. Even outside an OU, it still benefits from features such as consolidated billing."},
{"name": "Monitoring / Monitorowanie", "category": "Monitorowanie i nadzór", "kind": "pojęcie", "module": 10, "pl": "Ciągły proces zbierania, wizualizowania i śledzenia stanu (health) i wydajności infrastruktury, usług i aplikacji AWS. Pozwala obserwować aktywność systemów, ruch sieciowy i zdarzenia bezpieczeństwa, aby wcześnie wykrywać problemy i anomalie. Realizuje się je narzędziami do monitorowania w czasie rzeczywistym, zbierania i analizy logów oraz pulpitami – w AWS głównie w Amazon CloudWatch.", "en": "The continuous process of collecting, visualizing, and tracking the health and performance of your AWS infrastructure, services, and applications. It lets you observe system activity, network traffic, and security events to detect potential issues and anomalies early. It uses real-time monitoring tools, log collection and analysis, and dashboards – in AWS mainly Amazon CloudWatch."},
{"name": "Organizational unit (OU) / Jednostka organizacyjna", "category": "Monitorowanie i nadzór", "kind": "pojęcie", "module": 10, "pl": "Logiczna grupa kont w AWS Organizations; może zawierać konta członkowskie i zagnieżdżone OU. Konta grupuje się w OU według potrzeb biznesowych, bezpieczeństwa i regulacyjnych poszczególnych działów. Polityki (SCP) nałożone na OU obejmują wszystkie konta w niej.", "en": "A logical grouping of accounts in AWS Organizations; it can contain member accounts or nested OUs. You group accounts into OUs based on the business, security, and regulatory needs of each department. Policies (SCPs) applied to an OU affect all accounts in it."},
{"name": "Service control policy (SCP) / Polityka kontroli usług", "category": "Monitorowanie i nadzór", "kind": "pojęcie", "module": 10, "pl": "Polityka w AWS Organizations, która ogranicza usługi, zasoby i pojedyncze akcje API dostępne dla użytkowników i ról w kontach. Stosuje się ją do OU lub do pojedynczych kont członkowskich. SCP nie nadaje uprawnień – wyznacza maksymalną granicę tego, na co mogą pozwolić polityki IAM.", "en": "A policy in AWS Organizations that places restrictions on the AWS services, resources, and individual API actions that users and roles in each account can access. SCPs can be applied to OUs or individual member accounts. An SCP does not grant permissions – it sets the maximum boundary of what IAM policies can allow."},
{"name": "Service limits (Service Quotas) / Limity usług", "category": "Monitorowanie i nadzór", "kind": "pojęcie", "module": 10, "pl": "Maksymalne liczby zasobów lub operacji dozwolone na koncie AWS (np. liczba instancji w Regionie). Wiele z nich to limity miękkie, które można podnieść – wniosek składa się w konsoli Service Quotas. Trusted Advisor ostrzega, gdy zbliżasz się do limitu.", "en": "The maximum number of resources or operations allowed in an AWS account (e.g., the number of instances in a Region). Many are soft limits that can be raised by requesting a change in the Service Quotas console. Trusted Advisor warns you when you are approaching a limit."},
{"name": "Trusted Advisor check categories / Kategorie kontroli Trusted Advisor", "category": "Monitorowanie i nadzór", "kind": "pojęcie", "module": 10, "pl": "Kurs wymienia pięć kategorii: optymalizacja kosztów (cost optimization), wydajność (performance), bezpieczeństwo (security), odporność na awarie (fault tolerance) i limity usług (service limits); obecnie konsola pokazuje też doskonałość operacyjną (operational excellence). Statusy wyników: czerwony – zalecane działanie, pomarańczowy – zalecane zbadanie, zielony – brak problemów. Można ustawić powiadomienia e-mail dla kontaktów rozliczeniowych, operacyjnych i bezpieczeństwa.", "en": "The course lists five categories: cost optimization, performance, security, fault tolerance, and service limits; the console now also includes operational excellence. Result statuses: red – action recommended, orange – investigation recommended, green – no problems detected. You can set up email alerts for billing, operations, and security contacts."},
{"name": "AWS Billing and Cost Management dashboard (Billing Dashboard)", "category": "Ceny, rozliczenia i wsparcie", "kind": "usługa", "module": 11, "pl": "Centralny pulpit rozliczeń w konsoli AWS: pokazuje bieżące opłaty, użycie, prognozę wydatków na dany miesiąc i usługi generujące największe koszty. Pozwala też zarządzać metodami płatności, przeglądać i pobierać faktury, ustawiać budżety oraz obsługiwać rozliczenia skonsolidowane. To dobry punkt startowy do zrozumienia wydatków.", "en": "The central billing dashboard in the AWS console: it shows current charges, usage, the forecasted spend for the month, and a breakdown of the most-consumed services by cost. It also lets you manage payment methods, view and download invoices, set budgets, and handle consolidated billing. It is a good starting point for understanding your expenses."},
{"name": "AWS Budgets", "category": "Ceny, rozliczenia i wsparcie", "kind": "usługa", "module": 11, "pl": "Usługa do tworzenia własnych budżetów kosztów i użycia (także dla konkretnych usług, kategorii kosztów lub tagów) oraz do śledzenia wykorzystania i pokrycia Savings Plans i Reserved Instances. Wysyła alerty, gdy rzeczywiste lub prognozowane koszty zbliżają się do ustalonego progu lub go przekraczają, i może uruchamiać automatyczne akcje. Na egzaminie: „powiadom mnie, gdy wydatki przekroczą próg” → AWS Budgets.", "en": "A service for creating custom cost and usage budgets (including for specific services, cost categories, or tags) and for tracking Savings Plans and Reserved Instance utilization or coverage. It sends alerts when actual or forecasted costs approach or exceed your thresholds and can trigger automated actions. Exam tip: notify me when spending exceeds a threshold → AWS Budgets."},
{"name": "AWS Compute Optimizer", "category": "Ceny, rozliczenia i wsparcie", "kind": "usługa", "module": 11, "pl": "Usługa, która analizuje wykorzystanie zasobów obliczeniowych (np. instancji EC2 i funkcji Lambda) i rekomenduje optymalne typy i rozmiary, wskazując zasoby przewymiarowane lub niedowymiarowane. Służy do rightsizingu – obniża koszty i poprawia wydajność.", "en": "A service that analyzes the utilization of your compute resources (such as EC2 instances and Lambda functions) and recommends optimal types and sizes, identifying overprovisioned or underprovisioned resources. It is used for rightsizing to lower costs and improve performance."},
{"name": "AWS Cost and Usage Report (AWS CUR)", "category": "Ceny, rozliczenia i wsparcie", "kind": "usługa", "module": 13, "pl": "Najbardziej szczegółowy raport kosztów i użycia AWS – dane na poziomie pojedynczych zasobów i godzin, dostarczane do bucketu Amazon S3 do dalszej analizy (np. w Amazon Athena lub Amazon QuickSight). W kursie pojawia się jako usprawnienie dla filaru zrównoważonego rozwoju: pomaga śledzić zużycie zasobów i eliminować marnotrawstwo.", "en": "The most detailed AWS cost and usage report – data at the level of individual resources and hours, delivered to an Amazon S3 bucket for further analysis (for example with Amazon Athena or Amazon QuickSight). In the course it appears as an enhancement for the Sustainability pillar, helping you track resource usage and eliminate waste."},
{"name": "AWS Cost Explorer", "category": "Ceny, rozliczenia i wsparcie", "kind": "usługa", "module": 11, "pl": "Narzędzie do wizualizacji i analizy kosztów oraz użycia AWS w czasie za pomocą interaktywnych wykresów i raportów. Pozwala rozbić koszty według usługi, połączonego konta lub tagów (alokacja kosztów na podstawie tagów), prognozować przyszłe koszty i daje rekomendacje dotyczące Reserved Instances. Służy do analizy historycznych trendów wydatków i szukania oszczędności.", "en": "A tool for visualizing and analyzing AWS costs and usage over time with interactive graphs and reports. You can break down costs by service, linked account, or tags (tag-based cost allocation), forecast future costs, and get Reserved Instance recommendations. It is used to analyze historical spending trends and identify cost-saving opportunities."},
{"name": "AWS Documentation / Dokumentacja AWS (self-support)", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Obszerne zasoby do samodzielnego szukania odpowiedzi i rozwiązywania problemów: przewodniki użytkownika usług, dokumentacja API i SDK, samouczki, blogi i whitepapery z najlepszymi praktykami. Są dostępne bezpłatnie dla wszystkich klientów.", "en": "Extensive self-support resources for researching questions and troubleshooting issues: user guides for AWS services, API and SDK references, tutorials, blog posts, and whitepapers with best practices. They are available to all customers at no cost."},
{"name": "AWS Free Tier / Bezpłatna warstwa AWS", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Program, który pozwala nowym klientom bezpłatnie korzystać z wybranych usług AWS w określonych limitach, np. żeby wypróbować usługę albo uruchomić demo. Część ofert jest zawsze bezpłatna (Always Free), a część jest ograniczona czasowo lub ma formę okresu próbnego. Limity i warunki dla każdej usługi znajdziesz na jej stronie cennika.", "en": "A program that lets new customers use selected AWS services at no charge within defined limits, for example to try a service or run a demo. Some offers are always free, while others are time-limited or available as trials. The limits and terms for each service are listed on its pricing page."},
{"name": "AWS Knowledge Center", "category": "Ceny, rozliczenia i wsparcie", "kind": "usługa", "module": 11, "pl": "Część AWS re:Post z artykułami i filmami odpowiadającymi na najczęściej zadawane pytania i prośby klientów AWS. Dobre źródło samodzielnej pomocy (self-support).", "en": "Part of AWS re:Post containing articles and videos that cover the most frequently asked questions and requests from AWS customers. A good self-support resource."},
{"name": "AWS Marketplace", "category": "Ceny, rozliczenia i wsparcie", "kind": "usługa", "module": 11, "pl": "Cyfrowy katalog tysięcy ofert oprogramowania od niezależnych dostawców (ISV), w którym znajdziesz, przetestujesz, kupisz, wdrożysz i będziesz zarządzać oprogramowaniem firm trzecich działającym w AWS. Obejmuje m.in. SaaS, modele i algorytmy ML/AI oraz narzędzia do danych i analityki, z opcjami darmowymi i płatnymi (np. pay-as-you-go, subskrypcje roczne) i opiniami klientów. Upraszcza zakupy, a opłaty trafiają na rachunek AWS.", "en": "A curated digital catalog with thousands of software listings from independent software vendors (ISVs) where you can find, test, buy, deploy, and manage third-party software that runs on AWS. It includes SaaS, ML/AI models and algorithms, and data and analytics tools, with free and paid options (such as pay-as-you-go and annual subscriptions) and customer reviews. It simplifies procurement and consolidates charges into your AWS bill."},
{"name": "AWS Partner Network (APN)", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Globalna społeczność firm technologicznych i konsultingowych, które budują rozwiązania i usługi dla klientów z użyciem technologii AWS. Możesz zlecić partnerowi AWS rozwiązanie dopasowane do Twoich potrzeb albo dołączyć do programu jako partner i korzystać z finansowania, wydarzeń dla partnerów oraz szkoleń i certyfikacji.", "en": "A global community of technology and consulting businesses that use AWS technologies, programs, expertise, and tools to build solutions and services for customers. You can work with an AWS Partner on a solution tailored to your needs, or join as a partner and benefit from funding, partner events, and partner training and certification."},
{"name": "AWS Pricing Calculator", "category": "Ceny, rozliczenia i wsparcie", "kind": "usługa", "module": 11, "pl": "Bezpłatne narzędzie webowe do szacowania kosztów przed wdrożeniem. Wprowadzasz konkretną konfigurację (typy instancji, opcje pamięci masowej, wolumen transferu danych) i dostajesz szczegółowy rozkład kosztów; możesz też porównać koszty różnych usług i konfiguracji. Na egzaminie: szacowanie kosztów planowanej architektury → Pricing Calculator, analiza już poniesionych kosztów → Cost Explorer.", "en": "A free, web-based planning tool for estimating costs before deployment. You enter specific configurations (instance types, storage options, data transfer volumes) and receive a detailed cost breakdown; you can also compare the costs of different services and configurations. Exam tip: estimating a planned architecture → Pricing Calculator; analyzing costs already incurred → Cost Explorer."},
{"name": "AWS Professional Services", "category": "Ceny, rozliczenia i wsparcie", "kind": "usługa", "module": 11, "pl": "Zespół konsultingowy AWS oferujący głębsze wsparcie w formie projektów: złożone migracje, audyty bezpieczeństwa, strojenie wydajności i przyspieszanie wdrażania chmury. W odróżnieniu od planów wsparcia, które pomagają w bieżących problemach, to doradztwo projektowe. Ten zespół stworzył m.in. AWS Cloud Adoption Framework.", "en": "AWS's consulting team offering deeper, project-based support: complex migrations, security audits, performance tuning, and accelerating cloud adoption. Unlike support plans, which help with ongoing issues, it provides project-based consulting. This team created the AWS Cloud Adoption Framework."},
{"name": "AWS re:Post", "category": "Ceny, rozliczenia i wsparcie", "kind": "usługa", "module": 11, "pl": "Społecznościowa platforma pytań i odpowiedzi, na której możesz szukać pomocy, dzielić się wiedzą i znajdować rozwiązania dotyczące usług AWS. Jest dostępna dla wszystkich (także w planie Basic) i zawiera AWS Knowledge Center.", "en": "A community-driven question-and-answer platform where you can seek help, share knowledge, and find solutions related to AWS services and technologies. It is available to everyone (including Basic Support) and houses the AWS Knowledge Center."},
{"name": "AWS solutions architects (SAs) / Architekci rozwiązań AWS", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Eksperci AWS dostępni dla klientów planów Business i Enterprise. Doradzają w zakresie architektury, przekazują rekomendacje najlepszych praktyk i pomagają projektować skalowalne i bezpieczne aplikacje.", "en": "AWS experts available to Business and Enterprise Support customers. They provide architectural guidance and best-practice recommendations and help design scalable, secure applications."},
{"name": "AWS Support plans / Plany wsparcia AWS", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "AWS oferuje plany wsparcia od Basic (bezpłatny, dla wszystkich) przez Developer, Business i Enterprise On-Ramp po Enterprise. Każdy kolejny plan zawiera wszystko z poprzedniego i dodaje szybsze czasy odpowiedzi, pełniejszy zestaw kontroli AWS Trusted Advisor i bardziej spersonalizowaną pomoc (np. TAM). Według kursu plany Developer, Business i Enterprise On-Ramp zostaną wycofane 1 stycznia 2027 r., a AWS wprowadza nowe opcje wsparcia.", "en": "AWS offers support plans ranging from Basic (free, for everyone) through Developer, Business, and Enterprise On-Ramp to Enterprise. Each plan includes everything in the previous one and adds faster response times, a fuller set of AWS Trusted Advisor checks, and more personalized help (for example a TAM). According to the course, the Developer, Business, and Enterprise On-Ramp plans will be discontinued on January 1, 2027, as AWS introduces new support options."},
{"name": "AWS Trust and Safety Center", "category": "Ceny, rozliczenia i wsparcie", "kind": "usługa", "module": 11, "pl": "Miejsce, w którym zgłaszasz podejrzenie nadużyć z wykorzystaniem zasobów lub treści w AWS (abuse), np. spamu, phishingu czy ataków. Zawiera też wskazówki dotyczące ochrony aplikacji i dobrych praktyk w komunikacji cyfrowej. Na egzaminie: „zgłoś nadużycie” → AWS Trust and Safety Center.", "en": "Where you report suspected abusive activity or content involving AWS resources, such as spam, phishing, or attacks. It also offers guidance on protecting applications and best practices for digital messaging. Exam tip: report abuse → AWS Trust and Safety Center."},
{"name": "Basic Support", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Plan wsparcia dołączony bezpłatnie do każdego konta AWS. Daje całodobowy dostęp do obsługi klienta, dokumentacji, whitepaperów, forów i AWS re:Post, podstawowych kontroli AWS Trusted Advisor oraz AWS Health Dashboard (dawniej Personal Health Dashboard). Nie obejmuje kontaktu z inżynierami wsparcia technicznego ani TAM.", "en": "The support plan included at no cost with every AWS account. It provides 24/7 access to customer service, documentation, whitepapers, support forums and AWS re:Post, core AWS Trusted Advisor checks, and the AWS Health Dashboard (formerly Personal Health Dashboard). It does not include access to technical support engineers or a TAM."},
{"name": "Bring Your Own License (BYOL) / Własna licencja", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 10, "pl": "Model, w którym korzystasz w AWS z licencji oprogramowania kupionych wcześniej bezpośrednio od dostawcy (np. Microsoft), m.in. na Amazon EC2 Dedicated Hosts lub w Amazon WorkSpaces. Może dać znaczne oszczędności w porównaniu z zakupem licencji od AWS. Takimi licencjami pomaga zarządzać AWS License Manager.", "en": "A model in which you use existing software licenses purchased directly from vendors (such as Microsoft) on AWS services such as Amazon EC2 Dedicated Hosts and Amazon WorkSpaces. It can result in significant cost savings compared to purchasing licenses from AWS. AWS License Manager helps you manage these licenses."},
{"name": "Business Support", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Minimalny zalecany plan dla obciążeń produkcyjnych. Dodaje pełny zestaw kontroli AWS Trusted Advisor, bezpośredni dostęp telefoniczny do zespołu wsparcia, odpowiedź poniżej 4 godzin przy zakłóceniach systemu produkcyjnego i poniżej 1 godziny, gdy system produkcyjny nie działa. Za dodatkową opłatą daje dostęp do Infrastructure Event Management; nie obejmuje TAM.", "en": "The recommended minimum tier for production workloads. It adds the full set of AWS Trusted Advisor checks, direct phone access to the support team, responses under 4 hours when a production system is impaired and under 1 hour when a production system is down. For an extra fee it provides Infrastructure Event Management; it does not include a TAM."},
{"name": "Consolidated billing / Rozliczenia skonsolidowane", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Funkcja AWS Organizations, dzięki której wiele kont AWS – konto główne (zarządzające) i połączone z nim konta podrzędne, np. według działów lub projektów – dostaje jedną wspólną fakturę i jedną metodę płatności. Konto główne widzi wydatki całej organizacji, a łączne użycie wszystkich kont liczy się do rabatów wolumenowych. Zalety: centralne zarządzanie, rabaty i lepsze bezpieczeństwo.", "en": "A feature of AWS Organizations in which multiple AWS accounts – a primary (management) account and linked subaccounts, for example per department or project – receive a single bill and use a single payment method. The primary account gets a clear view of the whole organization's spend, and combined usage across accounts counts toward volume discounts. Benefits: centralized management, discounts, and improved security."},
{"name": "Cost drivers / Główne czynniki kosztów", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Trzy podstawowe czynniki kosztów w AWS to moc obliczeniowa (compute), pamięć masowa (storage) i transfer danych wychodzących (outbound data transfer). Za moc obliczeniową płacisz za czas (np. za godzinę lub sekundę) od uruchomienia do zatrzymania zasobu, a za pamięć – za ilość przydzielonych lub używanych danych, zwykle za GB. Cena zależy też od typu usługi, konfiguracji, regionu AWS i wybranego modelu cenowego – szczegóły są na zakładce cennika każdej usługi.", "en": "The three fundamental drivers of cost in AWS are compute, storage, and outbound data transfer. Compute is billed by time (for example per hour or per second) from launch until the resource is stopped; storage is billed by the amount provisioned or used, typically per GB. Prices also depend on the service type, configuration, AWS Region, and the pricing model you choose – check each service's pricing page for details."},
{"name": "Cost optimization techniques / Techniki optymalizacji kosztów", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Sposoby obniżania kosztów omówione w kursie: dobór właściwego rozmiaru zasobów (rightsizing, np. z AWS Compute Optimizer), instancje Spot dla obciążeń odpornych na przerwy, automatyczne skalowanie, Savings Plans dla stałych obciążeń, właściwe klasy pamięci S3 (S3 Intelligent-Tiering, S3 Glacier Deep Archive) i zasady cyklu życia. Do tego repliki do odczytu i Amazon ElastiCache zamiast większej instancji bazy, punkty końcowe VPC zamiast transferu przez internet oraz usuwanie nieużywanych woluminów EBS i migawek.", "en": "Ways to reduce costs covered in the course: rightsizing resources (for example with AWS Compute Optimizer), Spot Instances for interruption-tolerant workloads, auto scaling, Savings Plans for steady workloads, the right S3 storage classes (S3 Intelligent-Tiering, S3 Glacier Deep Archive) and lifecycle policies. Also read replicas and Amazon ElastiCache instead of a larger database instance, VPC endpoints instead of internet data transfer, and deleting unused EBS volumes and snapshots."},
{"name": "Data transfer pricing / Opłaty za transfer danych", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "W większości przypadków transfer danych przychodzących (inbound) do AWS oraz transfer między usługami AWS w tym samym regionie jest bezpłatny (są wyjątki). Płacisz za transfer danych wychodzących (outbound), np. gdy użytkownicy pobierają obiekty ze statycznej strony w Amazon S3; jest on sumowany dla wszystkich usług i rozliczany za GB progowo – im więcej, tym taniej za GB. Warto ograniczać ruch między strefami dostępności (AZ) i do internetu, a punkty końcowe VPC mogą obniżyć koszty transferu.", "en": "In most cases there is no charge for inbound data transfer or for data transfer between AWS services within the same Region (with some exceptions). You pay for outbound data transfer – for example when users download objects from a static website in Amazon S3; it is aggregated across services and charged per GB in tiers, so the more you transfer, the less you pay per GB. It pays to minimize inter-Availability Zone and internet traffic, and VPC endpoints can reduce data transfer costs."},
{"name": "Developer Support", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Plan polecany do eksperymentów i testów w AWS. Do planu Basic dodaje kontakt z pomocą techniczną e-mailem: odpowiedź w ciągu 24 godzin przy ogólnych pytaniach i poniżej 12 godzin, gdy działanie systemu jest zakłócone. Ma tylko podstawowe kontrole Trusted Advisor i nie obejmuje TAM.", "en": "Recommended for experimenting or testing in AWS. On top of Basic it adds email access to technical support: responses within 24 hours for general guidance and under 12 hours when systems are impaired. It includes only core Trusted Advisor checks and no TAM."},
{"name": "Enterprise On-Ramp Support", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Plan dla obciążeń produkcyjnych i krytycznych dla biznesu. Dodaje odpowiedź poniżej 30 minut, gdy system krytyczny dla biznesu nie działa, oraz dostęp do puli technicznych opiekunów klienta (TAM), którzy zapewniają proaktywne doradztwo. Na egzaminie: „pula TAM-ów” → Enterprise On-Ramp, „dedykowany TAM” → Enterprise.", "en": "For production and business-critical workloads. It adds a response time under 30 minutes when a business-critical system is down and access to a pool of technical account managers (TAMs) who provide proactive guidance. Exam tip: pool of TAMs → Enterprise On-Ramp; designated TAM → Enterprise."},
{"name": "Enterprise Support", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Najwyższy plan, dla obciążeń krytycznych dla biznesu i dla misji (mission-critical). Zapewnia odpowiedź poniżej 15 minut, gdy taki system nie działa, dedykowanego TAM, który doradza w kwestiach architektury i operacji, oraz pełny zestaw kontroli Trusted Advisor z rekomendacjami priorytetyzowanymi przez zespół konta AWS.", "en": "The top plan, for business-critical and mission-critical workloads. It provides a response time under 15 minutes when such a system is down, a designated TAM who gives consultative architectural and operational guidance, and the full set of Trusted Advisor checks with prioritized recommendations from the AWS account team."},
{"name": "Infrastructure Event Management (IEM)", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Pomoc AWS w zaplanowaniu i przeprowadzeniu dużych wydarzeń, takich jak premiera produktu czy globalna kampania reklamowa, tak aby infrastruktura wytrzymała skok ruchu. W kursie opisana jako opcja planu Business Support za dodatkową opłatą.", "en": "AWS help with planning and running large events, such as a product launch or a global advertising campaign, so your infrastructure can handle the traffic spike. In the course it is described as an option of the Business Support plan for an extra fee."},
{"name": "Pay as you go / Płatność za faktyczne użycie", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Jedna z trzech kluczowych zasad cennika AWS: płacisz tylko za zasoby, które faktycznie zużywasz, i tylko tak długo, jak z nich korzystasz – bez opłat z góry, długoterminowych umów i skomplikowanych licencji. Pozwala dopasować się do zmieniających się potrzeb i zmniejsza ryzyko przewymiarowania lub braku pojemności. Najlepiej pasuje do zmiennych obciążeń i sytuacji, gdy nie znasz jeszcze dokładnych potrzeb.", "en": "One of the three key AWS pricing concepts: you pay only for the resources you actually consume, for as long as you use them, with no upfront costs, long-term contracts, or complex licensing. It helps you adapt to changing business needs and reduces the risk of overprovisioning or missing capacity. It suits variable workloads and situations where you are unsure of your exact needs."},
{"name": "Pay less by using more / Płać mniej, używając więcej", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Trzecia zasada cennika AWS: rabaty wolumenowe. W części usług ceny są progowe (tiered) – im więcej używasz, tym niższa cena jednostkowa, np. za GB w Amazon S3 czy za transfer danych wychodzących. Nie myl z „save when you commit” – tu nie ma zobowiązania, rabat wynika z samej skali użycia (efekt skali).", "en": "The third AWS pricing concept: volume-based discounts. For some services pricing is tiered – the more you use, the lower the per-unit price, for example per GB in Amazon S3 or for outbound data transfer. Do not confuse it with save when you commit: there is no commitment here; the discount comes from the scale of usage (economies of scale)."},
{"name": "Rightsizing / Dobór właściwego rozmiaru", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Analizowanie i dostosowywanie zasobów (np. typu i rozmiaru instancji EC2 lub RDS) do faktycznych potrzeb obciążenia, tak aby nie płacić za przewymiarowaną pojemność ani nie cierpieć z powodu zbyt małej. Jeśli instancja jest niedociążona, możesz przejść na mniejszą i tańszą. Pomaga w tym AWS Compute Optimizer; rightsizing wspiera filary optymalizacji kosztów i efektywności wydajności.", "en": "Analyzing and adjusting resources (for example EC2 or RDS instance type and size) to match the actual needs of your workload, so you neither pay for overprovisioned capacity nor suffer from underprovisioning. If an instance is underutilized, you can switch to a smaller, cheaper one. AWS Compute Optimizer helps; rightsizing supports the Cost Optimization and Performance Efficiency pillars."},
{"name": "Save when you commit / Oszczędzaj dzięki zobowiązaniu", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Druga zasada cennika AWS: zobowiązując się do określonego poziomu użycia na 1 lub 3 lata, dostajesz znaczące rabaty w porównaniu z cenami On-Demand. Przykładem są Savings Plans dla usług obliczeniowych oraz Reserved Instances. Najlepiej sprawdza się przy stabilnych, przewidywalnych obciążeniach (steady-state).", "en": "The second AWS pricing concept: by committing to a certain level of usage for 1 or 3 years, you receive significant discounts compared to On-Demand prices. Savings Plans for compute services and Reserved Instances are examples. It is ideal for steady-state, predictable workloads."},
{"name": "Tags / Tagi (alokacja kosztów)", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Tagi to metadane (pary klucz–wartość), które dodajesz do zasobów AWS, np. env=dev albo project=sklep. Ułatwiają wyszukiwanie i grupowanie powiązanych zasobów, a w AWS Budgets i AWS Cost Explorer pozwalają przypisać koszty do projektów, działów lub środowisk (cost allocation tags).", "en": "Tags are metadata (key-value pairs) that you add to AWS resources, for example env=dev or project=shop. They make it easier to find and group related resources, and in AWS Budgets and AWS Cost Explorer they let you allocate costs to projects, departments, or environments (cost allocation tags)."},
{"name": "Technical Account Manager (TAM) / Techniczny opiekun klienta", "category": "Ceny, rozliczenia i wsparcie", "kind": "pojęcie", "module": 11, "pl": "Główna osoba kontaktowa w AWS, dostępna w planach Enterprise On-Ramp (pula TAM-ów) i Enterprise (dedykowany TAM). Proaktywnie monitoruje Twoje środowisko, doradza w zakresie korzystania z usług, optymalizacji architektury i kosztów oraz łączy Cię z programami i ekspertami AWS. Plany Basic, Developer i Business nie obejmują TAM.", "en": "Your primary AWS point of contact, available in the Enterprise On-Ramp (pool of TAMs) and Enterprise (designated TAM) plans. A TAM proactively monitors your environment, advises on using services and optimizing architectures and costs, and connects you with AWS programs and experts. Basic, Developer, and Business plans do not include a TAM."},
{"name": "Assess phase / Faza oceny", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Pierwsza faza migracji: oceniasz gotowość organizacji do działania w chmurze, określasz cele biznesowe i budujesz uzasadnienie biznesowe (business case) migracji. Kluczowe narzędzie tej fazy to Migration Evaluator.", "en": "The first migration phase: you assess your organization's readiness to operate in the cloud, identify business outcomes and goals, and build the business case for migration. The key tool in this phase is Migration Evaluator."},
{"name": "AWS Application Discovery Service", "category": "Migracja i transfer danych", "kind": "usługa", "module": 12, "pl": "Usługa fazy Mobilize, która automatycznie odkrywa inwentarz serwerów on-premises i połączenia między nimi. Zbiera dane o konfiguracji, wydajności i połączeniach serwerów oraz baz danych, mapuje zależności i pomaga stworzyć szczegółowy plan migracji. Zebrane dane można integrować z AWS Migration Hub.", "en": "A Mobilize-phase service that automatically discovers on-premises server inventory and connections. It gathers configuration, performance, and connection details for servers and databases, maps dependencies, and helps create a detailed migration plan. Its data can be integrated with AWS Migration Hub."},
{"name": "AWS Application Migration Service", "category": "Migracja i transfer danych", "kind": "usługa", "module": 12, "pl": "Główne narzędzie do przenoszenia aplikacji do AWS z serwerów fizycznych, infrastruktury wirtualnej, innych chmur lub między regionami AWS. Automatyzuje migrację przy minimalnym przestoju – serwery są replikowane, a firma działa normalnie – i pozwala modernizować aplikacje w trakcie. Jedno narzędzie dla wielu typów aplikacji obniża koszty migracji.", "en": "The primary tool for moving applications to AWS from physical servers, virtual infrastructure, other clouds, or between AWS Regions. It automates migration with minimal downtime – servers are replicated while the business keeps operating normally – and lets you modernize applications during migration. One tool for many application types reduces migration costs."},
{"name": "AWS Cloud Adoption Framework (AWS CAF)", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Ramy (framework) stworzone przez AWS Professional Services, które przekazują doświadczenie i najlepsze praktyki AWS firmom przygotowującym się do migracji. Porządkują wskazówki w sześć perspektyw: biznesowe Business, People i Governance oraz techniczne Platform, Security i Operations. Każda perspektywa pomaga wykryć luki w umiejętnościach i procesach, na podstawie których powstaje AWS CAF Action Plan.", "en": "A framework created by AWS Professional Services that brings AWS experience and best practices to companies preparing to migrate. It organizes guidance into six perspectives: the business-focused Business, People, and Governance, and the technical Platform, Security, and Operations. Each perspective helps uncover gaps in skills and processes, which become inputs to an AWS CAF Action Plan."},
{"name": "AWS Database Migration Service (AWS DMS)", "category": "Migracja i transfer danych", "kind": "usługa", "module": 7, "pl": "Usługa do migracji baz danych między bazą źródłową a docelową, np. z on-premises do Amazon RDS lub Aurora. Najważniejsza zaleta: baza źródłowa działa normalnie przez cały czas migracji, więc przestój aplikacji jest minimalny. Obsługuje migracje między tymi samymi silnikami i między różnymi (np. Oracle → Aurora, wtedy razem z AWS Schema Conversion Tool), a także ciągłą replikację danych.", "en": "A service for migrating databases between a source and a target database, for example from on premises to Amazon RDS or Aurora. Its key benefit is that the source database stays fully operational during migration, minimizing application downtime. It supports migrations between the same engine and between different engines (e.g. Oracle → Aurora, together with AWS Schema Conversion Tool), as well as continuous data replication."},
{"name": "AWS DataSync", "category": "Migracja i transfer danych", "kind": "usługa", "module": 12, "pl": "Usługa do automatyzacji i przyspieszania transferu dużych ilości danych online między pamięcią on-premises a usługami pamięci AWS (np. Amazon S3, Amazon EFS). Sama obsługuje szyfrowanie, optymalizację sieci, ograniczanie przepustowości, harmonogramy, filtrowanie zadań i raporty. Według kursu wystarcza do większości migracji danych; służy też do archiwizacji zimnych danych i hybrydowych przepływów danych.", "en": "A service that automates and accelerates online transfer of large amounts of data between on-premises storage and AWS storage services (such as Amazon S3 and Amazon EFS). It handles encryption, network optimization, bandwidth throttling, scheduling, task filtering, and reporting. According to the course it does the job for the majority of data migrations; it is also used to archive cold data and manage hybrid data workflows."},
{"name": "AWS Migration and Modernization Competency Partners", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Partnerzy AWS z kompetencją w zakresie migracji i modernizacji (w ramach AWS Competency Partner Program), wyspecjalizowani w poszczególnych fazach migracji lub rodzajach pomocy. Możesz z nimi współpracować, jeśli w zespole brakuje odpowiedniej wiedzy.", "en": "AWS Partners with the Migration and Modernization Competency (part of the AWS Competency Partner Program) who specialize in specific migration phases or types of help. You can work with them if your team lacks the expertise in house."},
{"name": "AWS Migration Hub", "category": "Migracja i transfer danych", "kind": "usługa", "module": 12, "pl": "Bezpłatne, centralne miejsce do prowadzenia migracji – od odkrywania i oceny przez planowanie po realizację. Daje narzędzia, wskazówki (szablony ścieżek migracji), automatyczne rekomendacje, współpracę zespołu i śledzenie postępu wszystkich zadań. Używany w fazie Mobilize oraz Migrate and modernize, także przy modernizacji aplikacji.", "en": "A free, centralized hub for running a migration – from discovery and assessment through planning and execution. It provides tools, guidance (prescriptive journey templates), automated recommendations, team collaboration, and tracking of all migration tasks. It is used in the Mobilize and Migrate and modernize phases, including for application modernization."},
{"name": "AWS Schema Conversion Tool (AWS SCT)", "category": "Migracja i transfer danych", "kind": "usługa", "module": 12, "pl": "Narzędzie, które konwertuje schematy baz danych i obiekty kodu (procedury składowane, widoki, funkcje) z jednego silnika bazy danych na inny, np. z Oracle na Amazon Aurora PostgreSQL. Używa się go razem z AWS DMS przy migracjach heterogenicznych, czyli między różnymi silnikami.", "en": "A tool that converts database schemas and code objects (stored procedures, views, and functions) from one database engine to another, for example from Oracle to Amazon Aurora PostgreSQL. It is used together with AWS DMS for heterogeneous migrations, that is, between different engines."},
{"name": "AWS Snow Family (AWS Snowball Edge Storage Optimized)", "category": "Migracja i transfer danych", "kind": "usługa", "module": 12, "pl": "Fizyczne, wytrzymałe urządzenia AWS do migracji danych offline: urządzenie trafia do Ciebie, kopiujesz na nie dane i odsyłasz je do AWS, gdzie dane są ładowane do usług takich jak Amazon S3. Snowball Edge Storage Optimized ma szybką pamięć NVMe i upraszcza migracje wielu petabajtów. Przydaje się, gdy internet jest wolny lub niedostępny, a także do przetwarzania brzegowego (edge computing) w trudnych warunkach.", "en": "Physical, rugged AWS devices for offline data migration: the device is shipped to you, you copy data onto it and ship it back to AWS, where the data is loaded into services such as Amazon S3. Snowball Edge Storage Optimized provides high-performance NVMe storage and simplifies multi-petabyte migrations. It is useful when the internet is slow or unavailable, and for edge computing in harsh environments."},
{"name": "AWS Transfer Family", "category": "Migracja i transfer danych", "kind": "usługa", "module": 12, "pl": "W pełni zarządzana usługa bezpiecznego przesyłania plików do i z Amazon S3 oraz Amazon EFS przez protokoły SFTP, FTPS, FTP i inne. Pozwala zmodernizować istniejącą wymianę plików z pracownikami i partnerami bez utrzymywania własnych serwerów FTP. Zapewnia szyfrowanie i uwierzytelnianie oraz skaluje się automatycznie.", "en": "A fully managed service for secure file transfers into and out of Amazon S3 and Amazon EFS over SFTP, FTPS, FTP, and other protocols. It lets you modernize existing file exchange with your workforce and partners without running your own FTP servers. It provides encryption and authentication and scales automatically."},
{"name": "Business perspective (AWS CAF) / Perspektywa biznesowa", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Perspektywa biznesowa AWS CAF dba o to, by IT było zgodne z potrzebami biznesu, a inwestycje w IT przekładały się na kluczowe wyniki biznesowe. Pomaga zbudować mocne uzasadnienie biznesowe i ustalić priorytety inicjatyw chmurowych. Typowe role: menedżerowie biznesowi i finansowi, właściciele budżetów, interesariusze strategii.", "en": "The AWS CAF Business perspective ensures that IT aligns with business needs and that IT investments link to key business results. It helps create a strong business case and prioritize cloud adoption initiatives. Common roles: business managers, finance managers, budget owners, strategy stakeholders."},
{"name": "Cloud migration / Migracja do chmury", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Proces przenoszenia zasobów cyfrowych organizacji – infrastruktury IT, aplikacji i baz danych – ze środowiska on-premises (lub od innego dostawcy chmury) do chmury AWS. Wymaga planowania strategicznego, wdrożenia i bieżącego zarządzania; duże migracje odbywają się etapami. AWS dzieli ten proces na trzy fazy: ocena (Assess), mobilizacja (Mobilize) oraz migracja i modernizacja (Migrate and modernize).", "en": "The process of moving an organization's digital assets – IT resources, applications, and databases – from on-premises infrastructure (or another cloud provider) to the AWS Cloud. It involves strategic planning, implementation, and ongoing management; large migrations happen in phases. AWS divides the process into three phases: Assess, Mobilize, and Migrate and modernize."},
{"name": "Governance perspective (AWS CAF) / Perspektywa nadzoru", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Perspektywa nadzoru (governance) skupia się na umiejętnościach i procesach, które zgrywają strategię IT ze strategią biznesową, maksymalizując wartość i minimalizując ryzyko. Pomaga zarządzać inwestycjami w chmurę i mierzyć ich efekty biznesowe. Typowe role: CIO, kierownicy programów, architekci korporacyjni, analitycy biznesowi, menedżerowie portfela.", "en": "The Governance perspective focuses on the skills and processes that align IT strategy with business strategy, maximizing business value and minimizing risk. It helps manage and measure cloud investments to evaluate business outcomes. Common roles: CIO, program managers, enterprise architects, business analysts, portfolio managers."},
{"name": "Migrate and modernize phase / Faza migracji i modernizacji", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Trzecia faza migracji: każda aplikacja jest projektowana, migrowana i weryfikowana zgodnie z planem i najlepszymi praktykami. Narzędzia: AWS Application Migration Service, AWS DMS, a dla danych AWS DataSync, AWS Transfer Family i AWS Snow Family; postęp nadal śledzisz w AWS Migration Hub. Możesz działać własnymi siłami albo z partnerami AWS.", "en": "The third migration phase: each application is architected, migrated, and validated according to the plan and best practices. Tools include AWS Application Migration Service and AWS DMS, and for data AWS DataSync, AWS Transfer Family, and the AWS Snow Family; you keep tracking progress in AWS Migration Hub. You can do it in house or with AWS Partners."},
{"name": "Migration Evaluator", "category": "Migracja i transfer danych", "kind": "usługa", "module": 12, "pl": "Usługa oceny migracji używana w fazie Assess do zbudowania uzasadnienia biznesowego. Analizuje obecny stan on-premises i stan docelowy, tworzy plan gotowości do migracji z prognozą kosztów w chmurze i pokazuje kilka scenariuszy migracji. Daje też wskazówki dotyczące ponownego wykorzystania posiadanych licencji.", "en": "A migration assessment service used in the Assess phase to build the business case. It analyzes your current on-premises state and target state, develops a migration readiness plan with projected cloud costs, and shows multiple migration scenarios. It also provides insights on reusing existing software licenses."},
{"name": "Mobilize phase / Faza mobilizacji", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Druga faza migracji: tworzysz plan migracji, uzupełniasz luki w gotowości i przygotowujesz organizację. Kluczowe jest zrozumienie zależności między aplikacjami i wybór strategii migracji (7R). Typowe narzędzia: AWS Application Discovery Service i AWS Migration Hub.", "en": "The second migration phase: you create a migration plan, address gaps in readiness, and prepare the organization. Understanding application interdependencies and choosing migration strategies (the 7 Rs) is key. Typical tools: AWS Application Discovery Service and AWS Migration Hub."},
{"name": "Online and offline data transfer / Transfer danych online i offline", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Dane możesz przenieść do AWS przez sieć (online) – np. AWS DataSync, AWS Transfer Family, AWS Direct Connect, a bazy danych przez AWS DMS – albo fizycznie (offline) na urządzeniach AWS Snow Family. Offline wybiera się, gdy przepustowość jest ograniczona, w lokalizacji nie ma internetu, a Direct Connect nie wchodzi w grę, albo gdy wysyłka petabajtów przez internet trwałaby dłużej niż wysyłka urządzenia. Przy planowaniu bierz pod uwagę bezpieczeństwo, walidację danych, harmonogram i przepustowość.", "en": "You can move data to AWS over the network (online) – for example AWS DataSync, AWS Transfer Family, AWS Direct Connect, and AWS DMS for databases – or physically (offline) using AWS Snow Family devices. Offline transfer is chosen when bandwidth is limited, the location has no internet and Direct Connect is not an option, or when sending petabytes over the internet would take longer than shipping a device. Plan for security, data validation, scheduling, and bandwidth requirements."},
{"name": "Operations perspective (AWS CAF) / Perspektywa operacji", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Perspektywa operacji pomaga uruchamiać, używać, obsługiwać i przywracać obciążenia IT na poziomie uzgodnionym z interesariuszami biznesowymi. Definiuje bieżące procedury operacyjne oraz zmiany procesów i szkolenia potrzebne do wdrożenia chmury. Typowe role: menedżerowie operacji IT i wsparcia IT.", "en": "The Operations perspective helps you enable, run, use, operate, and recover IT workloads to the level agreed with business stakeholders. It defines day-to-day operating procedures and the process changes and training needed for cloud adoption. Common roles: IT operations managers, IT support managers."},
{"name": "People perspective (AWS CAF) / Perspektywa ludzi", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Perspektywa ludzi wspiera strategię zarządzania zmianą w całej organizacji. Ocenia struktury i role, nowe wymagania dotyczące umiejętności i procesów oraz luki, co pomaga zaplanować szkolenia, obsadę stanowisk i zmiany organizacyjne. Typowe role: HR, rekrutacja (staffing), menedżerowie zespołów.", "en": "The People perspective supports an organization-wide change management strategy. It evaluates organizational structures and roles, new skill and process requirements, and gaps, which helps prioritize training, staffing, and organizational changes. Common roles: human resources, staffing, people managers."},
{"name": "Platform perspective (AWS CAF) / Perspektywa platformy", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Perspektywa platformy obejmuje zasady i wzorce wdrażania nowych rozwiązań w chmurze i migracji obciążeń on-premises. Wykorzystuje modele architektury, by opisać strukturę systemów IT i szczegółowo zaprojektować środowisko docelowe. Typowe role: CTO, menedżerowie IT, architekci rozwiązań.", "en": "The Platform perspective includes principles and patterns for implementing new solutions in the cloud and migrating on-premises workloads. It uses architectural models to describe the structure of IT systems and design the target-state environment in detail. Common roles: CTO, IT managers, solutions architects."},
{"name": "Refactor (re-architect) / Przeprojektowanie", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Ponowne zaprojektowanie i przebudowa aplikacji z użyciem funkcji natywnych dla chmury – tu piszesz nowy kod. Napędza ją silna potrzeba biznesowa (nowe funkcje, skala, wydajność), trudna do osiągnięcia w obecnym środowisku. Daje największe korzyści, ale ma najwyższy koszt początkowy (planowanie i nakład pracy).", "en": "Reimagining how an application is architected and developed using cloud-native features – you write new code. It is driven by a strong business need (features, scale, performance) that is hard to achieve in the existing environment. It offers the biggest benefits but has the highest initial cost in planning and human effort."},
{"name": "Rehost (lift and shift) / Przeniesienie bez zmian", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Przeniesienie aplikacji do chmury bez zmian, zwykle przez zamianę serwerów w maszyny wirtualne. To najszybsza strategia przy dużych migracjach, które muszą szybko się skalować – wtedy większość aplikacji jest rehostowana. Nawet bez optymalizacji może dać oszczędności do 30% łącznych kosztów.", "en": "Moving applications to the cloud without changes, usually by turning existing servers into virtual machines. It is the fastest strategy for large legacy migrations that need to scale quickly – most applications are rehosted. Even without optimization it can save up to 30 percent of total costs."},
{"name": "Relocate / Zmiana lokalizacji", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Zmiana miejsca hostowania na chmurę dla aplikacji, które już działają on-premises jako maszyny wirtualne (VM) lub kontenery. Same aplikacje nie są modyfikowane – zmienia się tylko miejsce, w którym działają.", "en": "Changing the hosting location to the cloud for applications that already run on premises as virtual machines (VMs) or containers. The applications themselves are not modified – only where they run changes."},
{"name": "Replatform (lift, tinker, and shift) / Zmiana platformy", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Przeniesienie z kilkoma optymalizacjami pod chmurę, które dają wymierną korzyść, ale bez zmiany podstawowej architektury i bez pisania nowego kodu. Przykład: przeniesienie własnej bazy MySQL do Amazon RDS (albo Amazon Aurora) bez zmian w kodzie aplikacji.", "en": "Migrating with a few cloud optimizations that deliver a tangible benefit, without changing the core architecture or writing new code. Example: moving a self-managed MySQL database to Amazon RDS (or Amazon Aurora) with no application code changes."},
{"name": "Repurchase (drop and shop) / Zakup nowego rozwiązania", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Przejście z tradycyjnej licencji na model SaaS, np. zastąpienie dotychczasowego systemu CRM nowym oprogramowaniem do obsługi sprzedaży w chmurze. Często oznacza zmianę dostawcy; koszty początkowe mogą wzrosnąć, a wdrożenie nowego pakietu wymaga czasu, ale korzyści bywają duże.", "en": "Moving from a traditional license to a software-as-a-service (SaaS) model, for example replacing an existing CRM system with new cloud-based sales software. It often means changing vendors; upfront costs may increase and adopting the new package takes time, but the benefits can be substantial."},
{"name": "Retain / Zachowanie", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Pozostawienie aplikacji w środowisku źródłowym („stays where it lays”) – np. aplikacji krytycznych, które wymagałyby dużej przebudowy przed migracją, albo takich, które wkrótce zostaną wycofane. Migruj tylko to, co ma sens biznesowy.", "en": "Keeping applications in the source environment (stays where it lays) – for example business-critical applications that would need major refactoring before migration, or ones about to be deprecated. Migrate only what makes business sense."},
{"name": "Retire / Wycofanie", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Wyłączenie aplikacji, które nie są już potrzebne. Firmy często odkrywają, że ponad 10% obciążeń w ich portfelu IT nie jest używanych – migracja to dobra okazja, by je wygasić i zaoszczędzić koszty oraz pracę.", "en": "Removing applications that are no longer needed. Companies often find that more than 10 percent of the workloads in their IT portfolio are unused – a migration is a good opportunity to end-of-life them and save cost and effort."},
{"name": "Security perspective (AWS CAF) / Perspektywa bezpieczeństwa", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Perspektywa bezpieczeństwa dba o to, by organizacja spełniała cele bezpieczeństwa w zakresie widoczności, audytowalności, kontroli i zwinności. Porządkuje wybór i wdrażanie mechanizmów kontroli bezpieczeństwa. Typowe role: CISO, menedżerowie i analitycy bezpieczeństwa IT.", "en": "The Security perspective ensures the organization meets security objectives for visibility, auditability, control, and agility. It structures the selection and implementation of security controls. Common roles: CISO, IT security managers, IT security analysts."},
{"name": "Seven migration strategies (7 Rs) / Siedem strategii migracji", "category": "Migracja i transfer danych", "kind": "pojęcie", "module": 12, "pl": "Siedem typowych ścieżek przeniesienia aplikacji do chmury: Relocate, Rehost, Replatform, Refactor, Repurchase, Retain i Retire. Wybór zależy od złożoności aplikacji, celów biznesowych, czasu i dostępnych zasobów; zwykle organizacja łączy kilka strategii w swoim portfelu aplikacji. Retain i Retire nie obejmują faktycznej migracji.", "en": "Seven common paths for moving applications to the cloud: Relocate, Rehost, Replatform, Refactor, Repurchase, Retain, and Retire. The choice depends on application complexity, business goals, time constraints, and available resources; organizations usually combine several strategies across their application portfolio. Retain and Retire do not involve actually migrating anything."},
{"name": "AWS Architecture Center", "category": "Architektura (Well-Architected)", "kind": "pojęcie", "module": 13, "pl": "Zbiór architektur referencyjnych, diagramów i najlepszych praktyk do budowania bezpiecznych, wydajnych i skalowalnych rozwiązań w AWS. Uzupełnia go AWS Architecture Blog z artykułami technicznymi.", "en": "A collection of reference architectures, diagrams, and best practices for building secure, efficient, and scalable solutions on AWS. It is complemented by the AWS Architecture Blog with technical insights."},
{"name": "AWS Well-Architected Framework", "category": "Architektura (Well-Architected)", "kind": "pojęcie", "module": 13, "pl": "Zbiór najlepszych praktyk AWS, który daje spójne podejście do projektowania i oceny architektur – bezpiecznych, wydajnych, odpornych i efektywnych. Opiera się na sześciu filarach: doskonałość operacyjna, bezpieczeństwo, niezawodność, efektywność wydajności, optymalizacja kosztów i zrównoważony rozwój. Obciążenia ocenia się względem frameworka w AWS Well-Architected Tool.", "en": "A set of AWS best practices that provides a consistent approach to designing and evaluating architectures that are secure, high-performing, resilient, and efficient. It is built on six pillars: Operational Excellence, Security, Reliability, Performance Efficiency, Cost Optimization, and Sustainability. Workloads are reviewed against it with the AWS Well-Architected Tool."},
{"name": "AWS Well-Architected Tool (AWS WA Tool)", "category": "Architektura (Well-Architected)", "kind": "usługa", "module": 13, "pl": "Bezpłatna, samoobsługowa usługa do oceny i ulepszania obciążeń względem sześciu filarów Well-Architected. Definiujesz obciążenie (workload), odpowiadasz na pytania dla każdego filaru (niepasujące możesz oznaczyć jako nie dotyczące), a narzędzie generuje raport z wykrytymi problemami i sposobami ich naprawy według najlepszych praktyk. Obsługuje kamienie milowe (milestones), niestandardowe soczewki (lenses) i współpracę zespołu.", "en": "A free, self-service tool for assessing and improving workloads against the six Well-Architected pillars. You define a workload, answer questions for each pillar (marking those that don't apply), and the tool generates a report of potential issues with remediation guidance based on best practices. It supports milestone tracking, custom lenses, and team collaboration."},
{"name": "Cost Optimization pillar / Filar optymalizacji kosztów", "category": "Architektura (Well-Architected)", "kind": "pojęcie", "module": 13, "pl": "Filar kontrolowania i ograniczania wydatków przez rozsądne przydzielanie zasobów i zarządzanie nimi. Przykłady: przejście na mniejszą instancję, gdy obecna jest niedociążona, wyłączanie niepotrzebnych zasobów, instancje Spot dla zmiennego ruchu, Savings Plans dla stałych obciążeń oraz śledzenie kosztów w AWS Budgets i AWS Cost Explorer.", "en": "The pillar for controlling and reducing spending through smart provisioning and resource management. Examples: switching to a smaller instance when the current one is underutilized, deprovisioning services you don't need, Spot Instances for variable traffic, Savings Plans for steady workloads, and tracking costs with AWS Budgets and AWS Cost Explorer."},
{"name": "Lens / Soczewka (AWS WA Tool)", "category": "Architektura (Well-Architected)", "kind": "pojęcie", "module": 13, "pl": "Soczewka to zestaw pytań i najlepszych praktyk w AWS Well-Architected Tool dopasowany do konkretnej technologii, branży lub potrzeb organizacji. Niestandardowe soczewki (custom lenses) pozwalają prowadzić przeglądy architektury według własnych kryteriów, obok standardowego frameworka.", "en": "A lens is a set of questions and best practices in the AWS Well-Architected Tool tailored to a specific technology, industry, or organizational need. Custom lenses let you run architecture reviews against your own criteria alongside the standard framework."},
{"name": "Operational Excellence pillar / Filar doskonałości operacyjnej", "category": "Architektura (Well-Architected)", "kind": "pojęcie", "module": 13, "pl": "Filar skupiony na uruchamianiu i monitorowaniu systemów tak, by dostarczały wartość biznesową, oraz na ciągłym doskonaleniu procesów. Obejmuje automatyzację (np. wdrożenia przez potoki CI/CD, infrastruktura jako kod), monitorowanie, skuteczne reagowanie na zdarzenia i mechanizmy samonaprawy, np. automatyczne wycofanie zmian (auto-rollback).", "en": "The pillar focused on running and monitoring systems to deliver business value and continuously improving processes. It covers automation (for example deployments through CI/CD pipelines and infrastructure as code), monitoring, responding to events effectively, and self-healing mechanisms such as auto-rollback."},
{"name": "Performance Efficiency pillar / Filar efektywności wydajności", "category": "Architektura (Well-Architected)", "kind": "pojęcie", "module": 13, "pl": "Filar efektywnego wykorzystania zasobów: dobieranie odpowiednich zasobów do zadania (np. rightsizing instancji EC2 i RDS z AWS Compute Optimizer) i dostosowywanie ich, gdy potrzeby się zmieniają. Przykłady: AWS Lambda dla zadań sterowanych zdarzeniami, Amazon CloudFront do szybkiego dostarczania treści na całym świecie.", "en": "The pillar for using resources efficiently: selecting the right resources for the job (for example rightsizing EC2 and RDS instances with AWS Compute Optimizer) and adjusting them as needs evolve. Examples: AWS Lambda for event-driven tasks and Amazon CloudFront for fast global content delivery."},
{"name": "Reliability pillar / Filar niezawodności", "category": "Architektura (Well-Architected)", "kind": "pojęcie", "module": 13, "pl": "Filar odporności: planowanie odtwarzania po awarii (recovery), zdolność systemu do wytrzymania awarii i szybkiego powrotu do działania oraz dostosowywanie się do zmieniających się potrzeb biznesu i klientów. Przykłady: wdrożenie w wielu strefach dostępności (AZ), monitorowanie w Amazon CloudWatch i automatyczne akcje naprawcze.", "en": "The pillar for resilience: recovery planning, the ability of systems to withstand failures and recover quickly, and adapting systems to changing business and customer demands. Examples: deploying across multiple Availability Zones, monitoring with Amazon CloudWatch, and automated recovery actions."},
{"name": "Security pillar / Filar bezpieczeństwa", "category": "Architektura (Well-Architected)", "kind": "pojęcie", "module": 13, "pl": "Filar ochrony systemów i danych dzięki najlepszym praktykom: zasada najmniejszych uprawnień, integralność danych, szyfrowanie danych w spoczynku i w tranzycie, precyzyjna kontrola dostępu i regularne łatanie systemów. Bezpieczeństwo ma być wbudowane w rozwiązanie od początku.", "en": "The pillar for protecting systems and data through best practices: the principle of least privilege, data integrity, encryption of data at rest and in transit, fine-grained access controls, and regular patching. Security should be built into the solution from the start."},
{"name": "Sustainability pillar / Filar zrównoważonego rozwoju", "category": "Architektura (Well-Architected)", "kind": "pojęcie", "module": 13, "pl": "Filar projektowania energooszczędnych systemów i ograniczania wpływu na środowisko. Zachęca do unikania stale włączonych zasobów, gdy nie są potrzebne (np. AWS Lambda zamiast ciągle działającej instancji EC2, mniejsza instancja RDS), korzystania z usług serverless i elastycznych oraz eliminowania marnotrawstwa – np. na podstawie AWS Cost and Usage Report. Obniża to jednocześnie koszty i emisje.", "en": "The pillar for designing energy-efficient systems and minimizing environmental impact. It encourages avoiding always-on resources you don't need (for example AWS Lambda instead of an always-on EC2 instance, or a smaller RDS instance), using serverless and elastic services, and eliminating waste – for example based on the AWS Cost and Usage Report. This lowers both costs and emissions."},
{"name": "Amazon AppStream 2.0", "category": "Usługi specjalistyczne", "kind": "usługa", "module": 13, "pl": "W pełni zarządzana usługa strumieniowania aplikacji z chmury na dowolne zgodne urządzenie, także aplikacji desktopowych udostępnianych jak SaaS bez zmian w kodzie. Użytkownicy dostają natychmiastowy dostęp do wymagającego oprogramowania bez lokalnej instalacji i mocnego sprzętu. Różnica: AppStream 2.0 strumieniuje pojedyncze aplikacje, a WorkSpaces daje cały pulpit.", "en": "A fully managed service that streams applications from the cloud to any compatible device, including desktop applications delivered like SaaS without code changes. Users get instant access to powerful software without local installation or high-end hardware. Difference: AppStream 2.0 streams individual applications, while WorkSpaces provides a full desktop."},
{"name": "Amazon Connect", "category": "Usługi specjalistyczne", "kind": "usługa", "module": 13, "pl": "Oparta na AI, chmurowa usługa centrum kontaktowego (contact center) do szybkiego uruchomienia skalowalnej obsługi klienta. Zapewnia routing i nagrywanie połączeń, interaktywne menu głosowe (IVR), czat i analitykę oraz integruje się z innymi usługami AWS – np. z AWS Lambda, by zaproponować oddzwonienie przy długim czasie oczekiwania.", "en": "An AI-powered, cloud-based contact center service for quickly setting up a scalable customer service operation. It provides call routing and recording, interactive voice response (IVR), chat, and analytics, and integrates with other AWS services – for example with AWS Lambda to offer callbacks during long wait times."},
{"name": "Amazon Simple Email Service (Amazon SES)", "category": "Usługi specjalistyczne", "kind": "usługa", "module": 13, "pl": "Skalowalna i ekonomiczna usługa wysyłania e-maili, którą można zintegrować z dowolną aplikacją. Służy do automatycznej wysyłki dużych wolumenów wiadomości transakcyjnych (np. potwierdzeń zamówień) i marketingowych (newsletterów, promocji).", "en": "A scalable, cost-effective email service that can be integrated into any application. It is used for automated, high-volume sending of transactional emails (such as order confirmations) and marketing emails (newsletters, promotions)."},
{"name": "Amazon WorkSpaces", "category": "Usługi specjalistyczne", "kind": "usługa", "module": 13, "pl": "W pełni zarządzana usługa wirtualnych pulpitów (VDI) w chmurze. Pracownicy bezpiecznie korzystają ze swojego środowiska pracy z dowolnego urządzenia z internetem, tak jak z komputera w biurze, a firma zyskuje opłacalność i łatwą administrację.", "en": "A fully managed cloud-based virtual desktop (VDI) service. Employees securely access their work environment from any internet-connected device, just like an office computer, while the company benefits from cost efficiency and easy administration."},
{"name": "Amazon WorkSpaces Secure Browser (formerly Amazon WorkSpaces Web)", "category": "Usługi specjalistyczne", "kind": "usługa", "module": 13, "pl": "W pełni zarządzana, zdalna przeglądarka firmowa – lżejsze rozwiązanie dla osób, które potrzebują tylko aplikacji webowych. Zapewnia chronione środowisko dostępu do prywatnych stron, aplikacji SaaS i publicznego internetu bez instalowania specjalnego oprogramowania klienckiego, utrzymywania infrastruktury czy VPN.", "en": "A fully managed remote enterprise browser – a lighter option for people who only need web-based applications. It provides a protected environment for accessing private websites, SaaS applications, and the public internet without specialized client software, infrastructure, or VPN connections."},
{"name": "AWS Amplify", "category": "Usługi specjalistyczne", "kind": "usługa", "module": 13, "pl": "Usługa upraszczająca tworzenie, wdrażanie i zarządzanie bezpiecznymi, skalowalnymi aplikacjami full-stack (frontend i backend), webowymi i mobilnymi. Pozwala szybko dodać uwierzytelnianie, API, przechowywanie danych i hosting przy minimalnym zarządzaniu infrastrukturą.", "en": "A service that streamlines developing, deploying, and managing secure, scalable full-stack (frontend and backend) web and mobile applications. It lets you quickly add authentication, APIs, storage, and hosting with minimal infrastructure management."},
{"name": "AWS AppSync", "category": "Usługi specjalistyczne", "kind": "usługa", "module": 13, "pl": "W pełni zarządzana usługa GraphQL. Pozwala stworzyć jedno API GraphQL, które bezpiecznie pobiera, modyfikuje i łączy dane z wielu źródeł, łącząc aplikacje frontendowe z danymi backendu. GraphQL to język zapytań do API, w którym klient pobiera dokładnie te dane, których potrzebuje.", "en": "A fully managed GraphQL service. It lets you create a single GraphQL API that securely accesses, manipulates, and combines data from multiple data sources, connecting frontend applications with backend data. GraphQL is a query language for APIs in which clients request only the specific data they need."},
{"name": "AWS CodeBuild", "category": "Usługi specjalistyczne", "kind": "usługa", "module": 13, "pl": "W pełni zarządzana usługa ciągłej integracji (CI), która kompiluje kod źródłowy, uruchamia testy i tworzy pakiety gotowe do wdrożenia. Skaluje się automatycznie, a płacisz tylko za czas budowania – nie musisz utrzymywać własnych serwerów buildów.", "en": "A fully managed continuous integration (CI) service that compiles source code, runs tests, and produces software packages ready for deployment. It scales automatically, and you pay only for the build time you use – no build servers to maintain."},
{"name": "AWS CodePipeline", "category": "Usługi specjalistyczne", "kind": "usługa", "module": 13, "pl": "W pełni zarządzana usługa CI/CD, która automatyzuje etapy budowania, testowania i wdrażania w procesie wydawania oprogramowania. Monitoruje repozytorium i po każdej zmianie uruchamia kolejne kroki, przenosząc kod od rozwoju do produkcji bez przydzielania serwerów.", "en": "A fully managed CI/CD service that automates the build, test, and deploy phases of your release process. It monitors your repository and, on each change, kicks off the steps that take code from development to production without provisioning servers."},
{"name": "AWS IoT Core", "category": "Usługi specjalistyczne", "kind": "usługa", "module": 13, "pl": "Zarządzana usługa chmurowa do bezpiecznego łączenia urządzeń fizycznych (IoT) z aplikacjami w chmurze. Upraszcza pobieranie i przetwarzanie danych z urządzeń oraz reagowanie na nie; połączenia są chronione wzajemnym uwierzytelnianiem i szyfrowaniem end-to-end, a do wyboru jest kilka protokołów komunikacji. Przykłady: inteligentne kamery, karmniki dla zwierząt, systemy nawadniania.", "en": "A managed cloud service for securely connecting physical (IoT) devices with cloud applications. It streamlines ingesting, processing, and acting on device data; connections are secured with mutual authentication and end-to-end encryption, and several communication protocols are supported. Examples: smart security cameras, pet feeders, irrigation systems."},
{"name": "AWS X-Ray", "category": "Usługi specjalistyczne", "kind": "usługa", "module": 13, "pl": "Usługa śledzenia (tracing), debugowania i analizy wydajności aplikacji, zwłaszcza rozproszonych i serverless. Śledzi żądania przechodzące przez kolejne komponenty (np. API Gateway → Lambda → DynamoDB) i wizualnie pokazuje, gdzie powstają wąskie gardła i błędy. Na egzaminie: „prześledź żądanie przez mikroserwisy” → X-Ray (metryki i logi → CloudWatch).", "en": "A service for tracing, debugging, and analyzing the performance of applications, especially distributed and serverless ones. It traces requests as they move through components (for example API Gateway → Lambda → DynamoDB) and visually shows where bottlenecks and errors occur. Exam tip: trace a request across microservices → X-Ray (metrics and logs → CloudWatch)."},
{"name": "CI/CD (continuous integration / continuous delivery) / Ciągła integracja i dostarczanie", "category": "Usługi specjalistyczne", "kind": "pojęcie", "module": 13, "pl": "Praktyka automatycznego integrowania, testowania i wdrażania zmian w kodzie, gdy tylko trafią do repozytorium – dzięki potokom (pipelines) oprogramowanie jest dostarczane szybko i niezawodnie. W AWS realizują to m.in. AWS CodePipeline (orkiestracja potoku) i AWS CodeBuild (budowanie i testy).", "en": "The practice of automatically integrating, testing, and deploying code changes as soon as they are committed to a repository – pipelines deliver software quickly and reliably. On AWS this is done with services such as AWS CodePipeline (pipeline orchestration) and AWS CodeBuild (build and test)."},
{"name": "End-user computing / Obsługa stanowisk użytkowników końcowych", "category": "Usługi specjalistyczne", "kind": "pojęcie", "module": 13, "pl": "Kategoria usług, dzięki którym dział IT zapewnia pracownikom zdalny dostęp do wirtualnych pulpitów i aplikacji. W AWS to m.in. Amazon WorkSpaces (cały pulpit), Amazon AppStream 2.0 (strumieniowanie aplikacji) i Amazon WorkSpaces Secure Browser (tylko aplikacje webowe).", "en": "A category of services that IT departments use to give employees remote access to virtual desktops and applications. On AWS these include Amazon WorkSpaces (full desktop), Amazon AppStream 2.0 (application streaming), and Amazon WorkSpaces Secure Browser (web apps only)."},
{"name": "Internet of Things (IoT) / Internet rzeczy", "category": "Usługi specjalistyczne", "kind": "pojęcie", "module": 13, "pl": "Sieć połączonych urządzeń fizycznych z czujnikami i oprogramowaniem, które zbierają dane i wymieniają je przez internet. Urządzenia można zdalnie monitorować i sterować nimi, by zwiększać efektywność i tworzyć nowe usługi. W AWS do łączenia urządzeń IoT z chmurą służy AWS IoT Core.", "en": "A network of connected physical devices with embedded sensors and software that collect and exchange data over the internet. Devices can be monitored and controlled remotely to improve efficiency and enable new services. On AWS, AWS IoT Core connects IoT devices to the cloud."}
];
